{
  "name": "OmniChat SaaS - Smart AI Support Widget",
  "description": "A comprehensive SaaS platform that allows businesses to embed a smart AI chat widget on their websites. It features a knowledge base system where users can upload documents to train the AI to answer customer queries automatically.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum View {
  DASHBOARD = 'dashboard',
  KNOWLEDGE_BASE = 'knowledge_base',
  WIDGET_CONFIG = 'widget_config',
  ANALYTICS = 'analytics',
  INTEGRATION = 'integration'
}

export interface Document {
  id: string;
  name: string;
  content: string;
  type: 'file' | 'url' | 'text';
  status: 'indexed' | 'processing';
  createdAt: number;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface WidgetSettings {
  primaryColor: string;
  botName: string;
  welcomeMessage: string;
  position: 'right' | 'left';
  avatarUrl: string;
}

export interface AnalyticsData {
  date: string;
  queries: number;
  solved: number;
  unsolved: number;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Document } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getChatResponse = async (
  userInput: string,
  history: { role: 'user' | 'model', parts: { text: string }[] }[],
  knowledgeBase: Document[],
  botName: string
): Promise<string> => {
  // Combine all indexed document contents to create the knowledge context
  const context = knowledgeBase
    .filter(doc => doc.status === 'indexed')
    .map(doc => `[Document: ${doc.name}]\n${doc.content}`)
    .join('\n\n');

  const systemInstruction = `
    You are a professional customer support AI assistant named "${botName}". 
    Your primary job is to answer customer questions based ONLY on the provided Knowledge Base context.

    KNOWLEDGE BASE CONTEXT:
    ${context || "No documents uploaded yet. Be helpful but general about the service."}

    GUIDELINES:
    1. Be polite, concise, and professional.
    2. If the answer is in the Knowledge Base, use it.
    3. If the answer is NOT in the context, politely inform the user that you don't have that information and suggest they contact human support.
    4. Do not invent facts.
    5. Always format your output in a clean, readable way using Markdown if necessary.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { role: 'user', parts: [{ text: userInput }] }
      ],
      config: {
        systemInstruction,
        temperature: 0.7,
        topP: 0.8,
        topK: 40,
      },
    });

    return response.text || "I'm sorry, I couldn't process that request.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Our AI is currently taking a short break. Please try again in a moment.";
  }
};

import React, { useState } from 'react';
import { Document } from '../types';

interface Props {
  documents: Document[];
  onAddDocument: (doc: Document) => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ documents, onAddDocument, onDeleteDocument }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = () => {
    if (!newDocName || !newDocText) return;
    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: newDocName,
      content: newDocText,
      type: 'text',
      status: 'indexed',
      createdAt: Date.now(),
    };
    onAddDocument(doc);
    setNewDocName('');
    setNewDocText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    // Simulate parsing file
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      setTimeout(() => {
        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: 'file',
          status: 'indexed',
          createdAt: Date.now(),
        };
        onAddDocument(doc);
        setIsUploading(false);
      }, 1500);
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Knowledge Base</h2>
          <p className="text-gray-500">Upload documents or add text to train your support AI.</p>
        </div>
        <div className="flex space-x-2">
           <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center">
            <i className="fas fa-upload mr-2"></i>
            Upload File
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Name</th>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Type</th>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Status</th>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {documents.map(doc => (
                  <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <i className={`fas ${doc.type === 'file' ? 'fa-file-alt' : 'fa-align-left'} text-gray-400 mr-3`}></i>
                        <span className="font-medium">{doc.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-xs font-medium px-2 py-1 bg-gray-100 rounded text-gray-600 capitalize">{doc.type}</span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="flex items-center text-xs font-semibold text-green-600">
                        <span className="w-1.5 h-1.5 bg-green-600 rounded-full mr-2"></span>
                        {doc.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => onDeleteDocument(doc.id)}
                        className="text-red-400 hover:text-red-600 transition-colors"
                      >
                        <i className="fas fa-trash"></i>
                      </button>
                    </td>
                  </tr>
                ))}
                {documents.length === 0 && (
                  <tr>
                    <td colSpan={4} className="px-6 py-12 text-center text-gray-400">
                      <i className="fas fa-folder-open text-4xl mb-4"></i>
                      <p>No documents found. Start by uploading one!</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="font-bold mb-4 flex items-center">
              <i className="fas fa-keyboard text-blue-600 mr-2"></i>
              Add Manual Text
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Document Title</label>
                <input 
                  type="text" 
                  value={newDocName}
                  onChange={(e) => setNewDocName(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="e.g. Refund Policy"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Content</label>
                <textarea 
                  rows={6}
                  value={newDocText}
                  onChange={(e) => setNewDocText(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                  placeholder="Paste your FAQ or documentation here..."
                ></textarea>
              </div>
              <button 
                onClick={handleManualAdd}
                disabled={!newDocName || !newDocText}
                className="w-full bg-gray-900 text-white py-2 rounded-lg font-medium hover:bg-gray-800 transition-colors disabled:opacity-50"
              >
                Index Knowledge
              </button>
            </div>
          </div>
        </div>
      </div>

      {isUploading && (
        <div className="fixed inset-0 bg-black/20 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white p-8 rounded-2xl shadow-xl flex flex-col items-center">
            <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
            <p className="font-bold text-lg">Processing Document...</p>
            <p className="text-gray-500 text-sm">AI is indexing the content for your bot.</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default KnowledgeBase;

