import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

// Cấu hình lưu trữ tệp tin
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
const upload = multer({ storage });

app.use(cors());
app.use(express.json());

// "Database" đơn giản bằng file JSON
const DB_FILE = './db.json';
const initDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ users: [], documents: [] }));
  }
};
initDB();

const getDB = () => JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
const saveDB = (data: any) => fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));

// API: Đăng nhập
app.post('/api/login', (email, password) => {
  // Demo đơn giản
  if (email === 'admin@omnichat.io' && password === '123456') {
    return { success: true, user: { email, role: 'admin' } };
  }
  return { success: false };
});

// API: Lấy danh sách tài liệu
app.get('/api/documents', (req, res) => {
  const db = getDB();
  res.json(db.documents);
});

// API: Thêm tài liệu văn bản
app.post('/api/documents/text', (req, res) => {
  const { name, content } = req.body;
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    name,
    content,
    type: 'text',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Upload tệp tin
app.post('/api/documents/upload', upload.single('file'), (req, res) => {
  if (!req.file) return res.status(400).send('No file uploaded.');

  const content = fs.readFileSync(req.file.path, 'utf-8');
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    name: req.file.originalname,
    content: content,
    path: req.file.path,
    type: 'file',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Xóa tài liệu
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) {
    fs.unlinkSync(doc.path);
  }
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});

// API: Chat với AI (Xử lý phía server để bảo mật API Key)
app.post('/api/chat', async (req, res) => {
  const { message, history, botName } = req.body;
  const db = getDB();
  const apiKey = process.env.API_KEY;

  if (!apiKey) return res.status(500).json({ error: "Thiếu API KEY trên server" });

  const ai = new GoogleGenAI({ apiKey });
  const context = db.documents.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');

  const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy dùng kiến thức sau: ${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: message }] }],
      config: { systemInstruction }
    });
    res.json({ text: response.text });
  } catch (error) {
    res.status(500).json({ error: "Lỗi AI" });
  }
});

app.listen(PORT, () => {
  console.log(`Backend server running at http://localhost:${PORT}`);
});

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import Login from './components/Login';
import { View, Document, WidgetSettings } from './types';

const API_BASE = 'http://localhost:3001/api';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);

  // Tải dữ liệu từ Backend khi khởi động
  useEffect(() => {
    const savedUser = localStorage.getItem('omnichat_user');
    if (savedUser) {
      setIsLoggedIn(true);
      setCurrentUser(savedUser);
      fetchDocuments();
    }
  }, []);

  const fetchDocuments = async () => {
    try {
      const res = await fetch(`${API_BASE}/documents`);
      const data = await res.json();
      setDocuments(data);
    } catch (e) {
      console.error("Không thể kết nối Backend");
    }
  };

  const handleLogin = (email: string) => {
    setIsLoggedIn(true);
    setCurrentUser(email);
    localStorage.setItem('omnichat_user', email);
    fetchDocuments();
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user');
  };

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi là trợ lý AI thông minh, tôi có thể giúp gì cho bạn hôm nay?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  const addDocument = (doc: Document) => {
    setDocuments(prev => [...prev, doc]);
  };

  const deleteDocument = async (id: string) => {
    await fetch(`${API_BASE}/documents/${id}`, { method: 'DELETE' });
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const getViewTitle = (view: View) => {
    switch (view) {
      case View.DASHBOARD: return 'Bảng điều khiển';
      case View.KNOWLEDGE_BASE: return 'Kho tri thức';
      case View.WIDGET_CONFIG: return 'Cấu hình Widget';
      case View.INTEGRATION: return 'Nhúng vào Website';
      case View.DEPLOYMENT_GUIDE: return 'Cài đặt & Deploy';
      case View.ANALYTICS: return 'Lịch sử chat';
      default: return '';
    }
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} onLogout={handleLogout} />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-8 z-10 shrink-0">
          <div className="flex items-center space-x-2">
            <h1 className="text-sm font-bold text-gray-500 uppercase tracking-widest">
              {getViewTitle(currentView)}
            </h1>
          </div>
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2">
                <span className="text-sm font-medium text-blue-600 bg-blue-50 px-3 py-1 rounded-full border border-blue-100">
                  <i className="fas fa-server mr-2"></i>
                  Backend Online
                </span>
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 max-w-7xl mx-auto w-full">
          {currentView === View.DASHBOARD && <Dashboard />}
          {currentView === View.KNOWLEDGE_BASE && (
            <KnowledgeBase 
              documents={documents} 
              onAddDocument={addDocument} 
              onDeleteDocument={deleteDocument} 
            />
          )}
          {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={setSettings} />}
          {currentView === View.INTEGRATION && <Integration />}
          {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
          {currentView === View.ANALYTICS && (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 py-20">
              <i className="fas fa-history text-6xl mb-4"></i>
              <h2 className="text-xl font-bold">Lịch sử hội thoại thực tế</h2>
            </div>
          )}
        </div>

        <div className="hidden md:block">
          <ChatWidget settings={settings} knowledgeBase={documents} />
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Document } from '../types';

const API_BASE = 'http://localhost:3001/api';

interface Props {
  documents: Document[];
  onAddDocument: (doc: Document) => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ documents, onAddDocument, onDeleteDocument }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;

    setIsUploading(true);
    const res = await fetch(`${API_BASE}/documents/text`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: newDocName, content: newDocText })
    });
    const doc = await res.json();
    onAddDocument(doc);
    setNewDocName('');
    setNewDocText('');
    setIsUploading(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);

    const res = await fetch(`${API_BASE}/documents/upload`, {
      method: 'POST',
      body: formData
    });
    const doc = await res.json();
    onAddDocument(doc);
    setIsUploading(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Kho tri thức (Server Storage)</h2>
          <p className="text-gray-500">Tài liệu được lưu an toàn tại thư mục /uploads trên server.</p>
        </div>
        <div className="flex space-x-2">
           <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center">
            <i className="fas fa-upload mr-2"></i>
            Tải tệp lên Server
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Tên tài liệu</th>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Loại</th>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Trạng thái</th>
                  <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {documents.map(doc => (
                  <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <i className={`fas ${doc.type === 'file' ? 'fa-file-alt' : 'fa-align-left'} text-gray-400 mr-3`}></i>
                        <span className="font-medium">{doc.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-xs font-medium px-2 py-1 bg-gray-100 rounded text-gray-600 capitalize">
                        {doc.type === 'file' ? 'Tệp tin' : 'Văn bản'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="flex items-center text-xs font-semibold text-green-600">
                        <i className="fas fa-database mr-2"></i>
                        Đã lưu Server
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => onDeleteDocument(doc.id)}
                        className="text-red-400 hover:text-red-600 transition-colors"
                      >
                        <i className="fas fa-trash"></i>
                      </button>
                    </td>
                  </tr>
                ))}
                {documents.length === 0 && (
                  <tr>
                    <td colSpan={4} className="px-6 py-12 text-center text-gray-400">
                      <i className="fas fa-folder-open text-4xl mb-4"></i>
                      <p>Kho tri thức trên server đang trống.</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="font-bold mb-4 flex items-center">
              <i className="fas fa-keyboard text-blue-600 mr-2"></i>
              Thêm trực tiếp
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tiêu đề</label>
                <input 
                  type="text" 
                  value={newDocName}
                  onChange={(e) => setNewDocName(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nội dung</label>
                <textarea 
                  rows={6}
                  value={newDocText}
                  onChange={(e) => setNewDocText(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                ></textarea>
              </div>
              <button 
                onClick={handleManualAdd}
                disabled={!newDocName || !newDocText || isUploading}
                className="w-full bg-gray-900 text-white py-2 rounded-lg font-medium hover:bg-gray-800 transition-colors disabled:opacity-50"
              >
                {isUploading ? 'Đang lưu...' : 'Lưu lên Server'}
              </button>
            </div>
          </div>
        </div>
      </div>

      {isUploading && (
        <div className="fixed inset-0 bg-black/20 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white p-8 rounded-2xl shadow-xl flex flex-col items-center">
