import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import Login from './components/Login';
import { View, Document, WidgetSettings } from './types';

const API_BASE = 'http://localhost:3001/api';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('omnichat_user');
    if (savedUser) {
      setIsLoggedIn(true);
      setCurrentUser(savedUser);
      fetchDocuments();
    }
  }, []);

  const fetchDocuments = async () => {
    try {
      const res = await fetch(`${API_BASE}/documents`);
      const data = await res.json();
      setDocuments(data);
    } catch (e) {
      console.error("Không thể kết nối Backend");
    }
  };

  const handleLogin = (email: string) => {
    setIsLoggedIn(true);
    setCurrentUser(email);
    localStorage.setItem('omnichat_user', email);
    fetchDocuments();
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user');
  };

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi là trợ lý AI thông minh, tôi có thể giúp gì cho bạn hôm nay?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  const addDocument = (doc: Document) => {
    setDocuments(prev => [...prev, doc]);
  };

  const deleteDocument = async (id: string) => {
    await fetch(`${API_BASE}/documents/${id}`, { method: 'DELETE' });
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const getViewTitle = (view: View) => {
    switch (view) {
      case View.DASHBOARD: return 'Bảng điều khiển';
      case View.KNOWLEDGE_BASE: return 'Kho tri thức';
      case View.WIDGET_CONFIG: return 'Cấu hình Widget';
      case View.INTEGRATION: return 'Nhúng vào Website';
      case View.DEPLOYMENT_GUIDE: return 'Cài đặt & Deploy';
      case View.ANALYTICS: return 'Lịch sử chat';
      default: return '';
    }
  };

  // Đóng menu mobile khi chuyển view
  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50 relative">
      {/* Overlay cho mobile khi mở menu */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden transition-opacity"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 z-30 shrink-0">
          <div className="flex items-center space-x-3">
            <button 
              onClick={() => setIsMobileMenuOpen(true)}
              className="lg:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-lg"
            >
              <i className="fas fa-bars text-xl"></i>
            </button>
            <h1 className="text-xs lg:text-sm font-bold text-gray-500 uppercase tracking-widest truncate">
              {getViewTitle(currentView)}
            </h1>
          </div>
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2">
                <span className="text-[10px] lg:text-sm font-medium text-blue-600 bg-blue-50 px-2 lg:px-3 py-1 rounded-full border border-blue-100">
                  <i className="fas fa-server mr-1 lg:mr-2"></i>
                  <span className="hidden sm:inline">Backend Online</span>
                  <span className="sm:hidden">Online</span>
                </span>
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 max-w-7xl mx-auto w-full">
          {currentView === View.DASHBOARD && <Dashboard />}
          {currentView === View.KNOWLEDGE_BASE && (
            <KnowledgeBase 
              documents={documents} 
              onAddDocument={addDocument} 
              onDeleteDocument={deleteDocument} 
            />
          )}
          {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={setSettings} />}
          {currentView === View.INTEGRATION && <Integration />}
          {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
          {currentView === View.ANALYTICS && (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 py-20 text-center">
              <i className="fas fa-history text-6xl mb-4"></i>
              <h2 className="text-xl font-bold">Lịch sử hội thoại thực tế</h2>
              <p className="mt-2">Tính năng này đang được phát triển.</p>
            </div>
          )}
        </div>

        {/* ChatWidget ẩn trên màn hình quá nhỏ hoặc tùy chỉnh hiển thị */}
        <div className="fixed bottom-4 right-4 z-50">
          <ChatWidget settings={settings} knowledgeBase={documents} />
        </div>
      </main>
    </div>
  );
};

export default App;

