import React, { useState } from 'react';
import { Document } from '../types';

const API_BASE = 'http://localhost:3001/api';

interface Props {
  documents: Document[];
  onAddDocument: (doc: Document) => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ documents, onAddDocument, onDeleteDocument }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;

    setIsUploading(true);
    const res = await fetch(`${API_BASE}/documents/text`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: newDocName, content: newDocText })
    });
    const doc = await res.json();
    onAddDocument(doc);
    setNewDocName('');
    setNewDocText('');
    setIsUploading(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);

    const res = await fetch(`${API_BASE}/documents/upload`, {
      method: 'POST',
      body: formData
    });
    const doc = await res.json();
    onAddDocument(doc);
    setIsUploading(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold">Kho tri thức</h2>
          <p className="text-sm text-gray-500">Quản lý tài liệu đã lưu trên server.</p>
        </div>
        <div className="w-full sm:w-auto">
           <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center justify-center">
            <i className="fas fa-upload mr-2"></i>
            Tải tệp lên
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[600px]">
                <thead className="bg-gray-50 border-b border-gray-100">
                  <tr>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Tên tài liệu</th>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Loại</th>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Trạng thái</th>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {documents.map(doc => (
                    <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center min-w-0">
                          <i className={`fas ${doc.type === 'file' ? 'fa-file-alt' : 'fa-align-left'} text-gray-400 mr-3 shrink-0`}></i>
                          <span className="font-medium truncate max-w-[200px]">{doc.name}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-[10px] font-medium px-2 py-1 bg-gray-100 rounded text-gray-600 capitalize">
                          {doc.type === 'file' ? 'Tệp tin' : 'Văn bản'}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span className="flex items-center text-[10px] font-semibold text-green-600 whitespace-nowrap">
                          <i className="fas fa-database mr-2"></i>
                          Đã lưu
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button 
                          onClick={() => onDeleteDocument(doc.id)}
                          className="text-red-400 hover:text-red-600 transition-colors p-2"
                        >
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                  {documents.length === 0 && (
                    <tr>
                      <td colSpan={4} className="px-6 py-12 text-center text-gray-400">
                        <i className="fas fa-folder-open text-4xl mb-4"></i>
                        <p>Kho tri thức đang trống.</p>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="font-bold mb-4 flex items-center">
              <i className="fas fa-keyboard text-blue-600 mr-2"></i>
              Thêm trực tiếp
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tiêu đề</label>
                <input 
                  type="text" 
                  value={newDocName}
                  onChange={(e) => setNewDocName(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nội dung</label>
                <textarea 
                  rows={4}
                  value={newDocText}
                  onChange={(e) => setNewDocText(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                ></textarea>
              </div>
              <button 
                onClick={handleManualAdd}
                disabled={!newDocName || !newDocText || isUploading}
                className="w-full bg-gray-900 text-white py-2 rounded-lg font-medium hover:bg-gray-800 transition-colors disabled:opacity-50"
              >
                {isUploading ? 'Đang lưu...' : 'Lưu lên Server'}
              </button>
            </div>
          </div>
        </div>
      </div>

      {isUploading && (
        <div className="fixed inset-0 bg-black/20 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white p-6 rounded-2xl shadow-xl flex flex-col items-center max-w-sm w-full">
            <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
            <p className="font-bold text-center">Đang tải dữ liệu...</p>
          </div>
        </div>
      )}
    </div>
  );
};

