import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

// Cấu hình lưu trữ tệp tin
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
const upload = multer({ storage });

// Fix: Use 'as any' to avoid typing conflicts with express middleware overloads
app.use(cors() as any);
app.use(express.json() as any);

// "Database" đơn giản bằng file JSON
const DB_FILE = './db.json';
const initDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ users: [], documents: [] }));
  }
};
initDB();

const getDB = () => JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
const saveDB = (data: any) => fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));

// API: Đăng nhập
// Fix: Corrected route parameters from (email, password) to (req, res)
app.post('/api/login', (req, res) => {
  const { email, password } = req.body;
  // Demo đơn giản
  if (email === 'admin@omnichat.io' && password === '123456') {
    return res.json({ success: true, user: { email, role: 'admin' } });
  }
  return res.json({ success: false });
});

// API: Lấy danh sách tài liệu
app.get('/api/documents', (req, res) => {
  const db = getDB();
  res.json(db.documents);
});

// API: Thêm tài liệu văn bản
app.post('/api/documents/text', (req, res) => {
  const { name, content } = req.body;
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    name,
    content,
    type: 'text',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Upload tệp tin
app.post('/api/documents/upload', upload.single('file'), (req, res) => {
  // Fix: Cast req to any to access 'file' property added by multer
  const file = (req as any).file;
  if (!file) return res.status(400).send('No file uploaded.');

  const content = fs.readFileSync(file.path, 'utf-8');
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    name: file.originalname,
    content: content,
    path: file.path,
    type: 'file',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Xóa tài liệu
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) {
    fs.unlinkSync(doc.path);
  }
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});

// API: Chat với AI (Xử lý phía server để bảo mật API Key)
app.post('/api/chat', async (req, res) => {
  const { message, history, botName } = req.body;
  const db = getDB();
  const apiKey = process.env.API_KEY;

  if (!apiKey) return res.status(500).json({ error: "Thiếu API KEY trên server" });

  // Fix: Initialize GoogleGenAI inside the handler to ensure it uses the latest API key
  const ai = new GoogleGenAI({ apiKey });
  const context = db.documents.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');

  const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy dùng kiến thức sau: ${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: message }] }],
      config: { systemInstruction }
    });
    // Fix: Access response.text as a property (not a method)
    res.json({ text: response.text });
  } catch (error) {
    console.error("Lỗi Gemini API:", error);
    res.status(500).json({ error: "Lỗi AI" });
  }
});

app.listen(PORT, () => {
  console.log(`Backend server running at http://localhost:${PORT}`);
});

import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
const upload = multer({ storage });

app.use(cors() as any);
app.use(express.json() as any);

const DB_FILE = './db.json';
const initDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ 
      users: [
        { id: 'admin', email: 'admin@omnichat.io', password: '123456', botSettings: { botName: 'OmniBot', primaryColor: '#2563eb', welcomeMessage: 'Xin chào!' } }
      ], 
      documents: [] 
    }));
  }
};
initDB();

const getDB = () => JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
const saveDB = (data: any) => fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));

// API: Đăng ký
app.post('/api/register', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();

  if (db.users.find((u: any) => u.email === email)) {
    return res.status(400).json({ success: false, message: 'Email đã tồn tại' });
  }

  const newUser = {
    id: Math.random().toString(36).substr(2, 9),
    email,
    password,
    botSettings: {
      botName: 'Trợ lý AI',
      primaryColor: '#2563eb',
      welcomeMessage: 'Chào mừng bạn đến với hỗ trợ trực tuyến!'
    }
  };

  db.users.push(newUser);
  saveDB(db);
  res.json({ success: true, user: { id: newUser.id, email: newUser.email } });
});

// API: Đăng nhập
app.post('/api/login', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();
  const user = db.users.find((u: any) => u.email === email && u.password === password);

  if (user) {
    res.json({ success: true, user: { id: user.id, email: user.email, botSettings: user.botSettings } });
  } else {
    res.status(401).json({ success: false, message: 'Sai thông tin đăng nhập' });
  }
});

// API: Lấy tài liệu của riêng User
app.get('/api/documents/:userId', (req, res) => {
  const db = getDB();
  const userDocs = db.documents.filter((d: any) => d.userId === req.params.userId);
  res.json(userDocs);
});

// API: Lưu cấu hình Widget cho User
app.post('/api/settings/:userId', (req, res) => {
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === req.params.userId);
  if (userIndex !== -1) {
    db.users[userIndex].botSettings = req.body;
    saveDB(db);
    res.json({ success: true });
  } else {
    res.status(404).json({ success: false });
  }
});

// API: Thêm tài liệu văn bản (có userId)
app.post('/api/documents/text', (req, res) => {
  const { name, content, userId } = req.body;
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name,
    content,
    type: 'text',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Upload tệp (có userId)
app.post('/api/documents/upload', upload.single('file'), (req, res) => {
  const file = (req as any).file;
  const { userId } = req.body;
  if (!file || !userId) return res.status(400).send('Missing file or userId.');

  const content = fs.readFileSync(file.path, 'utf-8');
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name: file.originalname,
    content: content,
    path: file.path,
    type: 'file',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Xóa tài liệu
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) fs.unlinkSync(doc.path);
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});

// API: Chat AI (Chỉ lấy tài liệu của userId đó)
app.post('/api/chat', async (req, res) => {
  const { message, userId, botName } = req.body;
  const db = getDB();
  const apiKey = process.env.API_KEY;

  if (!apiKey) return res.status(500).json({ error: "Missing API KEY" });

  const ai = new GoogleGenAI({ apiKey });
  // Phân tách dữ liệu: Chỉ lấy tài liệu của người đang chat
  const context = db.documents
    .filter((d: any) => d.userId === userId)
    .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`)
    .join('\n\n');

  const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy dùng kiến thức sau để hỗ trợ khách hàng: ${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: message }] }],
      config: { systemInstruction }
    });
    res.json({ text: response.text });
  } catch (error) {
    res.status(500).json({ error: "AI Error" });
  }
});

app.listen(PORT, () => {
  console.log(`SaaS Backend running at http://localhost:${PORT}`);
});

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import Login from './components/Login';
import { View, Document, WidgetSettings } from './types';

const API_BASE = 'http://localhost:3001/api';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userId, setUserId] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  useEffect(() => {
    const savedUser = localStorage.getItem('omnichat_user_id');
    if (savedUser) {
      setUserId(savedUser);
      setIsLoggedIn(true);
      fetchUserData(savedUser);
    }
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      // 1. Lấy danh sách tài liệu
      const docRes = await fetch(`${API_BASE}/documents/${uid}`);
      const docData = await docRes.json();
      setDocuments(docData);

      // 2. Lấy cấu hình user (từ login response đã có hoặc fetch lại)
      // Trong demo này ta fetch lại từ API lấy danh sách user hoặc giả định lưu local
    } catch (e) {
      console.error("Lỗi đồng bộ dữ liệu");
    }
  };

  const handleLogin = (user: any) => {
    setIsLoggedIn(true);
    setUserId(user.id);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    fetchUserData(user.id);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserId(null);
    localStorage.removeItem('omnichat_user_id');
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (userId) {
      await fetch(`${API_BASE}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newSettings)
      });
    }
  };

  const deleteDocument = async (id: string) => {
    await fetch(`${API_BASE}/documents/${id}`, { method: 'DELETE' });
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50 relative">
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 z-30 shrink-0">
          <div className="flex items-center space-x-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
              <i className="fas fa-bars text-xl"></i>
            </button>
            <h1 className="text-xs lg:text-sm font-bold text-gray-500 uppercase tracking-widest truncate">
              {currentView}
            </h1>
          </div>
          <div className="flex items-center space-x-2">
            <span className="text-[10px] lg:text-sm font-medium text-blue-600 bg-blue-50 px-2 lg:px-3 py-1 rounded-full border border-blue-100">
              <i className="fas fa-user-circle mr-1"></i>
              ID: {userId}
            </span>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 max-w-7xl mx-auto w-full">
          {currentView === View.DASHBOARD && <Dashboard />}
          {currentView === View.KNOWLEDGE_BASE && (
            <KnowledgeBase 
              userId={userId!}
              documents={documents} 
              onAddDocument={(doc) => setDocuments([...documents, doc])} 
              onDeleteDocument={deleteDocument} 
            />
          )}
          {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={updateSettings} />}
          {currentView === View.INTEGRATION && <Integration userId={userId!} />}
          {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
        </div>

        <div className="fixed bottom-4 right-4 z-50">
          <ChatWidget settings={settings} userId={userId!} />
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface Props {
  onLogin: (user: any) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    const endpoint = isRegister ? '/api/register' : '/api/login';

    try {
      const response = await fetch(`http://localhost:3001${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });

      const data = await response.json();

      if (data.success) {
        if (isRegister) {
          setIsRegister(false);
          setError('Đăng ký thành công! Hãy đăng nhập.');
        } else {
          onLogin(data.user);
        }
      } else {
        setError(data.message || 'Có lỗi xảy ra.');
      }
    } catch (err) {
      setError('Không thể kết nối Backend server.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gray-50 p-4 font-sans">
      <div className="max-w-md w-full space-y-8 bg-white p-10 rounded-3xl shadow-xl border border-gray-100">
        <div className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-4 shadow-lg">
            <i className="fas fa-rocket"></i>
          </div>
          <h2 className="text-3xl font-black text-gray-900">{isRegister ? 'Tạo tài khoản SaaS' : 'Chào mừng trở lại'}</h2>
          <p className="mt-2 text-sm text-gray-500">Mỗi khách hàng sẽ có kho tri thức riêng biệt.</p>
        </div>

        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          {error && (
            <div className={`p-3 rounded-xl text-xs font-medium border ${error.includes('thành công') ? 'bg-green-50 text-green-600 border-green-100' : 'bg-red-50 text-red-600 border-red-100'}`}>
              <i className={`fas ${error.includes('thành công') ? 'fa-check-circle' : 'fa-exclamation-circle'} mr-2`}></i>
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Email</label>
              <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} className="block w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="email@congty.com" />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Mật khẩu</label>
              <input type="password" required value={password} onChange={(e) => setPassword(e.target.value)} className="block w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="••••••••" />
            </div>
          </div>

          <button type="submit" disabled={isLoading} className="w-full flex justify-center py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all disabled:opacity-50 shadow-lg shadow-blue-100">
            {isLoading ? <i className="fas fa-circle-notch animate-spin"></i> : (isRegister ? 'Đăng ký tài khoản' : 'Đăng nhập ngay')}
          </button>
        </form>

        <div className="text-center pt-4">
          <button onClick={() => setIsRegister(!isRegister)} className="text-xs font-bold text-blue-600 hover:underline">
            {isRegister ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký dùng thử'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { Document } from '../types';

const API_BASE = 'http://localhost:3001/api';

interface Props {
  userId: string;
  documents: Document[];
  onAddDocument: (doc: Document) => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ userId, documents, onAddDocument, onDeleteDocument }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;

    setIsUploading(true);
    const res = await fetch(`${API_BASE}/documents/text`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: newDocName, content: newDocText, userId })
    });
    const doc = await res.json();
    onAddDocument(doc);
    setNewDocName('');
    setNewDocText('');
    setIsUploading(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    formData.append('userId', userId);

    const res = await fetch(`${API_BASE}/documents/upload`, {
      method: 'POST',
      body: formData
    });
    const doc = await res.json();
    onAddDocument(doc);
    setIsUploading(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold">Kho tri thức riêng</h2>
          <p className="text-sm text-gray-500">Tài liệu của bạn được cách ly an toàn với người dùng khác.</p>
        </div>
        <div className="w-full sm:w-auto">
           <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center justify-center shadow-lg shadow-blue-100">
            <i className="fas fa-upload mr-2"></i>
            Tải tệp lên
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[600px]">
                <thead className="bg-gray-50 border-b border-gray-100">
                  <tr>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Tên tài liệu</th>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Loại</th>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Trạng thái</th>
                    <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {documents.map(doc => (
                    <tr key={doc.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center min-w-0">
                          <i className={`fas ${doc.type === 'file' ? 'fa-file-alt' : 'fa-align-left'} text-gray-400 mr-3 shrink-0`}></i>
                          <span className="font-medium truncate max-w-[200px]">{doc.name}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-[10px] font-medium px-2 py-1 bg-gray-100 rounded text-gray-600 capitalize">
                          {doc.type}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span className="flex items-center text-[10px] font-semibold text-green-600 whitespace-nowrap">
                          <i className="fas fa-lock mr-2"></i>
                          Riêng tư
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button onClick={() => onDeleteDocument(doc.id)} className="text-red-400 hover:text-red-600 transition-colors p-2">
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="font-bold mb-4 flex items-center">
              <i className="fas fa-keyboard text-blue-600 mr-2"></i>
              Soạn thảo nhanh
            </h3>
            <div className="space-y-4">
              <input type="text" value={newDocName} onChange={(e) => setNewDocName(e.target.value)} placeholder="Tên tài liệu..." className="w-full px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500" />
              <textarea rows={4} value={newDocText} onChange={(e) => setNewDocText(e.target.value)} placeholder="Nội dung kiến thức..." className="w-full px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm" />
              <button onClick={handleManualAdd} disabled={!newDocName || !newDocText || isUploading} className="w-full bg-gray-900 text-white py-2 rounded-lg font-medium hover:bg-gray-800 transition-colors disabled:opacity-50">
                {isUploading ? 'Đang lưu...' : 'Lưu vào kho'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
