              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-comments', color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Tỷ lệ giải quyết', value: `${successRate}%`, icon: 'fa-brain', color: 'text-green-600', bg: 'bg-green-50' },
          { label: 'Câu hỏi chưa xử lý', value: totalQueries - totalSolved, icon: 'fa-question-circle', color: 'text-red-600', bg: 'bg-red-50' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex items-center space-x-4 group hover:shadow-md transition-all">
            <div className={`p-4 rounded-xl ${stat.bg} ${stat.color} shrink-0`}>
              <i className={`fas ${stat.icon} text-2xl`}></i>
            </div>
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{stat.label}</p>
              <h3 className="text-3xl font-black text-gray-900">{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-lg font-black text-gray-900">Biểu đồ tương tác</h3>
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-blue-600 rounded-full"></span>
              <span className="text-[10px] font-bold text-gray-500 uppercase">Yêu cầu</span>
            </div>
          </div>
        </div>

        <div className="h-80 w-full">
          {isLoading ? (
            <div className="h-full w-full flex items-center justify-center">
              <i className="fas fa-circle-notch animate-spin text-blue-600 text-3xl"></i>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 'bold', fontFamily: 'Inter'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 'bold', fontFamily: 'Inter'}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px', fontFamily: 'Inter' }}
                />
                <Area type="monotone" dataKey="queries" stroke="#2563eb" fillOpacity={1} fill="url(#colorQueries)" strokeWidth={3} />
                <Area type="monotone" dataKey="solved" stroke="#10b981" fill="transparent" strokeWidth={3} strokeDasharray="5 5" />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
               <i className="fas fa-chart-bar text-5xl mb-4 opacity-20"></i>
               <p className="text-sm font-bold">Chưa có dữ liệu cho giai đoạn này</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

