                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4} className="px-8 py-32 text-center">
                    <div className="max-w-xs mx-auto">
                      <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-6">
                        <i className="fa-solid fa-user-slash text-4xl"></i>
                      </div>
                      <h3 className="text-lg font-bold text-slate-900">Danh sách trống</h3>
                      <p className="text-sm text-slate-500 font-medium mt-2">Chưa có khách hàng nào đăng ký hoặc không khớp với tìm kiếm của bạn.</p>
                      <button onClick={loadCustomers} className="mt-6 text-blue-600 font-bold text-sm hover:underline">
                        <i className="fa-solid fa-rotate-right mr-2"></i> Làm mới
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CustomerManagement;

import React, { useState, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(setCustomers);
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  return (
    <div className="space-y-7 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-5 bg-white p-7 rounded-3xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight">
            <i className="fa-solid fa-chart-pie text-blue-600 mr-2"></i>
            Thống kê hoạt động AI
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-1">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem khách hàng: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Dữ liệu tương tác thời gian thực từ widget.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto">
          {isMaster && (
            <select 
              value={selectedUser}
              onChange={(e) => setSelectedUser(e.target.value)}
              className="flex-1 lg:flex-none px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all cursor-pointer"
            >
              <option value="all">Toàn bộ hệ thống</option>
              {customers.map(c => (
                <option key={c.id} value={c.id}>{c.email}</option>
              ))}
            </select>
          )}

          <div className="flex bg-slate-100 p-1.5 rounded-2xl">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-4 py-2 rounded-xl text-[11px] font-extrabold uppercase tracking-widest transition-all ${
                  period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-solid fa-message', color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Tỷ lệ chính xác', value: `${successRate}%`, icon: 'fa-solid fa-bolt-lightning', color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'Cần hỗ trợ lại', value: totalQueries - totalSolved, icon: 'fa-solid fa-circle-exclamation', color: 'text-rose-600', bg: 'bg-rose-50' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-7 rounded-3xl shadow-sm border border-slate-200 flex items-center space-x-5 hover:shadow-md transition-all group">
            <div className={`w-14 h-14 rounded-2xl ${stat.bg} ${stat.color} flex items-center justify-center shrink-0 transition-transform group-hover:scale-110`}>
              <i className={`${stat.icon} text-2xl`}></i>
            </div>
            <div>
              <p className="text-[11px] font-extrabold text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-900 tracking-tight">{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-200">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-12">
          <h3 className="text-lg font-extrabold text-slate-900 tracking-tight">Biểu đồ tăng trưởng tương tác</h3>
          <div className="flex items-center space-x-6">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-blue-600 rounded-full"></span>
              <span className="text-[11px] font-bold text-slate-500 uppercase tracking-tighter">Tổng truy vấn</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-emerald-500 rounded-full"></span>
              <span className="text-[11px] font-bold text-slate-500 uppercase tracking-tighter">Đã xử lý</span>
            </div>
          </div>
        </div>

        <div className="h-[400px] w-full">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <i className="fa-solid fa-spinner animate-spin text-blue-600 text-4xl"></i>
              <p className="mt-4 text-sm font-bold text-slate-400">Đang tổng hợp dữ liệu...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.15}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} 
                  dy={15} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} 
                />
                <Tooltip 
                  cursor={{stroke: '#e2e8f0', strokeWidth: 2}}
                  contentStyle={{ 
                    borderRadius: '20px', 
                    border: 'none', 
                    boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', 
                    padding: '15px',
                    fontWeight: 700,
                    fontSize: '12px'
                  }}
                />
                <Area type="monotone" dataKey="queries" stroke="#2563eb" fillOpacity={1} fill="url(#colorQueries)" strokeWidth={4} />
                <Area type="monotone" dataKey="solved" stroke="#10b981" fill="transparent" strokeWidth={3} strokeDasharray="6 6" />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <i className="fa-solid fa-chart-line text-6xl mb-6 opacity-20"></i>
               <p className="text-sm font-bold">Chưa có dữ liệu nào được ghi nhận</p>
               <p className="text-xs font-medium mt-1">Các lượt chat của khách hàng sẽ hiển thị tại đây.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Document } from '../types';

interface Props {
  userId: string;
  documents: Document[];
  onAddDocument: (name: string, content: string, type: 'text' | 'file') => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ userId, documents, onAddDocument, onDeleteDocument }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;
    setIsProcessing(true);
    await onAddDocument(newDocName, newDocText, 'text');
    setNewDocName('');
    setNewDocText('');
    setIsProcessing(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      await onAddDocument(file.name, content, 'file');
      setIsProcessing(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-7 animate-in fade-in slide-in-from-bottom-3 duration-500 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-5 bg-white p-7 rounded-3xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight">
            <i className="fa-solid fa-brain text-blue-600 mr-2"></i>
            Kho tri thức AI
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Dữ liệu huấn luyện riêng biệt cho AI của bạn.</p>
        </div>
        <div className="w-full md:w-auto">
           <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-7 py-3 rounded-2xl font-bold transition-all flex items-center justify-center shadow-lg shadow-blue-100 active:scale-95">
            <i className="fa-solid fa-cloud-arrow-up mr-2 text-lg"></i>
            Tải tài liệu lên
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-7">
        <div className="lg:col-span-2 space-y-5">
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[650px]">
                <thead className="bg-slate-50/50 border-b border-slate-100">
                  <tr>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Tài liệu</th>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Định dạng</th>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Trạng thái</th>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest text-right">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {documents.map(doc => (
                    <tr key={doc.id} className="hover:bg-blue-50/30 transition-colors group">
                      <td className="px-8 py-5">
                        <div className="flex items-center min-w-0">
                          <div className={`w-11 h-11 rounded-2xl flex items-center justify-center mr-4 shrink-0 shadow-sm ${doc.type === 'file' ? 'bg-amber-50 text-amber-500' : 'bg-blue-50 text-blue-500'}`}>
                            <i className={`fa-solid ${doc.type === 'file' ? 'fa-file-lines' : 'fa-font'} text-lg`}></i>
                          </div>
                          <div className="truncate">
                            <p className="font-bold text-sm text-slate-800 truncate">{doc.name}</p>
                            <p className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter">Cập nhật: {new Date(doc.createdAt).toLocaleDateString('vi-VN')}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-5">
                        <span className="text-[10px] font-black px-2.5 py-1.5 bg-slate-100 rounded-lg text-slate-500 uppercase tracking-wider">
                          {doc.type}
                        </span>
                      </td>
                      <td className="px-8 py-5">
                        <span className="inline-flex items-center text-[10px] font-extrabold text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-full">
                          <i className="fa-solid fa-circle-check mr-2"></i>
                          Sẵn sàng
                        </span>
                      </td>
                      <td className="px-8 py-5 text-right">
                        <button 
                          onClick={() => onDeleteDocument(doc.id)} 
                          className="text-slate-300 hover:text-rose-500 transition-all p-2.5 rounded-xl hover:bg-rose-50"
                          title="Xóa tài liệu"
                        >
                          <i className="fa-solid fa-trash-can"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                  {documents.length === 0 && (
                    <tr>
                      <td colSpan={4} className="px-8 py-24 text-center">
                        <div className="flex flex-col items-center">
                          <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 mb-5 border-2 border-dashed border-slate-200">
                            <i className="fa-solid fa-inbox text-3xl"></i>
                          </div>
                          <h3 className="text-base font-bold text-slate-800">Kho tri thức trống</h3>
                          <p className="text-sm font-medium text-slate-400 mt-2 max-w-xs mx-auto">Tải tệp hoặc nhập văn bản để AI có thể bắt đầu học và trả lời khách hàng.</p>
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-7 rounded-[2rem] shadow-sm border border-slate-200">
            <h3 className="font-extrabold text-sm text-slate-800 mb-6 flex items-center uppercase tracking-tight">
              <i className="fa-solid fa-keyboard text-blue-600 mr-2 text-lg"></i>
              Thêm nhanh văn bản
            </h3>
            <div className="space-y-5">
              <div>
                <label className="block text-[11px] font-extrabold text-slate-400 uppercase mb-2 ml-1 tracking-widest">Tiêu đề nội dung</label>
                <input 
                  type="text" 
                  value={newDocName} 
                  onChange={(e) => setNewDocName(e.target.value)} 
                  placeholder="Ví dụ: Quy định đổi trả" 
                  className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white text-sm font-medium transition-all" 
                />
              </div>
              <div>
                <label className="block text-[11px] font-extrabold text-slate-400 uppercase mb-2 ml-1 tracking-widest">Chi tiết thông tin</label>
                <textarea 
                  rows={6} 
                  value={newDocText} 
                  onChange={(e) => setNewDocText(e.target.value)} 
                  placeholder="Dán nội dung hướng dẫn hoặc kiến thức vào đây..." 
                  className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white text-sm font-medium transition-all resize-none" 
                />
              </div>
              <button 
                onClick={handleManualAdd} 
                disabled={!newDocName || !newDocText || isProcessing} 
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold hover:bg-black transition-all disabled:opacity-50 shadow-lg shadow-slate-200 active:scale-95 flex items-center justify-center"
              >
                {isProcessing ? <i className="fa-solid fa-circle-notch animate-spin"></i> : 'Lưu vào kho tri thức'}
              </button>
            </div>
          </div>

          <div className="bg-slate-900 p-7 rounded-[2rem] text-white shadow-xl shadow-slate-200 relative overflow-hidden group">
            <div className="relative z-10">
              <h4 className="font-extrabold text-lg mb-2">Hỗ trợ định dạng</h4>
              <p className="text-xs font-medium text-slate-400 leading-relaxed mb-4">
                Hệ thống hỗ trợ tốt nhất cho văn bản thô, Markdown và JSON.
              </p>
              <div className="flex items-center text-[11px] font-bold text-blue-400">
                <i className="fa-solid fa-circle-info mr-2"></i>
                Xem hướng dẫn chi tiết
              </div>
            </div>
            <i className="fa-solid fa-lightbulb absolute -bottom-6 -right-6 text-white/5 text-8xl group-hover:scale-110 transition-transform duration-500"></i>
          </div>
        </div>
      </div>
    </div>
  );
};

export default KnowledgeBase;

