                    </div>
                  </div>
                  {isMaster && (
                    <div className="text-xs font-bold bg-blue-100 text-blue-700 px-3 py-1.5 rounded-full">
                      {getCustomerEmail(selectedLog.userId)}
                    </div>
                  )}
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/30">
                  {/* User Message */}
                  <div className="flex justify-end">
                    <div className="max-w-[85%] space-y-1">
                      <div className="bg-blue-600 text-white p-4 rounded-2xl rounded-tr-sm shadow-sm text-sm font-medium leading-relaxed">
                        {selectedLog.query}
                      </div>
                      <p className="text-[10px] text-slate-400 font-bold text-right uppercase mr-1">Khách hàng</p>
                    </div>
                  </div>

                  {/* AI Response */}
                  <div className="flex justify-start">
                    <div className="max-w-[85%] space-y-1">
                      <div className="bg-white text-slate-800 border border-slate-200 p-4 rounded-2xl rounded-tl-sm shadow-sm text-sm font-medium leading-relaxed whitespace-pre-wrap">
                        {selectedLog.answer}
                      </div>
                      <div className="flex items-center gap-2 ml-1">
                        <p className="text-[10px] text-slate-400 font-bold uppercase">AI Bot</p>
                        {!selectedLog.isSolved && (
                          <span className="text-[9px] text-rose-500 bg-rose-50 px-1.5 rounded font-bold">Bot không trả lời được</span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
             </>
           ) : (
             <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                 <i className="fa-solid fa-message text-3xl"></i>
               </div>
               <p className="text-sm font-bold">Chọn một cuộc hội thoại để xem chi tiết</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

