               </p>
               <div className="grid grid-cols-2 gap-3 mt-6">
                 <button onClick={() => setDeleteModal({ isOpen: false, userId: null, email: '' })} className="py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-colors">Hủy bỏ</button>
                 <button onClick={handleDeleteUser} className="py-3 bg-rose-600 text-white rounded-xl font-bold hover:bg-rose-700 transition-colors shadow-lg shadow-rose-200">Xóa vĩnh viễn</button>
               </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

