                      </div>
                    </td>
                    <td className="px-6 py-5 text-center">
                      <div className="inline-flex items-center px-2.5 py-1 bg-slate-100 border border-slate-200">
                         <span className="w-1.5 h-1.5 rounded-none mr-1.5" style={{ backgroundColor: customer.botSettings.primaryColor }}></span>
                         <span className="text-[10px] font-bold text-slate-700">{customer.botSettings.botName}</span>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <p className="text-xs font-semibold text-slate-600 flex items-center">
                        <i className="fa-regular fa-calendar-check mr-2 text-slate-400"></i>
                        {new Date(customer.createdAt).toLocaleDateString('vi-VN')}
                      </p>
                    </td>
                    <td className="px-6 py-5 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => onViewStats(customer.id)}
                          className="w-8 h-8 flex items-center justify-center bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white transition-all border border-blue-100"
                          title="Xem báo cáo"
                        >
                          <i className="fa-solid fa-chart-simple text-xs"></i>
                        </button>
                        <button 
                          onClick={() => {
                            setResetModal({ isOpen: true, userId: customer.id, email: customer.email });
                            setNewResetPassword('');
                          }}
                          className="w-8 h-8 flex items-center justify-center bg-amber-50 text-amber-600 hover:bg-amber-500 hover:text-white transition-all border border-amber-100"
                          title="Reset mật khẩu"
                        >
                          <i className="fa-solid fa-key text-xs"></i>
                        </button>
                        <button 
                          onClick={() => setDeleteModal({ isOpen: true, userId: customer.id, email: customer.email })}
                          className="w-8 h-8 flex items-center justify-center bg-rose-50 text-rose-600 hover:bg-rose-500 hover:text-white transition-all border border-rose-100"
                          title="Xóa tài khoản"
                        >
                          <i className="fa-solid fa-trash-can text-xs"></i>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4} className="px-8 py-32 text-center">
                    <div className="max-w-xs mx-auto">
                      <div className="w-20 h-20 bg-slate-50 flex items-center justify-center text-slate-300 mx-auto mb-6 border border-slate-100">
                        <i className="fa-solid fa-user-slash text-3xl"></i>
                      </div>
                      <h3 className="text-lg font-bold text-slate-900">Danh sách trống</h3>
                      <p className="text-sm text-slate-500 font-medium mt-2">Chưa có khách hàng nào đăng ký.</p>
                      <button onClick={loadCustomers} className="mt-6 text-blue-600 font-bold text-sm hover:underline">
                        <i className="fa-solid fa-rotate-right mr-2"></i> Thử tải lại
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Reset Password Modal */}
      {resetModal.isOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in duration-200">
             <div className="p-6 text-center">
               <div className="w-14 h-14 bg-amber-100 text-amber-600 flex items-center justify-center mx-auto mb-4 text-2xl">
                 <i className="fa-solid fa-key"></i>
