import React, { useState } from 'react';
import { Document } from '../types';

interface Props {
  userId: string;
  documents: Document[];
  onAddDocument: (name: string, content: string, type: 'text' | 'file') => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ userId, documents, onAddDocument, onDeleteDocument }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;
    setIsProcessing(true);
    await onAddDocument(newDocName, newDocText, 'text');
    setNewDocName('');
    setNewDocText('');
    setIsProcessing(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      await onAddDocument(file.name, content, 'file');
      setIsProcessing(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-7 animate-in fade-in slide-in-from-bottom-3 duration-500 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-5 bg-white p-7 border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight">
            <i className="fa-solid fa-brain text-blue-600 mr-2"></i>
            Kho tri thức AI
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Dữ liệu huấn luyện riêng biệt cho AI của bạn.</p>
        </div>
        <div className="w-full md:w-auto">
           <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-7 py-3 font-bold transition-all flex items-center justify-center shadow-lg shadow-blue-100 active:scale-95">
            <i className="fa-solid fa-cloud-arrow-up mr-2 text-lg"></i>
            Tải tài liệu lên
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-7">
        <div className="lg:col-span-2 space-y-5">
          <div className="bg-white shadow-sm border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[650px]">
                <thead className="bg-slate-50/50 border-b border-slate-100">
                  <tr>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Tài liệu</th>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Định dạng</th>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest">Trạng thái</th>
                    <th className="px-8 py-5 text-[11px] font-extrabold text-slate-400 uppercase tracking-widest text-right">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {documents.map(doc => (
                    <tr key={doc.id} className="hover:bg-blue-50/30 transition-colors group">
                      <td className="px-8 py-5">
                        <div className="flex items-center min-w-0">
                          <div className={`w-11 h-11 flex items-center justify-center mr-4 shrink-0 shadow-sm ${doc.type === 'file' ? 'bg-amber-50 text-amber-500' : 'bg-blue-50 text-blue-500'}`}>
                            <i className={`fa-solid ${doc.type === 'file' ? 'fa-file-lines' : 'fa-font'} text-lg`}></i>
                          </div>
                          <div className="truncate">
                            <p className="font-bold text-sm text-slate-800 truncate">{doc.name}</p>
                            <p className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter">Cập nhật: {new Date(doc.createdAt).toLocaleDateString('vi-VN')}</p>
