import React, { useState } from 'react';
import { Document } from '../types';

interface Props {
  userId: string;
  documents: Document[];
  onAddDocument: (name: string, content: string, type: 'text' | 'file') => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ userId, documents, onAddDocument, onDeleteDocument }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;
    setIsProcessing(true);
    await onAddDocument(newDocName, newDocText, 'text');
    setNewDocName('');
    setNewDocText('');
    setIsProcessing(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      await onAddDocument(file.name, content, 'file');
      setIsProcessing(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-3 duration-500 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-8 rounded-3xl border border-slate-100 shadow-xl shadow-slate-200/50">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-3">
            <span className="w-10 h-10 rounded-xl bg-blue-100 text-blue-600 flex items-center justify-center text-lg shadow-sm">
               <i className="fa-solid fa-brain"></i>
            </span>
            Kho tri thức AI
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-2">Nạp dữ liệu để AI thông minh hơn.</p>
        </div>
        <div className="w-full md:w-auto">
           <label className="cursor-pointer bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white px-6 py-3 rounded-xl font-bold transition-all flex items-center justify-center shadow-lg shadow-blue-500/30 active:scale-95 transform hover:-translate-y-0.5">
            <i className="fa-solid fa-cloud-arrow-up mr-2 text-lg"></i>
            Tải tài liệu
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-3xl shadow-lg shadow-slate-200/40 border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[650px]">
                <thead className="bg-slate-50/80 border-b border-slate-100">
