                    <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">Tên tài liệu</th>
                    <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">Định dạng</th>
                    <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">Trạng thái</th>
                    <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {documents.map(doc => (
                    <tr key={doc.id} className="hover:bg-blue-50/30 transition-colors group">
                      <td className="px-8 py-5">
                        <div className="flex items-center min-w-0">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center mr-4 shrink-0 shadow-sm border border-white ${doc.type === 'file' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>
                            <i className={`fa-solid ${doc.type === 'file' ? 'fa-file-lines' : 'fa-align-left'}`}></i>
                          </div>
                          <div className="truncate">
                            <p className="font-bold text-sm text-slate-800 truncate group-hover:text-blue-600 transition-colors">{doc.name}</p>
                            <p className="text-[10px] font-bold text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded inline-block mt-0.5">{new Date(doc.createdAt).toLocaleDateString('vi-VN')}</p>
                          </div>
