                          </div>
                          <h3 className="text-base font-bold text-slate-800">Chưa có dữ liệu</h3>
                          <p className="text-sm font-medium text-slate-400 mt-2 max-w-xs mx-auto">Hãy thêm tài liệu để bắt đầu.</p>
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-6 rounded-3xl shadow-lg shadow-slate-200/40 border border-slate-100">
            <h3 className="font-bold text-slate-800 mb-6 flex items-center">
              <i className="fa-solid fa-pen-to-square text-blue-500 mr-2"></i>
              Soạn thảo nhanh
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-1">Tiêu đề</label>
                <input 
                  type="text" 
                  value={newDocName} 
                  onChange={(e) => setNewDocName(e.target.value)} 
                  placeholder="Ví dụ: Chính sách bảo hành" 
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white text-sm font-medium transition-all" 
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-1">Nội dung</label>
                <textarea 
                  rows={8} 
                  value={newDocText} 
                  onChange={(e) => setNewDocText(e.target.value)} 
                  placeholder="Nhập nội dung chi tiết..." 
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white text-sm font-medium transition-all resize-none" 
                />
