              <button 
                onClick={handleManualAdd} 
                disabled={!newDocName || !newDocText || isProcessing} 
                className="w-full bg-slate-800 hover:bg-slate-900 text-white py-3.5 rounded-xl font-bold transition-all disabled:opacity-50 shadow-lg shadow-slate-300 active:scale-95 flex items-center justify-center gap-2"
              >
                {isProcessing ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <><i className="fa-solid fa-save"></i> Lưu dữ liệu</>}
              </button>
