  ];

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#2563eb',
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  // Map view names to Vietnamese
  const viewNames: Record<View, string> = {
    [View.DASHBOARD]: 'Tổng quan',
    [View.KNOWLEDGE_BASE]: 'Kho tri thức',
    [View.WIDGET_CONFIG]: 'Cấu hình Widget',
    [View.ANALYTICS]: 'Phân tích',
    [View.INTEGRATION]: 'Tích hợp',
    [View.DEPLOYMENT_GUIDE]: 'Hướng dẫn triển khai',
    [View.CUSTOMER_MANAGEMENT]: 'Quản lý khách hàng',
    [View.CHAT_HISTORY]: 'Lịch sử hội thoại'
  };

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    const savedUserRole = localStorage.getItem('omnichat_user_role');

    if (savedUserId) {
      setCurrentUser({
         id: savedUserId,
         email: 'Loading...', 
         role: savedUserRole as any || 'user',
         botSettings: settings,
         createdAt: Date.now()
      });
      setIsLoggedIn(true);

      apiService.getAllUsers().then(users => {
         const me = users.find(u => u.id === savedUserId);
         if(me) handleLoginSuccess(me);
         else if(savedUserId === 'admin') {
             handleLoginSuccess({ 
                 id: 'admin', 
                 email: 'admin@omnichat.io', 
                 role: 'master', 
                 botSettings: settings, 
                 createdAt: Date.now() 
             });
         }
      });
    }

    // Click outside to close notifications
    const handleClickOutside = (event: MouseEvent) => {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);

  }, []);

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    localStorage.setItem('omnichat_user_role', user.role);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
    localStorage.removeItem('omnichat_user_role');
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) return <Login onLogin={handleLoginSuccess} />;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#f8fafc] relative font-sans text-slate-900 antialiased selection:bg-blue-100 selection:text-blue-900">
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-[#f8fafc] flex items-center justify-between px-6 lg:px-8 z-30 shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-500 hover:text-blue-600 transition-colors">
              <i className="fas fa-bars text-lg"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-2xl font-black text-slate-800 tracking-tight">
                {viewNames[currentView]}
              </h1>
              <p className="text-xs font-semibold text-slate-400 hidden sm:block">
                {currentUser?.role === 'master' ? 'Hệ thống Quản trị Cấp cao' : 'Hệ thống Quản trị Doanh nghiệp'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden md:flex items-center gap-2 bg-white px-3 py-1.5 rounded-full border border-slate-200 shadow-sm">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                <span className="text-xs font-bold text-slate-600">Hệ thống ổn định</span>
             </div>

             {/* Notification Bell */}
             <div className="relative" ref={notifRef}>
               <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className="w-10 h-10 bg-white rounded-full border border-slate-200 shadow-sm flex items-center justify-center text-slate-400 hover:text-blue-600 hover:border-blue-200 transition-all relative active:scale-95"
               >
                 <i className="fa-regular fa-bell"></i>
                 <span className="absolute top-2 right-2.5 w-2 h-2 bg-rose-500 rounded-full border-2 border-white"></span>
               </button>

               {/* Notification Dropdown */}
               {showNotifications && (
                 <div className="absolute right-0 mt-3 w-80 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in duration-200 z-50">
                    <div className="p-4 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                       <h3 className="font-bold text-sm text-slate-800">Thông báo</h3>
                       <span className="text-[10px] bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full font-bold">Mới</span>
                    </div>
                    <div className="max-h-80 overflow-y-auto">
                       {notifications.map(notif => (
                         <div key={notif.id} className="p-4 hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-0 cursor-pointer group">
                            <div className="flex gap-3">
                               <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${notif.bg} ${notif.color}`}>
                                  <i className={`fa-solid ${notif.icon}`}></i>
                               </div>
                               <div>
                                  <h4 className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{notif.title}</h4>
                                  <p className="text-xs text-slate-500 mt-0.5 leading-relaxed">{notif.desc}</p>
                                  <p className="text-[10px] text-slate-400 font-bold mt-2">{notif.time}</p>
                               </div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <div className="p-3 text-center border-t border-slate-50 bg-slate-50/30">
                       <button className="text-xs font-bold text-blue-600 hover:text-blue-700">Xem tất cả</button>
                    </div>
                 </div>
               )}
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto w-full scroll-smooth p-6 lg:p-8 pt-2">
          <div className="max-w-7xl mx-auto w-full">
            {currentView === View.DASHBOARD && (
              <Dashboard 
                user={currentUser!} 
                initialSelectedUser={selectedCustomerIdForStats} 
              />
            )}
            {currentView === View.KNOWLEDGE_BASE && (
              <KnowledgeBase 
                userId={currentUser!.id}
                documents={documents} 
                onAddDocument={addDocument} 
                onDeleteDocument={deleteDocument} 
              />
            )}
            {currentView === View.CHAT_HISTORY && (
              <ChatHistory user={currentUser!} />
            )}
            {currentView === View.WIDGET_CONFIG && <WidgetPreview settings={settings} setSettings={updateSettings} />}
            {currentView === View.INTEGRATION && <Integration userId={currentUser!.id} />}
            {currentView === View.DEPLOYMENT_GUIDE && <DeploymentGuide />}
            {currentView === View.CUSTOMER_MANAGEMENT && currentUser?.role === 'master' && (
              <CustomerManagement onViewStats={handleViewCustomerStats} />
            )}
          </div>
        </div>

        {currentUser?.role !== 'master' && (
          <div className="fixed bottom-6 right-6 z-50">
            <ChatWidget settings={settings} userId={currentUser!.id} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(setCustomers);
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  const getSelectedUserLabel = () => {
    if (selectedUser === 'all') return 'Toàn bộ hệ thống';
    const found = customers.find(c => c.id === selectedUser);
    return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-6 rounded-3xl border border-slate-100 shadow-xl shadow-slate-200/50">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight mb-1">
            Hiệu suất hoạt động AI
          </h2>
          <p className="text-sm text-slate-500 font-medium">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Theo dõi tương tác khách hàng thời gian thực.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto items-center">
          {isMaster && (
            <div className="relative flex-1 lg:flex-none w-full lg:w-64 z-20" ref={dropdownRef}>
              <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm font-bold hover:border-blue-400 transition-all text-slate-700 shadow-sm"
              >
                <span className="truncate">{getSelectedUserLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-slate-400 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 w-full mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl overflow-hidden max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200">
                  <div 
                    onClick={() => { setSelectedUser('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 transition-colors ${selectedUser === 'all' ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                  >
                    Toàn bộ hệ thống
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUser(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-medium cursor-pointer hover:bg-blue-50 hover:text-blue-600 border-t border-slate-50 transition-colors ${selectedUser === c.id ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex bg-slate-100 p-1 rounded-xl">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${
                  period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-solid fa-comments', from: 'from-blue-500', to: 'to-blue-600', shadow: 'shadow-blue-200' },
          { label: 'Tỷ lệ giải quyết', value: `${successRate}%`, icon: 'fa-solid fa-wand-magic-sparkles', from: 'from-emerald-500', to: 'to-emerald-600', shadow: 'shadow-emerald-200' },
          { label: 'Cần hỗ trợ', value: totalQueries - totalSolved, icon: 'fa-solid fa-headset', from: 'from-rose-500', to: 'to-rose-600', shadow: 'shadow-rose-200' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-3xl shadow-lg shadow-slate-200/50 border border-slate-100 flex items-center space-x-5 hover:-translate-y-1 transition-transform duration-300">
            <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${stat.from} ${stat.to} flex items-center justify-center shrink-0 shadow-lg ${stat.shadow} text-white`}>
              <i className={`${stat.icon} text-2xl`}></i>
            </div>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-800">{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-3xl shadow-xl shadow-slate-200/40 border border-slate-100">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
          <div>
            <h3 className="text-lg font-bold text-slate-800">Biểu đồ tăng trưởng</h3>
            <p className="text-xs text-slate-400 font-medium">Số lượng câu hỏi theo thời gian</p>
          </div>
          <div className="flex items-center space-x-6 bg-slate-50 px-4 py-2 rounded-xl">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-blue-500 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Tổng lượt hỏi</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-emerald-500 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Đã giải quyết</span>
            </div>
          </div>
        </div>

        <div className="h-[400px] w-full">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <i className="fa-solid fa-circle-notch animate-spin text-blue-500 text-3xl mb-3"></i>
              <p className="text-sm font-bold text-slate-400">Đang tải dữ liệu...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorSolved" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 600}} 
                  dy={10} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 600}} 
                />
                <Tooltip 
                  cursor={{stroke: '#cbd5e1', strokeWidth: 1, strokeDasharray: '4 4'}}
                  contentStyle={{ 
                    borderRadius: '16px', 
                    border: 'none', 
                    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', 
                    padding: '12px 16px',
                    fontWeight: 600,
                    fontSize: '12px',
                    backgroundColor: 'rgba(255, 255, 255, 0.95)'
                  }}
                  formatter={(value, name) => [value, name === 'queries' ? 'Tổng lượt hỏi' : 'Đã giải quyết']}
                />
                <Area 
                  type="monotone" 
                  dataKey="queries" 
                  name="Tổng lượt hỏi"
                  stroke="#3b82f6" 
                  fillOpacity={1} 
                  fill="url(#colorQueries)" 
                  strokeWidth={3} 
                  activeDot={{r: 6}} 
                />
                <Area 
                  type="monotone" 
                  dataKey="solved" 
                  name="Đã giải quyết"
                  stroke="#10b981" 
                  fillOpacity={1} 
                  fill="url(#colorSolved)" 
                  strokeWidth={3} 
                />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                 <i className="fa-solid fa-chart-line text-3xl opacity-30"></i>
               </div>
               <p className="text-sm font-bold">Chưa có dữ liệu nào</p>
               <p className="text-xs mt-1">Hệ thống sẽ hiển thị biểu đồ khi có tương tác.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

