import React, { useState, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(setCustomers);
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  const getSelectedUserLabel = () => {
    if (selectedUser === 'all') return 'Toàn bộ hệ thống';
    const found = customers.find(c => c.id === selectedUser);
    return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white/60 backdrop-blur-md p-6 rounded-[2rem] border border-white shadow-lg shadow-pink-100/50">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight mb-1 flex items-center gap-2">
            <span className="text-2xl">📊</span> Hiệu suất bé AI
          </h2>
          <p className="text-sm text-slate-500 font-bold">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Theo dõi sự chăm chỉ của AI theo thời gian thực nha.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto items-center">
          {isMaster && (
            <div className="relative flex-1 lg:flex-none w-full lg:w-64 z-20" ref={dropdownRef}>
              <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-5 py-3 bg-white border border-pink-100 rounded-2xl text-sm font-bold hover:border-pink-300 transition-all text-slate-700 shadow-sm"
              >
                <span className="truncate">{getSelectedUserLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-pink-300 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 w-full mt-2 bg-white border border-pink-100 rounded-2xl shadow-xl overflow-hidden max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200 z-50">
                  <div 
                    onClick={() => { setSelectedUser('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-bold cursor-pointer hover:bg-pink-50 hover:text-pink-600 transition-colors ${selectedUser === 'all' ? 'bg-pink-50 text-pink-600' : 'text-slate-600'}`}
                  >
                    Toàn bộ hệ thống
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUser(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-bold cursor-pointer hover:bg-pink-50 hover:text-pink-600 border-t border-slate-50 transition-colors ${selectedUser === c.id ? 'bg-pink-50 text-pink-600' : 'text-slate-600'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex bg-white p-1.5 rounded-2xl border border-pink-100 shadow-sm">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-4 py-2 text-xs font-bold rounded-xl transition-all ${
                  period === p ? 'bg-pink-100 text-pink-600 shadow-inner' : 'text-slate-400 hover:text-pink-400'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-solid fa-comments', from: 'from-pink-400', to: 'to-rose-400', shadow: 'shadow-pink-200', text: 'text-pink-500' },
          { label: 'Đã giải quyết', value: `${successRate}%`, icon: 'fa-solid fa-wand-magic-sparkles', from: 'from-purple-400', to: 'to-violet-500', shadow: 'shadow-purple-200', text: 'text-purple-500' },
          { label: 'Cần hỗ trợ', value: totalQueries - totalSolved, icon: 'fa-solid fa-headset', from: 'from-yellow-400', to: 'to-orange-400', shadow: 'shadow-orange-200', text: 'text-orange-500' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] shadow-[0_10px_30px_-10px_rgba(0,0,0,0.05)] border border-white flex items-center space-x-5 hover:-translate-y-2 hover:shadow-lg transition-all duration-300 group">
            <div className={`w-16 h-16 rounded-3xl bg-gradient-to-br ${stat.from} ${stat.to} flex items-center justify-center shrink-0 shadow-lg ${stat.shadow} text-white text-2xl group-hover:scale-110 transition-transform`}>
              <i className={`${stat.icon}`}></i>
            </div>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{stat.label}</p>
              <h3 className={`text-4xl font-black ${stat.text}`}>{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-[2.5rem] shadow-xl shadow-slate-200/40 border border-white relative overflow-hidden">
        {/* Background blobs for chart */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-pink-50 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 opacity-50"></div>

        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8 relative z-10">
          <div>
            <h3 className="text-xl font-bold text-slate-800">Biểu đồ tăng trưởng</h3>
            <p className="text-xs text-slate-400 font-bold mt-1">Xu hướng câu hỏi theo thời gian</p>
          </div>
          <div className="flex items-center space-x-6 bg-slate-50 px-5 py-3 rounded-2xl border border-slate-100">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-pink-400 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Tổng lượt hỏi</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-purple-400 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Đã giải quyết</span>
            </div>
          </div>
        </div>

        <div className="h-[400px] w-full relative z-10">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <i className="fa-solid fa-circle-notch animate-spin text-pink-400 text-3xl mb-3"></i>
              <p className="text-sm font-bold text-slate-400">Đang tải dữ liệu bé AI...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#f472b6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#f472b6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorSolved" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#a78bfa" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#a78bfa" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f9ff" />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 12, fontWeight: 700}} 
                  dy={10} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 12, fontWeight: 700}} 
                />
                <Tooltip 
                  cursor={{stroke: '#fbcfe8', strokeWidth: 2, strokeDasharray: '4 4'}}
                  contentStyle={{ 
                    borderRadius: '20px', 
                    border: 'none', 
                    boxShadow: '0 10px 25px -5px rgba(236,72,153, 0.2)', 
                    padding: '16px 20px',
                    fontWeight: 700,
                    fontSize: '13px',
                    backgroundColor: 'rgba(255, 255, 255, 0.95)',
                    color: '#475569'
                  }}
                  itemStyle={{ paddingBottom: '4px' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="queries" 
                  name="Tổng lượt hỏi"
                  stroke="#f472b6" 
                  fillOpacity={1} 
                  fill="url(#colorQueries)" 
                  strokeWidth={4} 
                  activeDot={{r: 8, strokeWidth: 0, fill: '#ec4899'}} 
                />
                <Area 
                  type="monotone" 
                  dataKey="solved" 
                  name="Đã giải quyết"
                  stroke="#a78bfa" 
                  fillOpacity={1} 
                  fill="url(#colorSolved)" 
                  strokeWidth={4} 
                  activeDot={{r: 8, strokeWidth: 0, fill: '#8b5cf6'}}
                />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <div className="w-24 h-24 bg-pink-50 rounded-full flex items-center justify-center mb-4">
                 <i className="fa-solid fa-chart-line text-4xl text-pink-200"></i>
               </div>
               <p className="text-lg font-bold">Chưa có dữ liệu nào</p>
               <p className="text-sm mt-1">Hệ thống sẽ hiển thị biểu đồ khi có tương tác.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

