                 <button onClick={() => setResetModal({ isOpen: false, userId: null, email: '' })} className="py-3.5 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-colors">Hủy nha</button>
                 <button onClick={handleResetPassword} className="py-3.5 bg-amber-500 text-white rounded-2xl font-bold hover:bg-amber-600 transition-colors shadow-lg shadow-amber-200">Xác nhận</button>
