             <div className="p-8 text-center">
               <div className="w-20 h-20 bg-rose-100 text-rose-500 rounded-3xl flex items-center justify-center mx-auto mb-5 text-3xl shadow-lg shadow-rose-200 transform -rotate-12">
                 <i className="fa-solid fa-trash-can"></i>
