import React, { useState } from 'react';
import { Document } from '../types';

interface Props {
  userId: string;
  documents: Document[];
  onAddDocument: (name: string, content: string, type: 'text' | 'file') => void;
  onDeleteDocument: (id: string) => void;
}

const KnowledgeBase: React.FC<Props> = ({ userId, documents, onAddDocument, onDeleteDocument }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [newDocText, setNewDocText] = useState('');
  const [newDocName, setNewDocName] = useState('');

  const handleManualAdd = async () => {
    if (!newDocName || !newDocText) return;
    setIsProcessing(true);
    await onAddDocument(newDocName, newDocText, 'text');
    setNewDocName('');
    setNewDocText('');
    setIsProcessing(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      await onAddDocument(file.name, content, 'file');
      setIsProcessing(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-3 duration-500 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-8 rounded-[2rem] border border-white shadow-lg shadow-purple-50">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-3">
            <span className="w-12 h-12 rounded-2xl bg-indigo-100 text-indigo-500 flex items-center justify-center text-xl shadow-sm rotate-3">
               <i className="fa-solid fa-brain"></i>
            </span>
            Kho tri thức AI
          </h2>
          <p className="text-sm text-slate-500 font-bold mt-2 ml-1">Nạp dữ liệu để AI thông minh hơn nè.</p>
        </div>
        <div className="w-full md:w-auto">
           <label className="cursor-pointer bg-gradient-to-r from-indigo-500 to-purple-500 hover:from-indigo-600 hover:to-purple-600 text-white px-8 py-4 rounded-full font-bold transition-all flex items-center justify-center shadow-lg shadow-indigo-200 active:scale-95 transform hover:-translate-y-1">
            <i className="fa-solid fa-cloud-arrow-up mr-2 text-lg"></i>
            Tải tài liệu lên
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".txt,.md,.json" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/40 border border-white overflow-hidden p-2">
            <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[600px] border-separate border-spacing-y-2">
                <thead>
                  <tr>
                    <th className="px-6 py-3 text-xs font-bold text-slate-400 uppercase tracking-wider pl-6">Tên tài liệu</th>
                    <th className="px-6 py-3 text-xs font-bold text-slate-400 uppercase tracking-wider">Định dạng</th>
                    <th className="px-6 py-3 text-xs font-bold text-slate-400 uppercase tracking-wider">Trạng thái</th>
                    <th className="px-6 py-3 text-xs font-bold text-slate-400 uppercase tracking-wider text-right pr-6">Thao tác</th>
                  </tr>
                </thead>
                <tbody>
                  {documents.map(doc => (
                    <tr key={doc.id} className="bg-slate-50 hover:bg-purple-50 transition-colors group rounded-2xl">
                      <td className="px-6 py-4 rounded-l-2xl">
                        <div className="flex items-center min-w-0">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 shrink-0 shadow-sm border-2 border-white ${doc.type === 'file' ? 'bg-amber-100 text-amber-500' : 'bg-blue-100 text-blue-500'}`}>
                            <i className={`fa-solid ${doc.type === 'file' ? 'fa-file-lines' : 'fa-align-left'} text-lg`}></i>
                          </div>
                          <div className="truncate">
                            <p className="font-bold text-sm text-slate-800 truncate group-hover:text-purple-600 transition-colors">{doc.name}</p>
                            <p className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded-full inline-block mt-1 shadow-sm border border-slate-100">{new Date(doc.createdAt).toLocaleDateString('vi-VN')}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-[10px] font-black px-3 py-1 bg-white text-slate-500 rounded-full uppercase tracking-wider border border-slate-100 shadow-sm">
                          {doc.type}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span className="inline-flex items-center text-[10px] font-extrabold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100">
                          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 mr-1.5 animate-pulse"></span>
                          Đã học thuộc
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right rounded-r-2xl">
                        <button 
                          onClick={() => onDeleteDocument(doc.id)} 
                          className="w-10 h-10 rounded-full bg-white hover:bg-rose-50 text-slate-300 hover:text-rose-500 transition-all flex items-center justify-center border border-slate-100 hover:border-rose-100 shadow-sm hover:scale-110 ml-auto"
                          title="Xóa tài liệu"
                        >
                          <i className="fa-solid fa-trash-can text-sm"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                  {documents.length === 0 && (
                    <tr>
                      <td colSpan={4} className="px-8 py-24 text-center">
                        <div className="flex flex-col items-center">
                          <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center text-indigo-200 mb-6 border-4 border-white shadow-sm">
                            <i className="fa-solid fa-folder-open text-4xl"></i>
                          </div>
                          <h3 className="text-base font-bold text-slate-800">Trống trơn à</h3>
                          <p className="text-sm font-medium text-slate-400 mt-2 max-w-xs mx-auto">Thêm tài liệu để AI học nhé.</p>
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-lg shadow-slate-200/40 border border-white">
            <h3 className="font-bold text-slate-800 mb-6 flex items-center text-lg">
              <i className="fa-solid fa-pen-nib text-pink-500 mr-2"></i>
              Soạn thảo nhanh
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Tiêu đề</label>
                <input 
                  type="text" 
                  value={newDocName} 
                  onChange={(e) => setNewDocName(e.target.value)} 
                  placeholder="Ví dụ: Chính sách bảo hành" 
                  className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-50 rounded-2xl outline-none focus:border-pink-300 focus:bg-white text-sm font-bold transition-all text-slate-700" 
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Nội dung</label>
                <textarea 
                  rows={8} 
                  value={newDocText} 
                  onChange={(e) => setNewDocText(e.target.value)} 
                  placeholder="Nhập nội dung chi tiết..." 
                  className="w-full px-5 py-3.5 bg-slate-50 border-2 border-slate-50 rounded-2xl outline-none focus:border-pink-300 focus:bg-white text-sm font-medium transition-all resize-none text-slate-700" 
                />
              </div>
              <button 
                onClick={handleManualAdd} 
                disabled={!newDocName || !newDocText || isProcessing} 
                className="w-full bg-slate-800 hover:bg-slate-900 text-white py-4 rounded-2xl font-bold transition-all disabled:opacity-50 shadow-lg shadow-slate-300 active:scale-95 flex items-center justify-center gap-2"
              >
                {isProcessing ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <><i className="fa-solid fa-save"></i> Lưu dữ liệu</>}
              </button>
            </div>
          </div>

          <div className="bg-gradient-to-br from-pink-500 to-purple-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-pink-200 relative overflow-hidden group">
            <div className="relative z-10">
              <h4 className="font-bold text-lg mb-2">Mẹo nhỏ nè ✨</h4>
              <p className="text-xs font-semibold text-pink-100 leading-relaxed mb-4">
                Sử dụng cấu trúc rõ ràng (Tiêu đề, gạch đầu dòng) sẽ giúp bé AI trả lời chính xác hơn đó nha.
              </p>
              <div className="flex items-center text-xs font-bold text-white hover:text-pink-100 cursor-pointer transition-colors bg-white/20 px-4 py-2 rounded-full w-fit backdrop-blur-sm hover:bg-white/30">
                <i className="fa-solid fa-lightbulb mr-2"></i>
                Xem ví dụ mẫu
              </div>
            </div>
            <div className="absolute -right-6 -bottom-6 w-32 h-32 bg-white/20 rounded-full blur-2xl group-hover:scale-150 transition-transform duration-700"></div>
            <div className="absolute top-4 right-4 text-4xl opacity-20 rotate-12">
              <i className="fa-solid fa-wand-magic-sparkles"></i>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

