                 value={passwordForm.old}
                 onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Mật khẩu mới</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 border-2 border-transparent focus:border-indigo-300 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white transition-all text-slate-700 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.new}
                 onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-xs font-bold text-slate-400 uppercase mb-2 ml-2">Xác nhận lại</label>
               <input 
                 type="password" 
                 required
                 className="w-full px-6 py-4 bg-slate-50 border-2 border-transparent focus:border-indigo-300 rounded-2xl text-sm font-bold focus:outline-none focus:bg-white transition-all text-slate-700 placeholder-slate-300"
                 placeholder="••••••"
                 value={passwordForm.confirm}
                 onChange={e => setPasswordForm({...passwordForm, confirm: e.target.value})}
               />
             </div>

             <button type="submit" className="w-full py-4 bg-slate-800 hover:bg-slate-900 text-white rounded-2xl font-bold shadow-lg shadow-slate-300 transition-all active:scale-[0.98] mt-2">
               Cập nhật ngay
             </button>
          </form>
        </div>
      </div>
    )}
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(setCustomers);
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  const getSelectedUserLabel = () => {
    if (selectedUser === 'all') return 'Toàn bộ hệ thống';
    const found = customers.find(c => c.id === selectedUser);
    return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white/60 backdrop-blur-md p-6 rounded-[2rem] border border-white shadow-lg shadow-indigo-50/50">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight mb-1 flex items-center gap-2">
            <span className="text-2xl">📊</span> Hiệu suất AI
          </h2>
          <p className="text-sm text-slate-500 font-bold">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Theo dõi sự chăm chỉ của AI theo thời gian thực.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto items-center">
          {isMaster && (
            <div className="relative flex-1 lg:flex-none w-full lg:w-64 z-20" ref={dropdownRef}>
              <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-5 py-3 bg-white border border-indigo-100 rounded-2xl text-sm font-bold hover:border-indigo-300 transition-all text-slate-700 shadow-sm"
              >
                <span className="truncate">{getSelectedUserLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-indigo-300 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 w-full mt-2 bg-white border border-indigo-100 rounded-2xl shadow-xl overflow-hidden max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200 z-50">
                  <div 
                    onClick={() => { setSelectedUser('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-bold cursor-pointer hover:bg-indigo-50 hover:text-indigo-600 transition-colors ${selectedUser === 'all' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600'}`}
                  >
                    Toàn bộ hệ thống
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUser(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-bold cursor-pointer hover:bg-indigo-50 hover:text-indigo-600 border-t border-slate-50 transition-colors ${selectedUser === c.id ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex bg-white p-1.5 rounded-2xl border border-indigo-100 shadow-sm">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-4 py-2 text-xs font-bold rounded-xl transition-all ${
                  period === p ? 'bg-indigo-100 text-indigo-600 shadow-inner' : 'text-slate-400 hover:text-indigo-400'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Tổng lượt hỏi', value: totalQueries, icon: 'fa-solid fa-comments', from: 'from-blue-400', to: 'to-indigo-500', shadow: 'shadow-blue-200', text: 'text-indigo-600' },
          { label: 'Đã giải quyết', value: `${successRate}%`, icon: 'fa-solid fa-wand-magic-sparkles', from: 'from-teal-400', to: 'to-emerald-500', shadow: 'shadow-emerald-200', text: 'text-teal-600' },
          { label: 'Cần hỗ trợ', value: totalQueries - totalSolved, icon: 'fa-solid fa-headset', from: 'from-amber-400', to: 'to-orange-400', shadow: 'shadow-orange-200', text: 'text-orange-500' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] shadow-[0_10px_30px_-10px_rgba(0,0,0,0.05)] border border-white flex items-center space-x-5 hover:-translate-y-2 hover:shadow-lg transition-all duration-300 group">
            <div className={`w-16 h-16 rounded-3xl bg-gradient-to-br ${stat.from} ${stat.to} flex items-center justify-center shrink-0 shadow-lg ${stat.shadow} text-white text-2xl group-hover:scale-110 transition-transform`}>
              <i className={`${stat.icon}`}></i>
            </div>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{stat.label}</p>
              <h3 className={`text-4xl font-black ${stat.text}`}>{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-[2.5rem] shadow-xl shadow-slate-200/40 border border-white relative overflow-hidden">
        {/* Background blobs for chart */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 opacity-50"></div>

        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8 relative z-10">
          <div>
            <h3 className="text-xl font-bold text-slate-800">Biểu đồ tăng trưởng</h3>
            <p className="text-xs text-slate-400 font-bold mt-1">Xu hướng câu hỏi theo thời gian</p>
          </div>
          <div className="flex items-center space-x-6 bg-slate-50 px-5 py-3 rounded-2xl border border-slate-100">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-indigo-400 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Tổng lượt hỏi</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-teal-400 rounded-full"></span>
              <span className="text-xs font-bold text-slate-600">Đã giải quyết</span>
            </div>
          </div>
        </div>

        <div className="h-[400px] w-full relative z-10">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <i className="fa-solid fa-circle-notch animate-spin text-indigo-400 text-3xl mb-3"></i>
              <p className="text-sm font-bold text-slate-400">Đang tải dữ liệu...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorSolved" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#14b8a6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#14b8a6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f9ff" />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 12, fontWeight: 700}} 
                  dy={10} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 12, fontWeight: 700}} 
                />
                <Tooltip 
                  cursor={{stroke: '#cbd5e1', strokeWidth: 2, strokeDasharray: '4 4'}}
                  contentStyle={{ 
                    borderRadius: '20px', 
                    border: 'none', 
                    boxShadow: '0 10px 25px -5px rgba(99,102,241, 0.2)', 
                    padding: '16px 20px',
                    fontWeight: 700,
                    fontSize: '13px',
                    backgroundColor: 'rgba(255, 255, 255, 0.95)',
                    color: '#475569'
                  }}
                  itemStyle={{ paddingBottom: '4px' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="queries" 
                  name="Tổng lượt hỏi"
                  stroke="#6366f1" 
                  fillOpacity={1} 
                  fill="url(#colorQueries)" 
                  strokeWidth={4} 
                  activeDot={{r: 8, strokeWidth: 0, fill: '#4f46e5'}} 
                />
                <Area 
                  type="monotone" 
                  dataKey="solved" 
                  name="Đã giải quyết"
                  stroke="#14b8a6" 
                  fillOpacity={1} 
                  fill="url(#colorSolved)" 
                  strokeWidth={4} 
                  activeDot={{r: 8, strokeWidth: 0, fill: '#0d9488'}}
                />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300">
               <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mb-4">
                 <i className="fa-solid fa-chart-line text-4xl text-indigo-200"></i>
               </div>
               <p className="text-lg font-bold">Chưa có dữ liệu nào</p>
               <p className="text-sm mt-1">Hệ thống sẽ hiển thị biểu đồ khi có tương tác.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  onViewStats: (userId: string) => void;
}

const CustomerManagement: React.FC<Props> = ({ onViewStats }) => {
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // States for Modals
  const [resetModal, setResetModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [newResetPassword, setNewResetPassword] = useState('');
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [actionMsg, setActionMsg] = useState<{ type: string, text: string }>({ type: '', text: '' });

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    setIsLoading(true);
    try {
      const data = await apiService.getAllUsers();
      const filtered = data.filter(u => u.role !== 'master');
      setCustomers(filtered);
    } catch (err) {
      console.error("Lỗi khi tải khách hàng:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!resetModal.userId || !newResetPassword) return;
    try {
      const result = await apiService.resetUserPassword(resetModal.userId, newResetPassword);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã đổi pass cho ${resetModal.email}` });
        setResetModal({ isOpen: false, userId: null, email: '' });
        setNewResetPassword('');
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const handleDeleteUser = async () => {
    if (!deleteModal.userId) return;
    try {
      const result = await apiService.deleteUser(deleteModal.userId);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã xóa bé ${deleteModal.email}` });
        setDeleteModal({ isOpen: false, userId: null, email: '' });
        loadCustomers(); 
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const filteredCustomers = customers.filter(c => 
    c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.botSettings.botName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Toast Notification */}
      {actionMsg.text && (
        <div className={`fixed top-6 right-6 z-[100] px-6 py-4 rounded-3xl shadow-xl border flex items-center animate-in slide-in-from-right duration-300 ${actionMsg.type === 'success' ? 'bg-white border-emerald-100 text-emerald-600' : 'bg-white border-rose-100 text-rose-600'}`}>
          <i className={`fa-solid ${actionMsg.type === 'success' ? 'fa-check-circle' : 'fa-heart-crack'} text-xl mr-3`}></i>
          <span className="font-bold text-sm">{actionMsg.text}</span>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-[2rem] border border-white shadow-lg shadow-indigo-50/50">
        <div className="flex items-center gap-4">
            <div>
              <h2 className="text-xl font-bold text-slate-800 flex items-center">
                <span className="w-10 h-10 rounded-2xl bg-indigo-100 text-indigo-500 flex items-center justify-center mr-3 text-lg">
                  <i className="fa-solid fa-users"></i>
                </span>
                Quản lý khách hàng
              </h2>
            </div>
            <button 
              onClick={loadCustomers}
              disabled={isLoading}
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-50 text-slate-400 hover:bg-indigo-100 hover:text-indigo-500 transition-all active:scale-90 border border-slate-100 shadow-sm"
              title="Làm mới danh sách"
            >
              <i className={`fa-solid fa-arrows-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
            </button>
        </div>
        <div className="relative w-full md:w-80 group">
          <i className="fa-solid fa-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors"></i>
          <input 
            type="text" 
            placeholder="Tìm theo email hoặc tên bot..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-5 py-3.5 bg-slate-50 border-2 border-slate-50 rounded-full focus:border-indigo-300 focus:bg-white outline-none text-sm font-bold transition-all text-slate-700"
          />
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-white overflow-hidden p-2">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-slate-50">
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider pl-8">Khách hàng</th>
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-center">Tên AI Bot</th>
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">Ngày tham gia</th>
                <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-right pr-8">Hành động</th>
              </tr>
            </thead>
            <tbody className="space-y-2">
              {isLoading ? (
                <tr>
                  <td colSpan={4} className="px-8 py-24 text-center">
                    <i className="fa-solid fa-circle-notch animate-spin text-indigo-400 text-3xl"></i>
                    <p className="text-sm font-bold text-slate-400 mt-4">Đang tìm kiếm...</p>
                  </td>
                </tr>
              ) : filteredCustomers.length > 0 ? (
                filteredCustomers.map(customer => (
                  <tr key={customer.id} className="hover:bg-indigo-50/50 transition-colors group rounded-2xl">
                    <td className="px-6 py-4 pl-8 rounded-l-2xl">
                      <div className="flex items-center">
                        <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-indigo-200 to-purple-200 text-purple-600 flex items-center justify-center font-bold mr-4 text-lg shadow-sm border-2 border-white">
                          {customer.email.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-800">{customer.email}</p>
