export default Login;

import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
const upload = multer({ storage });

app.use(cors() as any);
app.use(express.json() as any);

const DB_FILE = './db.json';
const initDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ 
      users: [
        { id: 'admin', email: 'admin@bibichat.io', password: '123456', role: 'master', botSettings: { botName: 'BibiBot', primaryColor: '#ec4899', welcomeMessage: 'Xin chào! Mình là BibiBot đây.' } }
      ], 
      documents: [],
      chatLogs: []
    }));
  }
};
initDB();

const getDB = () => JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
const saveDB = (data: any) => fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));

// API: Lấy danh sách Users (Cho Master)
app.get('/api/users', (req, res) => {
  const db = getDB();
  // Trả về danh sách users (có thể lọc bỏ password nếu cần bảo mật cao hơn)
  res.json(db.users);
});

// API: Đăng ký
app.post('/api/register', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();

  if (db.users.find((u: any) => u.email === email)) {
    return res.status(400).json({ success: false, message: 'Email đã tồn tại' });
  }

  const newUser = {
    id: Math.random().toString(36).substr(2, 9),
    email,
    password,
    role: 'user',
    createdAt: Date.now(),
    botSettings: {
      botName: 'Trợ lý AI',
      primaryColor: '#8b5cf6',
      welcomeMessage: 'Chào mừng bạn đến với hỗ trợ trực tuyến!',
      position: 'right',
      avatarUrl: ''
    }
  };

  db.users.push(newUser);
  saveDB(db);
  res.json({ success: true, user: newUser });
});

// API: Đăng nhập
app.post('/api/login', (req, res) => {
  const { email, password } = req.body;
  const db = getDB();
  const user = db.users.find((u: any) => u.email === email && u.password === password);

  if (user) {
    res.json({ success: true, user });
  } else {
    res.status(401).json({ success: false, message: 'Sai thông tin đăng nhập' });
  }
});

// API: Đổi mật khẩu (User tự đổi)
app.post('/api/user/change-password', (req, res) => {
  const { userId, oldPassword, newPassword } = req.body;
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === userId);

  if (userIndex === -1) return res.status(404).json({ success: false, message: 'User không tồn tại' });

  if (db.users[userIndex].password !== oldPassword) {
    return res.status(400).json({ success: false, message: 'Mật khẩu cũ không đúng' });
  }

  db.users[userIndex].password = newPassword;
  saveDB(db);
  res.json({ success: true, message: 'Đổi mật khẩu thành công' });
});

// API: Reset mật khẩu (Admin thực hiện)
app.post('/api/admin/reset-password', (req, res) => {
  const { targetUserId, newPassword } = req.body;
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === targetUserId);

  if (userIndex === -1) return res.status(404).json({ success: false, message: 'User không tồn tại' });

  db.users[userIndex].password = newPassword;
  saveDB(db);
  res.json({ success: true, message: 'Reset mật khẩu thành công' });
});

// API: Xóa User (Admin thực hiện)
app.delete('/api/admin/users/:id', (req, res) => {
  const db = getDB();
  const targetId = req.params.id;

  // Xóa user
  const initialUserCount = db.users.length;
  db.users = db.users.filter((u: any) => u.id !== targetId);

  if (db.users.length === initialUserCount) {
    return res.status(404).json({ success: false, message: 'User không tồn tại' });
  }

  // Xóa các dữ liệu liên quan
  // 1. Xóa documents
  const userDocs = db.documents.filter((d: any) => d.userId === targetId);
  userDocs.forEach((doc: any) => {
    if (doc.path && fs.existsSync(doc.path)) {
      try { fs.unlinkSync(doc.path); } catch(e) {}
    }
  });
  db.documents = db.documents.filter((d: any) => d.userId !== targetId);

  // 2. Xóa chat logs
  db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetId);

  saveDB(db);
  res.json({ success: true, message: 'Xóa user thành công' });
});

// API: Lấy tài liệu của riêng User
app.get('/api/documents/:userId', (req, res) => {
  const db = getDB();
  const userDocs = db.documents.filter((d: any) => d.userId === req.params.userId);
  res.json(userDocs);
});

// API: Lưu cấu hình Widget cho User
app.post('/api/settings/:userId', (req, res) => {
  const db = getDB();
  const userIndex = db.users.findIndex((u: any) => u.id === req.params.userId);
  if (userIndex !== -1) {
    db.users[userIndex].botSettings = req.body;
    saveDB(db);
    res.json({ success: true });
  } else {
    res.status(404).json({ success: false });
  }
});

// API: Thêm tài liệu văn bản (có userId)
app.post('/api/documents/text', (req, res) => {
  const { name, content, userId } = req.body;
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name,
    content,
    type: 'text',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Upload tệp (có userId)
app.post('/api/documents/upload', upload.single('file') as any, (req: any, res: any) => {
  const file = (req as any).file;
  const { userId } = req.body;
  if (!file || !userId) return res.status(400).send('Missing file or userId.');

  const content = fs.readFileSync(file.path, 'utf-8');
  const db = getDB();
  const newDoc = {
    id: Math.random().toString(36).substr(2, 9),
    userId,
    name: file.originalname,
    content: content,
    path: file.path,
    type: 'file',
    status: 'indexed',
    createdAt: Date.now()
  };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});

// API: Xóa tài liệu
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) fs.unlinkSync(doc.path);
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});

// API: Chat AI (Chỉ lấy tài liệu của userId đó)
app.post('/api/chat', async (req, res) => {
  const { message, userId, botName } = req.body;
  const db = getDB();

  if (!process.env.API_KEY) return res.status(500).json({ error: "Missing API KEY" });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const context = db.documents
    .filter((d: any) => d.userId === userId)
    .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`)
    .join('\n\n');

  const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy dùng kiến thức sau để hỗ trợ khách hàng: ${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { systemInstruction }
    });

    const reply = response.text || "Tôi không thể trả lời.";

    // Lưu Log
    if (!db.chatLogs) db.chatLogs = [];
    const newLog = {
      id: Math.random().toString(36).substr(2, 9),
      userId,
      customerSessionId: 'anon-session',
      query: message,
      answer: reply,
      timestamp: Date.now(),
      tokens: message.length + reply.length,
      isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
    };
    db.chatLogs.push(newLog);
    saveDB(db);

    res.json({ text: reply });
  } catch (error) {
    res.status(500).json({ error: "AI Error" });
  }
});

app.listen(PORT, () => {
  console.log(`SaaS Backend running at http://localhost:${PORT}`);
});

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole } from "../types";

const API_URL = 'http://localhost:3001/api';
const DB_KEY = 'omnichat_db_v1';

// Cấu hình tài khoản Master mặc định
const MASTER_USER: User = {
  id: 'admin',
  email: 'admin@bibichat.io',
  password: '123456',
  role: 'master',
  createdAt: Date.now(),
  botSettings: { 
    botName: 'BibiBot', 
    primaryColor: '#ec4899', 
    welcomeMessage: 'Xin chào! Hệ thống quản trị Master (Offline Mode).', 
    position: 'right', 
    avatarUrl: '' 
  }
};

// --- HELPER: LOCAL STORAGE FALLBACK ---
const getLocalDB = () => {
  const data = localStorage.getItem(DB_KEY);
  let db;

  if (!data) {
    db = { 
      users: [MASTER_USER], 
      documents: [],
      chatLogs: []
    };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  } else {
    db = JSON.parse(data);
    if (!db.users.find((u: any) => u.id === 'admin')) {
      db.users.unshift(MASTER_USER);
      localStorage.setItem(DB_KEY, JSON.stringify(db));
    }
  }
  return db;
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    // 1. Tạo user object
    const newUser: User = {
      id: Math.random().toString(36).substring(2, 11),
      email,
      password,
      role: 'user',
      createdAt: Date.now(),
      botSettings: {
        botName: 'Trợ lý AI',
        primaryColor: '#8b5cf6',
        welcomeMessage: 'Xin chào!',
        position: 'right',
        avatarUrl: ''
      }
    };

    // 2. Luôn lưu vào LocalStorage (Shadow Save) để đảm bảo Admin nhìn thấy ngay
    const db = getLocalDB();
    if (db.users.find((u: any) => u.email === email)) {
      // Nếu local đã có thì thôi, nhưng vẫn tiếp tục thử gọi server
    } else {
      db.users.push(newUser);
      saveLocalDB(db);
    }

    // 3. Gọi Server (nếu online)
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (res.ok) {
         const serverRes = await res.json();
         // Ưu tiên dùng ID từ server nếu có
         return serverRes;
      }
    } catch (e) {
      console.warn("Server Offline: Registration saved locally.");
    }

    // Trả về kết quả thành công dựa trên LocalStorage
    return { success: true, message: 'Đăng ký thành công (Offline/Hybrid)', user: newUser };
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (!res.ok) throw new Error("Server response not ok");
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();

      let user = db.users.find((u: any) => u.email === email && u.password === password);

      if (!user && email === MASTER_USER.email && password === MASTER_USER.password) {
        user = MASTER_USER;
        if (!db.users.find((u: any) => u.id === 'admin')) {
           db.users.unshift(MASTER_USER);
           saveLocalDB(db);
        }
      }

      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx === -1) return { success: false, message: "User không tồn tại" };
      if (db.users[idx].password !== oldPassword) return { success: false, message: "Mật khẩu cũ sai" };
      db.users[idx].password = newPassword;
      saveLocalDB(db);
      return { success: true, message: "Đổi mật khẩu thành công (Offline)" };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    const localDB = getLocalDB();
    const localUsers: User[] = localDB.users;

    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) throw new Error("Server error");
      const serverUsers: User[] = await res.json();

      // Merge: Lấy tất cả user từ Local + Server, loại bỏ trùng lặp email
      const map = new Map();

      // Ưu tiên local users trước để đảm bảo những user vừa tạo (chưa sync server) được hiện
      [...localUsers, ...serverUsers].forEach(u => {
        if (!map.has(u.email)) {
          map.set(u.email, u);
        }
      });

      const combinedUsers = Array.from(map.values());
      return combinedUsers.filter((u: any) => u.id !== 'admin'); 
    } catch (e) {
      return localUsers.filter(u => u.id !== 'admin');
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === targetUserId);
      if (idx !== -1) {
        db.users[idx].password = newPassword;
        saveLocalDB(db);
        return { success: true, message: "Reset thành công (Offline)" };
      }
      return { success: false, message: "Lỗi Offline" };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      db.documents = db.documents.filter((d: any) => d.userId !== targetUserId);
      db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Offline)" };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    try {
      await fetch(`${API_URL}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx !== -1) {
        db.users[idx].botSettings = settings;
        saveLocalDB(db);
      }
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      if (!res.ok) throw new Error("Server error");
      const doc = await res.json();
      if (type === 'file') doc.type = 'file'; 
      return doc;
    } catch (e) {
      const db = getLocalDB();
      const newDoc: Document = {
        id: Math.random().toString(36).substring(2, 11),
        userId,
        name,
        content,
        type,
        status: 'indexed',
        createdAt: Date.now()
      };
      db.documents.push(newDoc);
      saveLocalDB(db);
      return newDoc;
    }
  },

  deleteDocument: async (id: string) => {
    try {
      await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }

    const statsMap: Record<string, { queries: number, solved: number }> = {};

    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);

      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;

      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });

    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];
    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }
    return logs.sort((a, b) => b.timestamp - a.timestamp);
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    let context = "";
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if(res.ok) {
        const docs: Document[] = await res.json();
        context = docs.map(d => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      } else { throw new Error("API Docs Error"); }
    } catch (e) {
       const db = getLocalDB();
       context = db.documents.filter((d: any) => d.userId === userId)
         .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
    }

    if (!process.env.API_KEY) return "Vui lòng cấu hình API_KEY.";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau: \n${context}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: message,
        config: { systemInstruction }
      });

      const reply = response.text || "Tôi không thể trả lời.";

      const db = getLocalDB();
      const newLog: ChatLog = {
        id: Math.random().toString(36).substring(2, 9),
        userId,
        customerSessionId: 'anon-session',
        query: message,
        answer: reply,
        timestamp: Date.now(),
        tokens: message.length + (reply?.length || 0),
        isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
      };
      db.chatLogs.push(newLog);
      saveLocalDB(db);

      return reply;
    } catch (e) {
      console.error(e);
      return "Lỗi AI hoặc mất kết nối mạng.";
    }
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  userId: string;
}

const ChatWidget: React.FC<Props> = ({ settings, userId }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  useEffect(() => {
    if (messages.length === 1 && messages[0].id === '1') {
      setMessages([{ ...messages[0], text: settings.welcomeMessage }]);
    }
  }, [settings.welcomeMessage]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await apiService.chat(userId, input, settings.botName);
      const botMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: responseText, timestamp: Date.now() };
      setMessages(prev => [...prev, botMsg]);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Hệ thống đang bận. Vui lòng thử lại sau.", timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={`fixed bottom-6 ${settings.position === 'right' ? 'right-6' : 'left-6'} z-[9999] font-sans`}>
      <button 
        onClick={() => setIsOpen(!isOpen)} 
        className="w-16 h-16 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl transition-all hover:scale-110 active:scale-95 duration-300 relative group" 
        style={{ backgroundColor: settings.primaryColor }}
      >
        <span className="absolute inset-0 rounded-full bg-white opacity-20 group-hover:animate-ping"></span>
        {isOpen ? <i className="fa-solid fa-xmark"></i> : <i className="fa-solid fa-comment-dots"></i>}
      </button>

      {isOpen && (
        <div className={`absolute bottom-24 ${settings.position === 'right' ? 'right-0' : 'left-0'} w-[calc(100vw-3rem)] sm:w-[380px] h-[550px] bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in slide-in-from-bottom-10 duration-300 border border-slate-100/50`}>
          {/* Header */}
          <div className="p-5 text-white relative overflow-hidden" style={{ backgroundColor: settings.primaryColor }}>
            <div className="absolute top-0 right-0 p-4 opacity-10">
               <i className="fa-solid fa-robot text-6xl"></i>
            </div>
            <div className="flex items-center space-x-3 relative z-10">
              <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center border-2 border-white/30 backdrop-blur-sm">
                <i className="fa-solid fa-robot text-xl"></i>
              </div>
              <div>
                <h3 className="font-bold text-lg">{settings.botName}</h3>
                <div className="flex items-center text-xs opacity-90 font-medium bg-white/20 px-2 py-0.5 rounded-full w-fit mt-1">
                  <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full mr-1.5 animate-pulse"></span>
                  Trực tuyến
                </div>
              </div>
            </div>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 p-5 bg-slate-50 space-y-4 overflow-y-auto">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-3 text-sm font-medium shadow-sm leading-relaxed ${
                  msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-2xl rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-100 rounded-2xl rounded-tl-none'
                }`} style={msg.role === 'user' ? { backgroundColor: settings.primaryColor } : {}}>
                  <p className="whitespace-pre-wrap">{msg.text}</p>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white px-4 py-3 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm flex space-x-1.5 items-center">
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-4 bg-white border-t border-slate-100">
            <div className="flex items-center space-x-2 bg-slate-50 p-1.5 rounded-full border border-slate-200 focus-within:ring-2 focus-within:ring-blue-100 focus-within:border-blue-400 transition-all">
              <input 
                type="text" 
                value={input} 
                onChange={(e) => setInput(e.target.value)} 
                onKeyPress={(e) => e.key === 'Enter' && handleSend()} 
                placeholder="Nhập tin nhắn..." 
                className="flex-1 text-sm bg-transparent outline-none px-4 py-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                disabled={isLoading} 
              />
              <button 
                onClick={handleSend} 
                className="w-10 h-10 rounded-full text-white flex items-center justify-center transition-transform active:scale-90 shadow-md"
                style={{ backgroundColor: settings.primaryColor }}
              >
                <i className="fa-solid fa-paper-plane text-sm"></i>
