import React, { useState } from 'react';
import { View, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  currentView: View;
  onViewChange: (view: View) => void;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
  user: User;
}

