                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-pink-100 dark:bg-pink-900/30 text-pink-500 rounded-xl flex items-center justify-center text-xl shadow-sm">
                     <i className="fa-solid fa-bell"></i>
