                   >
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${notif.bg} ${notif.color} shadow-sm text-xl relative`}>
                         <i className={`fa-solid ${notif.icon}`}></i>
                         {!notif.isRead && <span className="absolute -top-1 -right-1 w-3 h-3 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>}
                      </div>
                      <div className="flex-1">
                         <div className="flex justify-between items-start mb-1">
                            <h4 className={`font-bold ${!notif.isRead ? 'text-slate-900 dark:text-white' : 'text-slate-700 dark:text-slate-300'}`}>{notif.title}</h4>
                            <span className="text-[10px] font-bold text-slate-400 bg-white dark:bg-slate-800 px-2 py-0.5 rounded-full border border-slate-200 dark:border-slate-600">{new Date(notif.time).toLocaleString('vi-VN')}</span>
                         </div>
                         <p className="text-sm text-slate-500 dark:text-slate-300 leading-relaxed">{notif.desc}</p>
                      </div>
                   </div>
                 ))}
                 <div className="text-center py-6">
                    <p className="text-sm font-bold text-slate-400">Bạn đã xem hết danh sách rồi nha! 🎉</p>
                 </div>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

