                </button>
             </form>
          </div>

          {/* Preview & History */}
          <div className="space-y-6">
             {/* Live Preview Card */}
             <div className="bg-slate-50 dark:bg-slate-900 p-6 rounded-[2.5rem] border-2 border-dashed border-slate-200 dark:border-slate-700">
