                <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex gap-4">
                   <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${selectedColor.bg} ${selectedColor.text} shadow-sm relative`}>
                      <i className={`fa-solid ${selectedIcon} text-lg`}></i>
                      <span className="absolute -top-1 -right-1 w-3 h-3 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>
                   </div>
                   <div className="min-w-0 flex-1">
                      <h4 className="text-sm font-black text-slate-800 dark:text-white truncate">{title || 'Tiêu đề thông báo...'}</h4>
                      <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed line-clamp-2">{desc || 'Nội dung thông báo sẽ hiện ở đây...'}</p>
                      <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold mt-1.5">
                        {(!sendImmediately && scheduleTime) ? formatVietnameseDate(new Date(scheduleTime).getTime()) : 'Vừa xong'}
                      </p>
                   </div>
                </div>
             </div>

             {/* History List with Infinite Scroll */}
             <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-700 overflow-hidden flex flex-col h-[400px]">
                <div className="p-5 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-700/30">
                   <h3 className="font-bold text-slate-700 dark:text-slate-300 text-sm">Lịch sử đã tạo ({history.length})</h3>
                </div>

                {isLoading ? (
                   <div className="flex flex-col items-center justify-center h-full space-y-4">
                      <div className="w-16 h-16 bg-indigo-50 dark:bg-indigo-900/30 rounded-full flex items-center justify-center animate-bounce">
                         <i className="fa-solid fa-robot text-indigo-500 text-2xl"></i>
                      </div>
                      <p className="text-xs font-bold text-slate-400 animate-pulse">Đang tải lịch sử nè...</p>
                   </div>
                ) : (
                  <div 
                    className="flex-1 overflow-y-auto p-4 space-y-3 scroll-smooth"
                    ref={historyScrollRef}
                    onScroll={handleHistoryScroll}
                  >
                     {history.length > 0 ? (
                        <>
                          {history.slice(0, visibleHistoryCount).map(h => (
                            <div 
                              key={h.id} 
                              onClick={() => setSelectedHistoryItem(h)}
                              className="flex gap-3 p-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors border border-transparent hover:border-slate-100 dark:hover:border-slate-600 cursor-pointer group"
                            >
                               <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${h.bg} ${h.color} text-sm`}>
                                  <i className={`fa-solid ${h.icon}`}></i>
                               </div>
                               <div className="flex-1 min-w-0">
                                  <p className="text-xs font-bold text-slate-800 dark:text-white truncate group-hover:text-indigo-600 transition-colors">{h.title}</p>
                                  <div className="flex justify-between items-center mt-1">
                                     <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${h.time > Date.now() ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                        {h.time > Date.now() ? 'Đang chờ' : 'Đã gửi'}
                                     </span>
                                     <span className="text-[10px] text-slate-400">{new Date(h.time).toLocaleDateString('vi-VN')}</span>
                                  </div>
                               </div>
                            </div>
                          ))}
                          {/* Loading More Indicator */}
                          {history.length > visibleHistoryCount && (
                             <div className="py-2 text-center">
                                <i className="fa-solid fa-circle-notch animate-spin text-indigo-400 text-sm"></i>
                             </div>
                          )}
                        </>
                     ) : (
                        <div className="text-center p-10 text-slate-400">
                           <p className="text-sm">Chưa có thông báo nào</p>
                        </div>
                     )}
                  </div>
                )}
             </div>
          </div>
       </div>

       {/* Detailed Popup Modal for History Item */}
       {selectedHistoryItem && (
         <div className="fixed inset-0 bg-slate-900/50 dark:bg-black/60 backdrop-blur-md z-[100] flex items-center justify-center p-4" onClick={() => setSelectedHistoryItem(null)}>
            <div 
              className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-[2.5rem] shadow-2xl p-0 relative animate-in fade-in zoom-in duration-300 border-[6px] border-slate-100 dark:border-slate-700 overflow-hidden"
              onClick={e => e.stopPropagation()}
            >
               <div className="relative h-24 bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center">
                  <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
                  <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl shadow-xl border-4 border-white/20 backdrop-blur-sm transform translate-y-8 ${selectedHistoryItem.bg} ${selectedHistoryItem.color}`}>
                     <i className={`fa-solid ${selectedHistoryItem.icon}`}></i>
                  </div>
                  <button 
                    onClick={() => setSelectedHistoryItem(null)}
                    className="absolute top-4 right-4 w-8 h-8 bg-black/20 hover:bg-black/30 text-white rounded-full flex items-center justify-center transition-colors backdrop-blur-md"
                  >
                    <i className="fa-solid fa-xmark"></i>
                  </button>
               </div>

               <div className="pt-12 pb-8 px-8 text-center">
                  <span className={`inline-block text-[10px] font-bold px-3 py-1 rounded-full mb-3 uppercase tracking-wider ${selectedHistoryItem.time > Date.now() ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                     {selectedHistoryItem.time > Date.now() ? 'Lên lịch gửi' : 'Đã gửi thành công'}
                  </span>

                  <h3 className="text-xl font-black text-slate-800 dark:text-white leading-tight mb-2">
                    {selectedHistoryItem.title}
                  </h3>

                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-6">
                    {formatVietnameseDate(selectedHistoryItem.time)}
                  </p>

                  <div className="bg-slate-50 dark:bg-slate-700/50 p-5 rounded-3xl border-2 border-slate-100 dark:border-slate-600 text-left">
                     <p className="text-sm font-medium text-slate-600 dark:text-slate-300 leading-relaxed">
                       {selectedHistoryItem.desc}
                     </p>
                  </div>

                  <div className="mt-6 flex justify-between items-center text-xs font-bold text-slate-400">
                     <span>ID: #{selectedHistoryItem.id}</span>
                     <span className="flex items-center gap-1"><i className="fa-solid fa-users text-indigo-400"></i> {selectedHistoryItem.userId === 'all' ? 'Tất cả' : '1 Người dùng'}</span>
                  </div>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

export default NotificationManager;

import React, { useState, useEffect } from 'react';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  onViewStats: (userId: string) => void;
}

const CustomerManagement: React.FC<Props> = ({ onViewStats }) => {
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // States for Modals
  const [resetModal, setResetModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [newResetPassword, setNewResetPassword] = useState('');
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [actionMsg, setActionMsg] = useState<{ type: string, text: string }>({ type: '', text: '' });

  // Loading state for modal actions
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    loadCustomers();
  }, []);

  const loadCustomers = async () => {
    setIsLoading(true);
    try {
      await new Promise(r => setTimeout(r, 800)); // Cute delay
      const data = await apiService.getAllUsers();
      const filtered = data.filter(u => u.role !== 'master');
      setCustomers(filtered);
    } catch (err) {
      console.error("Lỗi khi tải khách hàng:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!resetModal.userId || !newResetPassword) return;
    setIsProcessing(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      const result = await apiService.resetUserPassword(resetModal.userId, newResetPassword);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã đổi pass cho ${resetModal.email}` });
        setResetModal({ isOpen: false, userId: null, email: '' });
        setNewResetPassword('');
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setIsProcessing(false);
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const handleDeleteUser = async () => {
    if (!deleteModal.userId) return;
    setIsProcessing(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      const result = await apiService.deleteUser(deleteModal.userId);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã xóa bé ${deleteModal.email}` });
        setDeleteModal({ isOpen: false, userId: null, email: '' });
        loadCustomers(); 
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setIsProcessing(false);
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const filteredCustomers = customers.filter(c => 
    c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.botSettings.botName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Toast Notification */}
      {actionMsg.text && (
        <div className={`fixed top-6 right-6 z-[100] px-6 py-4 rounded-3xl shadow-xl border flex items-center animate-in slide-in-from-right duration-300 ${actionMsg.type === 'success' ? 'bg-white dark:bg-slate-800 border-emerald-100 dark:border-emerald-900 text-emerald-600 dark:text-emerald-400' : 'bg-white dark:bg-slate-800 border-rose-100 dark:border-rose-900 text-rose-600 dark:text-rose-400'}`}>
          <i className={`fa-solid ${actionMsg.type === 'success' ? 'fa-check-circle' : 'fa-heart-crack'} text-xl mr-3`}></i>
          <span className="font-bold text-sm">{actionMsg.text}</span>
        </div>
      )}

      {/* Header & Search */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-white dark:border-slate-700 shadow-lg shadow-indigo-50/50 dark:shadow-none">
        <div className="flex items-center gap-4">
            <div>
              <h2 className="text-xl font-bold text-slate-800 dark:text-white flex items-center">
                <span className="w-10 h-10 rounded-2xl bg-indigo-100 dark:bg-indigo-900/50 text-indigo-500 dark:text-indigo-300 flex items-center justify-center mr-3 text-lg">
                  <i className="fa-solid fa-users"></i>
                </span>
                Quản lý khách hàng
              </h2>
            </div>
            <button 
              onClick={loadCustomers}
              disabled={isLoading}
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-50 dark:bg-slate-700 text-slate-400 dark:text-slate-300 hover:bg-indigo-100 dark:hover:bg-indigo-900 hover:text-indigo-500 transition-all active:scale-90 border border-slate-100 dark:border-slate-600 shadow-sm"
              title="Làm mới danh sách"
            >
              <i className={`fa-solid fa-arrows-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
            </button>
        </div>
        <div className="relative w-full md:w-80 group">
          <i className="fa-solid fa-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 group-focus-within:text-indigo-500 transition-colors"></i>
          <input 
            type="text" 
            placeholder="Tìm theo email hoặc tên bot..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-5 py-3.5 bg-slate-50 dark:bg-slate-900 border-2 border-slate-50 dark:border-slate-700 rounded-full focus:border-indigo-300 dark:focus:border-indigo-500 focus:bg-white dark:focus:bg-slate-900 outline-none text-sm font-bold transition-all text-slate-700 dark:text-slate-200 placeholder:text-slate-400"
          />
        </div>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-white dark:border-slate-700 overflow-hidden p-2">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-separate border-spacing-y-2 min-w-[700px]">
            <thead>
              <tr className="bg-indigo-50/50 dark:bg-slate-700/50">
                <th className="px-6 py-5 text-sm font-black text-indigo-900/70 dark:text-indigo-200 rounded-l-2xl pl-8 whitespace-nowrap">
                  <i className="fa-solid fa-user-tag mr-2 text-indigo-400"></i>
                  Khách hàng
                </th>
                <th className="px-6 py-5 text-sm font-black text-indigo-900/70 dark:text-indigo-200 whitespace-nowrap text-center">
                  <i className="fa-solid fa-robot mr-2 text-pink-400"></i>
                  Tên AI Bot
                </th>
                <th className="px-6 py-5 text-sm font-black text-indigo-900/70 dark:text-indigo-200 whitespace-nowrap">
                  <i className="fa-regular fa-calendar-check mr-2 text-purple-400"></i>
                  Ngày tham gia
                </th>
                <th className="px-6 py-5 text-sm font-black text-indigo-900/70 dark:text-indigo-200 rounded-r-2xl text-right pr-8 whitespace-nowrap">
                  <i className="fa-solid fa-wand-magic-sparkles mr-2 text-amber-400"></i>
                  Hành động
                </th>
              </tr>
            </thead>
            <tbody className="space-y-2">
              {isLoading ? (
                <tr>
                  <td colSpan={4} className="px-8 py-32 text-center">
                    <div className="flex flex-col items-center">
                       <div className="w-16 h-16 bg-pink-100 dark:bg-pink-900/30 rounded-full flex items-center justify-center animate-bounce mb-4">
                          <i className="fa-solid fa-binoculars text-pink-500 text-2xl"></i>
                       </div>
                       <p className="text-sm font-bold text-slate-400 dark:text-slate-500">Đang tìm kiếm khách hàng...</p>
                    </div>
                  </td>
                </tr>
              ) : filteredCustomers.length > 0 ? (
                filteredCustomers.map(customer => (
                  <tr key={customer.id} className="bg-white dark:bg-slate-800/50 hover:bg-indigo-50/50 dark:hover:bg-slate-700/50 transition-colors group rounded-2xl">
                    <td className="px-6 py-4 pl-8 rounded-l-2xl border-b border-slate-50 dark:border-slate-700/50">
