                   <div className={`w-9 h-9 rounded-full flex items-center justify-center text-white text-sm font-bold shadow-md border-2 border-white dark:border-slate-600 ${currentUser?.role === 'master' ? 'bg-gradient-to-tr from-slate-700 to-slate-900' : 'bg-gradient-to-tr from-pink-400 to-orange-400'}`}>
                      {currentUser?.email.substring(0, 1).toUpperCase()}
