            <form onSubmit={handleChangePassword} className="space-y-4">
               {passwordMsg.text && (
                 <div className={`p-4 rounded-2xl text-sm font-bold flex items-center animate-in slide-in-from-top-2 ${passwordMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600 border border-emerald-200' : 'bg-rose-50 text-rose-600 border border-rose-200'}`}>
                   <i className={`fa-solid ${passwordMsg.type === 'success' ? 'fa-check-circle' : 'fa-circle-exclamation'} mr-2 text-lg`}></i>
                   {passwordMsg.text}
                 </div>
               )}

               <div className="space-y-4">
                 <div className="relative group">
                   <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 group-focus-within:text-pink-500 transition-colors">
                      <i className="fa-solid fa-key"></i>
                   </div>
                   <input 
                     type="password" 
                     required
                     className="w-full pl-12 pr-6 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-600 focus:border-pink-400 dark:focus:border-pink-500 rounded-2xl text-sm font-bold focus:outline-none transition-all text-slate-700 dark:text-slate-200 placeholder-slate-400 focus:bg-white dark:focus:bg-black/20"
                     placeholder="Mật khẩu cũ"
                     value={passwordForm.old}
                     onChange={e => setPasswordForm({...passwordForm, old: e.target.value})}
                   />
                 </div>

                 <div className="relative group">
                   <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 group-focus-within:text-pink-500 transition-colors">
                      <i className="fa-solid fa-lock"></i>
                   </div>
                   <input 
                     type="password" 
                     required
                     className="w-full pl-12 pr-6 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-600 focus:border-pink-400 dark:focus:border-pink-500 rounded-2xl text-sm font-bold focus:outline-none transition-all text-slate-700 dark:text-slate-200 placeholder-slate-400 focus:bg-white dark:focus:bg-black/20"
                     placeholder="Mật khẩu mới (>= 6 ký tự)"
                     value={passwordForm.new}
                     onChange={e => setPasswordForm({...passwordForm, new: e.target.value})}
                   />
                 </div>

                 <div className="relative group">
                   <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 group-focus-within:text-pink-500 transition-colors">
                      <i className="fa-solid fa-shield-halved"></i>
                   </div>
                   <input 
                     type="password" 
                     required
                     className="w-full pl-12 pr-6 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-600 focus:border-pink-400 dark:focus:border-pink-500 rounded-2xl text-sm font-bold focus:outline-none transition-all text-slate-700 dark:text-slate-200 placeholder-slate-400 focus:bg-white dark:focus:bg-black/20"
                     placeholder="Nhập lại mật khẩu mới"
                     value={passwordForm.confirm}
                     onChange={e => setPasswordForm({...passwordForm, confirm: e.target.value})}
                   />
                 </div>
               </div>

               <button type="submit" className="w-full py-4 bg-gradient-to-r from-pink-500 to-rose-600 hover:from-pink-600 hover:to-rose-700 text-white rounded-2xl font-black shadow-xl shadow-pink-200 dark:shadow-none transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-2 text-base group">
                 <span>Cập nhật ngay</span>
                 <i className="fa-solid fa-arrow-right group-hover:translate-x-1 transition-transform"></i>
               </button>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { apiService } from '../services/apiService';
import { Notification, User } from '../types';

interface Props {
  user: User;
}

const icons = [
  { class: 'fa-bell', label: 'Chuông' },
  { class: 'fa-gift', label: 'Quà' },
  { class: 'fa-bolt', label: 'Sét' },
  { class: 'fa-heart', label: 'Tim' },
  { class: 'fa-bullhorn', label: 'Loa' },
  { class: 'fa-star', label: 'Sao' },
  { class: 'fa-triangle-exclamation', label: 'Cảnh báo' },
  { class: 'fa-circle-info', label: 'Thông tin' },
  { class: 'fa-check-circle', label: 'Hoàn tất' },
  { class: 'fa-fire', label: 'Hot' },
];

const colors = [
  { text: 'text-pink-500', bg: 'bg-pink-100 dark:bg-pink-900/30' },
  { text: 'text-blue-500', bg: 'bg-blue-100 dark:bg-blue-900/30' },
  { text: 'text-emerald-500', bg: 'bg-emerald-100 dark:bg-emerald-900/30' },
  { text: 'text-amber-500', bg: 'bg-amber-100 dark:bg-amber-900/30' },
  { text: 'text-violet-500', bg: 'bg-violet-100 dark:bg-violet-900/30' },
  { text: 'text-rose-500', bg: 'bg-rose-100 dark:bg-rose-900/30' },
];

const targetOptions = [
  { value: 'all', label: 'Tất cả mọi người', icon: 'fa-users' },
  { value: 'admin', label: 'Chỉ Admin (Test)', icon: 'fa-user-shield' }
];

const NotificationManager: React.FC<Props> = ({ user }) => {
  const [history, setHistory] = useState<Notification[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form State
  const [title, setTitle] = useState('');
  const [desc, setDesc] = useState('');
  const [selectedIcon, setSelectedIcon] = useState('fa-bell');
  const [selectedColor, setSelectedColor] = useState(colors[0]);
  const [targetUser, setTargetUser] = useState('all');

  // Schedule Logic Changes
  const [sendImmediately, setSendImmediately] = useState(true);
  const [scheduleTime, setScheduleTime] = useState('');

  // Dropdown State
  const [isTargetDropdownOpen, setIsTargetDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // History List Infinite Scroll & Detail Popup
  const [visibleHistoryCount, setVisibleHistoryCount] = useState(10);
  const historyScrollRef = useRef<HTMLDivElement>(null);
  const [selectedHistoryItem, setSelectedHistoryItem] = useState<Notification | null>(null);

  useEffect(() => {
    loadHistory();
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsTargetDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const loadHistory = async () => {
    setIsLoading(true);
    // Simulate delay for cute loading effect
    await new Promise(r => setTimeout(r, 800)); 
    const data = await apiService.getAdminNotifications();
    setHistory(data);
    setIsLoading(false);
  };

  const handleSmartIcon = () => {
    const t = title.toLowerCase();
    if (t.includes('lỗi') || t.includes('bảo trì') || t.includes('cảnh báo')) setSelectedIcon('fa-triangle-exclamation');
    else if (t.includes('quà') || t.includes('khuyến mãi') || t.includes('tặng')) setSelectedIcon('fa-gift');
    else if (t.includes('yêu') || t.includes('thích')) setSelectedIcon('fa-heart');
    else if (t.includes('hot') || t.includes('mới')) setSelectedIcon('fa-fire');
    else if (t.includes('xong') || t.includes('thành công')) setSelectedIcon('fa-check-circle');
    else setSelectedIcon('fa-bullhorn');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !desc) return;

    setIsSubmitting(true);

    const scheduledTimestamp = (!sendImmediately && scheduleTime) ? new Date(scheduleTime).getTime() : Date.now();

    const newNotif = {
      title,
      desc,
      icon: selectedIcon,
      color: selectedColor.text,
      bg: selectedColor.bg,
      userId: targetUser,
      scheduledAt: scheduledTimestamp
    };

    await apiService.createSystemNotification(newNotif);

    // Simulate delay
    await new Promise(r => setTimeout(r, 1000));

    setTitle('');
    setDesc('');
    setScheduleTime('');
    setSendImmediately(true);
    setIsSubmitting(false);
    loadHistory();
  };

  const formatVietnameseDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleString('vi-VN', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleHistoryScroll = () => {
    if (historyScrollRef.current) {
        const { scrollTop, scrollHeight, clientHeight } = historyScrollRef.current;
        if (scrollTop + clientHeight >= scrollHeight - 50) {
            if (visibleHistoryCount < history.length) {
                setVisibleHistoryCount(prev => prev + 10);
            }
        }
    }
  };

  const selectedTargetLabel = targetOptions.find(opt => opt.value === targetUser);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12 relative">
       {/* Header */}
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-white dark:border-slate-700 shadow-lg shadow-indigo-50/50 dark:shadow-none">
          <div className="flex items-center gap-4">
              <span className="w-12 h-12 rounded-2xl bg-indigo-100 dark:bg-indigo-900/50 text-indigo-500 dark:text-indigo-300 flex items-center justify-center text-xl">
                  <i className="fa-solid fa-bell"></i>
              </span>
              <div>
                <h2 className="text-xl font-bold text-slate-800 dark:text-white">Quản lý Thông báo</h2>
                <p className="text-sm text-slate-500 dark:text-slate-400 font-bold">Gửi tin nhắn cute đến người dùng</p>
              </div>
          </div>
       </div>

       <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Create Form */}
          <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-700">
             <h3 className="font-bold text-lg text-slate-800 dark:text-white mb-6 flex items-center gap-2">
                <i className="fa-solid fa-pen-nib text-pink-500"></i> Soạn thông báo mới
             </h3>

             <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                   <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-2 ml-2">Tiêu đề</label>
                   <div className="relative">
                      <input 
                        type="text" 
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                        placeholder="VD: Bảo trì hệ thống..." 
                        className="w-full pl-5 pr-12 py-3.5 bg-slate-50 dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 rounded-2xl focus:border-indigo-500 font-bold text-sm text-slate-800 dark:text-white outline-none transition-all"
                      />
                      <button 
                        type="button" 
                        onClick={handleSmartIcon}
                        title="AI Chọn icon"
                        className="absolute right-3 top-1/2 -translate-y-1/2 w-8 h-8 rounded-lg bg-indigo-100 text-indigo-600 hover:bg-indigo-200 flex items-center justify-center transition-colors"
                      >
                         <i className="fa-solid fa-wand-magic-sparkles text-xs"></i>
                      </button>
                   </div>
                </div>

                <div>
                   <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-2 ml-2">Nội dung</label>
                   <textarea 
                      value={desc}
                      onChange={(e) => setDesc(e.target.value)}
                      rows={3}
                      placeholder="Nhập nội dung chi tiết..." 
                      className="w-full px-5 py-3.5 bg-slate-50 dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 rounded-2xl focus:border-indigo-500 font-medium text-sm text-slate-800 dark:text-white outline-none transition-all resize-none"
                   />
                </div>

                <div className="grid grid-cols-2 gap-4">
                   {/* Styled Date Picker with Toggle */}
                   <div>
                      <div className="flex justify-between items-center mb-2 ml-2">
                         <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">Thời gian gửi</label>
                      </div>

                      <div className="flex flex-col gap-3">
                         {/* Toggle Send Immediately */}
                         <div 
                           onClick={() => setSendImmediately(!sendImmediately)}
                           className={`cursor-pointer flex items-center gap-3 p-3 rounded-2xl border-2 transition-all ${sendImmediately ? 'bg-emerald-50 border-emerald-200 dark:bg-emerald-900/20 dark:border-emerald-800' : 'bg-slate-50 border-slate-200 dark:bg-slate-900 dark:border-slate-700 hover:border-emerald-200'}`}
                         >
                            <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors ${sendImmediately ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-300 dark:border-slate-500'}`}>
                               {sendImmediately && <i className="fa-solid fa-check text-[10px]"></i>}
                            </div>
                            <span className={`text-xs font-bold ${sendImmediately ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-500 dark:text-slate-400'}`}>Gửi ngay lập tức</span>
                         </div>

                         {/* Date Input - Shows only if not immediate */}
                         <div className={`transition-all duration-300 overflow-hidden ${sendImmediately ? 'max-h-0 opacity-0' : 'max-h-20 opacity-100'}`}>
                            <div className="relative">
                               <input 
                                 type="datetime-local" 
                                 value={scheduleTime}
                                 onChange={(e) => setScheduleTime(e.target.value)}
                                 className="w-full px-4 py-3 bg-white dark:bg-slate-900 border-2 border-indigo-100 dark:border-slate-600 rounded-2xl font-bold text-xs text-indigo-600 dark:text-indigo-300 outline-none focus:border-indigo-400 transition-all"
                               />
                               <span className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-400 bg-white dark:bg-slate-900 pl-2">
                                  <i className="fa-regular fa-calendar-days"></i>
                               </span>
                            </div>
                         </div>
                      </div>
                   </div>

                   {/* Custom Styled Dropdown for Target Audience */}
                   <div className="relative" ref={dropdownRef}>
                      <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-2 ml-2">Gửi tới ai?</label>
                      <button 
                        type="button"
                        onClick={() => setIsTargetDropdownOpen(!isTargetDropdownOpen)}
                        className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 rounded-2xl font-bold text-xs text-slate-700 dark:text-slate-200 outline-none flex items-center justify-between hover:border-indigo-400 transition-all h-[52px]"
                      >
                         <span className="flex items-center gap-2">
                            <i className={`fa-solid ${selectedTargetLabel?.icon} text-indigo-500`}></i>
                            {selectedTargetLabel?.label}
                         </span>
                         <i className={`fa-solid fa-chevron-down text-[10px] transition-transform ${isTargetDropdownOpen ? 'rotate-180' : ''}`}></i>
                      </button>

                      {isTargetDropdownOpen && (
                        <div className="absolute top-full left-0 w-full mt-2 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-600 rounded-2xl shadow-xl overflow-hidden z-20 animate-in fade-in zoom-in duration-200">
                           {targetOptions.map(opt => (
                             <div 
                               key={opt.value}
                               onClick={() => { setTargetUser(opt.value); setIsTargetDropdownOpen(false); }}
                               className={`px-4 py-3 text-xs font-bold cursor-pointer flex items-center gap-3 transition-colors ${targetUser === opt.value ? 'bg-indigo-50 dark:bg-slate-700 text-indigo-600 dark:text-white' : 'hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300'}`}
                             >
                                <div className={`w-6 h-6 rounded-full flex items-center justify-center ${targetUser === opt.value ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                                   <i className={`fa-solid ${opt.icon}`}></i>
                                </div>
                                {opt.label}
                             </div>
                           ))}
                        </div>
                      )}
                   </div>
                </div>

                {/* Icon Selector */}
                <div>
                   <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-3 ml-2">Chọn biểu tượng</label>
                   <div className="flex flex-wrap gap-3">
                      {icons.map((ic) => (
                         <button 
                           key={ic.class}
                           type="button"
                           onClick={() => setSelectedIcon(ic.class)}
                           className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${selectedIcon === ic.class ? 'bg-indigo-600 text-white shadow-lg scale-110' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-600'}`}
                         >
                            <i className={`fa-solid ${ic.class}`}></i>
                         </button>
                      ))}
                   </div>
                </div>

                 {/* Color Selector */}
                <div>
                   <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-3 ml-2">Chọn màu sắc</label>
                   <div className="flex flex-wrap gap-3">
                      {colors.map((c, i) => (
                         <button 
                           key={i}
                           type="button"
                           onClick={() => setSelectedColor(c)}
                           className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${selectedColor.text === c.text ? 'ring-2 ring-offset-2 ring-indigo-400 scale-110' : ''} ${c.bg} ${c.text}`}
                         >
                            <i className="fa-solid fa-circle text-xs"></i>
                         </button>
                      ))}
                   </div>
                </div>

                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="w-full py-4 bg-gradient-to-r from-indigo-500 to-violet-600 hover:from-indigo-600 hover:to-violet-700 text-white rounded-2xl font-bold shadow-xl shadow-indigo-200 dark:shadow-none active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                >
                   {isSubmitting ? (
                     <>
                        <i className="fa-solid fa-circle-notch animate-spin"></i>
                        Đang gửi...
                     </>
                   ) : (
                     <>
                        <i className="fa-solid fa-paper-plane"></i> 
                        {(!sendImmediately && scheduleTime) ? 'Lên lịch gửi' : 'Gửi thông báo ngay'}
                     </>
                   )}
                </button>
             </form>
          </div>

          {/* Preview & History */}
          <div className="space-y-6">
             {/* Live Preview Card */}
             <div className="bg-slate-50 dark:bg-slate-900 p-6 rounded-[2.5rem] border-2 border-dashed border-slate-200 dark:border-slate-700">
                <h4 className="text-center text-xs font-bold text-slate-400 uppercase mb-4">Xem trước</h4>
                <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex gap-4">
                   <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${selectedColor.bg} ${selectedColor.text} shadow-sm relative`}>
                      <i className={`fa-solid ${selectedIcon} text-lg`}></i>
                      <span className="absolute -top-1 -right-1 w-3 h-3 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>
                   </div>
                   <div className="min-w-0 flex-1">
                      <h4 className="text-sm font-black text-slate-800 dark:text-white truncate">{title || 'Tiêu đề thông báo...'}</h4>
                      <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed line-clamp-2">{desc || 'Nội dung thông báo sẽ hiện ở đây...'}</p>
                      <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold mt-1.5">
                        {(!sendImmediately && scheduleTime) ? formatVietnameseDate(new Date(scheduleTime).getTime()) : 'Vừa xong'}
                      </p>
                   </div>
                </div>
             </div>

             {/* History List with Infinite Scroll */}
             <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-700 overflow-hidden flex flex-col h-[400px]">
                <div className="p-5 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-700/30">
                   <h3 className="font-bold text-slate-700 dark:text-slate-300 text-sm">Lịch sử đã tạo ({history.length})</h3>
                </div>

                {isLoading ? (
                   <div className="flex flex-col items-center justify-center h-full space-y-4">
                      <div className="w-16 h-16 bg-indigo-50 dark:bg-indigo-900/30 rounded-full flex items-center justify-center animate-bounce">
                         <i className="fa-solid fa-robot text-indigo-500 text-2xl"></i>
                      </div>
                      <p className="text-xs font-bold text-slate-400 animate-pulse">Đang tải lịch sử nè...</p>
                   </div>
                ) : (
                  <div 
                    className="flex-1 overflow-y-auto p-4 space-y-3 scroll-smooth"
                    ref={historyScrollRef}
                    onScroll={handleHistoryScroll}
                  >
                     {history.length > 0 ? (
                        <>
                          {history.slice(0, visibleHistoryCount).map(h => (
                            <div 
                              key={h.id} 
                              onClick={() => setSelectedHistoryItem(h)}
                              className="flex gap-3 p-3 rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors border border-transparent hover:border-slate-100 dark:hover:border-slate-600 cursor-pointer group"
                            >
                               <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${h.bg} ${h.color} text-sm`}>
                                  <i className={`fa-solid ${h.icon}`}></i>
                               </div>
                               <div className="flex-1 min-w-0">
                                  <p className="text-xs font-bold text-slate-800 dark:text-white truncate group-hover:text-indigo-600 transition-colors">{h.title}</p>
                                  <div className="flex justify-between items-center mt-1">
                                     <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${h.time > Date.now() ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                        {h.time > Date.now() ? 'Đang chờ' : 'Đã gửi'}
                                     </span>
                                     <span className="text-[10px] text-slate-400">{new Date(h.time).toLocaleDateString('vi-VN')}</span>
                                  </div>
                               </div>
                            </div>
                          ))}
                          {/* Loading More Indicator */}
                          {history.length > visibleHistoryCount && (
                             <div className="py-2 text-center">
                                <i className="fa-solid fa-circle-notch animate-spin text-indigo-400 text-sm"></i>
                             </div>
                          )}
                        </>
                     ) : (
                        <div className="text-center p-10 text-slate-400">
                           <p className="text-sm">Chưa có thông báo nào</p>
                        </div>
                     )}
                  </div>
                )}
             </div>
          </div>
       </div>

       {/* Detailed Popup Modal for History Item (Refined Style like Change Password Modal) */}
       {selectedHistoryItem && (
         <div className="fixed inset-0 bg-slate-900/50 dark:bg-black/60 backdrop-blur-md z-[100] flex items-center justify-center p-4" onClick={() => setSelectedHistoryItem(null)}>
            <div 
              className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-[2.5rem] shadow-2xl p-8 relative animate-in fade-in zoom-in duration-300 border-[6px] border-slate-100 dark:border-slate-700 overflow-hidden"
              onClick={e => e.stopPropagation()}
            >
               {/* Close Button */}
               <button 
                 onClick={() => setSelectedHistoryItem(null)}
                 className="absolute top-6 right-6 w-10 h-10 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 rounded-full flex items-center justify-center text-slate-500 dark:text-slate-400 transition-colors z-20"
               >
                 <i className="fa-solid fa-xmark text-lg"></i>
               </button>

               <div className="text-center mb-6 pt-4">
                  {/* Icon Display */}
                  <div className={`w-24 h-24 mx-auto mb-5 rounded-3xl flex items-center justify-center text-4xl shadow-xl border-4 border-white dark:border-slate-700 transform -rotate-12 hover:rotate-12 transition-transform duration-500 ${selectedHistoryItem.bg} ${selectedHistoryItem.color}`}>
                     <i className={`fa-solid ${selectedHistoryItem.icon}`}></i>
                  </div>

                  {/* Status Badge */}
                  <span className={`inline-block text-[10px] font-bold px-3 py-1 rounded-full mb-3 uppercase tracking-wider ${selectedHistoryItem.time > Date.now() ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                     {selectedHistoryItem.time > Date.now() ? 'Lên lịch gửi' : 'Đã gửi thành công'}
                  </span>

                  <h3 className="text-xl font-black text-slate-800 dark:text-white leading-tight mb-2 px-2">
                    {selectedHistoryItem.title}
                  </h3>

                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-6">
                    {formatVietnameseDate(selectedHistoryItem.time)}
                  </p>

                  <div className="bg-slate-50 dark:bg-slate-700/50 p-5 rounded-3xl border-2 border-slate-100 dark:border-slate-600 text-left">
                     <p className="text-sm font-medium text-slate-600 dark:text-slate-300 leading-relaxed">
                       {selectedHistoryItem.desc}
                     </p>
                  </div>

                  <div className="mt-6 flex justify-between items-center text-xs font-bold text-slate-400 px-2">
                     <span>ID: #{selectedHistoryItem.id.substring(0,6)}</span>
                     <span className="flex items-center gap-1"><i className="fa-solid fa-users text-indigo-400"></i> {selectedHistoryItem.userId === 'all' ? 'Tất cả' : '1 Người dùng'}</span>
                  </div>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

export default NotificationManager;

import React, { useState, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import CustomerManagement from './components/CustomerManagement';
import ChatHistory from './components/ChatHistory';
import NotificationManager from './components/NotificationManager'; 
import Login from './components/Login';
import LandingPage from './components/LandingPage';
import { TermsPage, PrivacyPage, ContactPage, DemoPage } from './components/LegalPages'; 
import { View, Document, WidgetSettings, User, Notification } from './types';
import { apiService } from './services/apiService';

// Định nghĩa kiểu cho trang Public
type PublicViewType = 'landing' | 'login' | 'terms' | 'privacy' | 'contact' | 'demo';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [publicView, setPublicView] = useState<PublicViewType>('landing'); 
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedCustomerIdForStats, setSelectedCustomerIdForStats] = useState<string>('all');

  // Dark Mode State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('omnichat_theme') === 'dark';
    }
    return false;
  });

  // Notification State
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [selectedNotification, setSelectedNotification] = useState<Notification | null>(null);
  const [showAllNotifModal, setShowAllNotifModal] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  // Infinite Scroll State for Notifications
  const [visibleNotifCount, setVisibleNotifCount] = useState(20);
  const notifModalScrollRef = useRef<HTMLDivElement>(null);

  // Profile & Password Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#8b5cf6', 
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  const viewNames: Record<View, string> = {
    [View.DASHBOARD]: 'Tổng quan',
    [View.KNOWLEDGE_BASE]: 'Kho tri thức',
    [View.WIDGET_CONFIG]: 'Làm đẹp Widget',
    [View.ANALYTICS]: 'Phân tích',
    [View.INTEGRATION]: 'Mã nhúng',
    [View.DEPLOYMENT_GUIDE]: 'Hướng dẫn',
    [View.CUSTOMER_MANAGEMENT]: 'Khách hàng',
    [View.CHAT_HISTORY]: 'Lịch sử chat',
    [View.NOTIFICATION_MANAGER]: 'Quản lý thông báo'
  };

  useEffect(() => {
    // Apply Dark Mode Class
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('omnichat_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('omnichat_theme', 'light');
    }
  }, [darkMode]);

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    const savedUserRole = localStorage.getItem('omnichat_user_role');

    if (savedUserId) {
      setCurrentUser({
         id: savedUserId,
         email: 'Loading...', 
         role: savedUserRole as any || 'user',
         botSettings: settings,
         createdAt: Date.now()
      });
      setIsLoggedIn(true);

      apiService.getAllUsers().then(users => {
         const me = users.find(u => u.id === savedUserId);
         if(me) handleLoginSuccess(me);
         else if(savedUserId === 'admin') {
             handleLoginSuccess({ 
                 id: 'admin', 
                 email: 'admin@bibichat.io', 
                 role: 'master', 
                 botSettings: settings, 
                 createdAt: Date.now() 
             });
         }
      });
    }

    const handleClickOutside = (event: MouseEvent) => {
      // Close Notif Dropdown
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
        setSelectedNotification(null);
      }
      // Close Profile Dropdown
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);

  }, []);

  // --- Logic Notification Polling ---
  useEffect(() => {
    if (isLoggedIn && currentUser) {
      loadNotifications();
      const interval = setInterval(loadNotifications, 5000);
      return () => {
        clearInterval(interval);
      };
    }
  }, [isLoggedIn, currentUser?.id]);

  const handleNotifModalScroll = () => {
    if (notifModalScrollRef.current) {
        const { scrollTop, scrollHeight, clientHeight } = notifModalScrollRef.current;
        if (scrollTop + clientHeight >= scrollHeight - 50) {
            if (visibleNotifCount < notifications.length) {
                setVisibleNotifCount(prev => prev + 20);
            }
        }
    }
  };

  useEffect(() => {
      if (showAllNotifModal) {
          setVisibleNotifCount(20);
      }
  }, [showAllNotifModal]);

  const loadNotifications = async () => {
    if (currentUser) {
      const data = await apiService.getNotifications(currentUser.id);
      setNotifications(data);
    }
  };

  const handleNotificationClick = async (notif: Notification) => {
    setSelectedNotification(notif);
    if (!notif.isRead) {
      await apiService.markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
    }
  };

  const handleMarkAllRead = async () => {
    if (!currentUser) return;
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
    await apiService.markAllNotificationsRead(currentUser.id);
  };

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setPublicView('landing'); 
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    localStorage.setItem('omnichat_user_role', user.role);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
    localStorage.removeItem('omnichat_user_role');
    setPublicView('landing'); 
    setNotifications([]); 
  };

  // Logic Change Password
  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu quá ngắn (>= 6 ký tự)' });
      return;
    }

    try {
      const result = await apiService.changePassword(currentUser.id, currentUser.password || '', passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) {
    if (publicView === 'terms') return <TermsPage onNavigate={setPublicView} />;
    if (publicView === 'privacy') return <PrivacyPage onNavigate={setPublicView} />;
    if (publicView === 'contact') return <ContactPage onNavigate={setPublicView} />;
    if (publicView === 'demo') return <DemoPage onNavigate={setPublicView} />;

    if (publicView === 'landing') {
        return <LandingPage onNavigate={setPublicView} />;
    }

    return (
      <>
        <div className="absolute top-4 left-4 z-50">
           <button 
             onClick={() => setPublicView('landing')}
             className="px-4 py-2 bg-white/50 hover:bg-white rounded-xl text-sm font-bold text-slate-600 transition-all backdrop-blur-sm shadow-sm"
           >
             <i className="fa-solid fa-arrow-left mr-2"></i>Trang chủ
           </button>
        </div>
        <Login onLogin={handleLoginSuccess} />
      </>
    );
  }

  return (
    <div className={`flex h-screen w-full overflow-hidden relative font-sans antialiased transition-colors duration-500
      ${darkMode ? 'bg-slate-900 text-slate-100 selection:bg-purple-500 selection:text-white' : 'bg-[#f0f2f5] text-slate-700 selection:bg-pink-100 selection:text-pink-900'}
    `}>
      {/* Dynamic Background Mesh Gradient */}
      {!darkMode && (
        <div className="absolute inset-0 z-0 pointer-events-none opacity-60">
           <div className="absolute top-[-10%] left-[-10%] w-[40rem] h-[40rem] bg-pink-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
           <div className="absolute top-[-10%] right-[-10%] w-[40rem] h-[40rem] bg-purple-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>
           <div className="absolute bottom-[-10%] left-[20%] w-[40rem] h-[40rem] bg-yellow-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-4000"></div>
        </div>
      )}

      {/* Dark Mode Background Decor */}
      {darkMode && (
         <div className="absolute inset-0 z-0 pointer-events-none">
            <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-purple-900/20 rounded-full blur-[120px]"></div>
            <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-blue-900/20 rounded-full blur-[120px]"></div>
         </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative z-10">
        <header className="h-24 flex items-center justify-between px-8 z-30 shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden w-12 h-12 bg-white/50 dark:bg-slate-800 rounded-2xl shadow-sm flex items-center justify-center text-pink-500 hover:text-pink-600 transition-colors backdrop-blur-sm">
              <i className="fas fa-bars text-xl"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-3xl font-black text-slate-800 dark:text-white tracking-tight drop-shadow-sm">
                {viewNames[currentView]}
              </h1>
              <p className="text-sm font-bold text-slate-500 dark:text-slate-400 hidden sm:block">
                {currentUser?.role === 'master' ? '🚀 Control Center' : '✨ Dashboard Doanh Nghiệp'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             {/* Dark Mode Toggle */}
             <button 
               onClick={() => setDarkMode(!darkMode)}
               className="w-12 h-12 rounded-full bg-white/60 dark:bg-slate-800 border border-white dark:border-slate-700 shadow-sm flex items-center justify-center text-slate-600 dark:text-yellow-400 hover:scale-110 transition-transform backdrop-blur-sm"
               title={darkMode ? "Chuyển sang sáng" : "Chuyển sang tối"}
             >
                <i className={`fa-solid ${darkMode ? 'fa-sun' : 'fa-moon'} text-xl`}></i>
             </button>

             {/* Notification Bell */}
             <div className="relative" ref={notifRef}>
               <button 
                onClick={() => { setShowNotifications(!showNotifications); setSelectedNotification(null); }}
                className="w-12 h-12 bg-white/60 dark:bg-slate-800 rounded-full shadow-sm flex items-center justify-center text-slate-500 dark:text-slate-300 hover:text-pink-500 dark:hover:text-pink-400 hover:scale-110 transition-all relative active:scale-95 group border border-white dark:border-slate-700 backdrop-blur-sm"
               >
                 <i className={`fa-regular fa-bell text-xl ${unreadCount > 0 ? 'group-hover:animate-swing' : ''}`}></i>
                 {unreadCount > 0 && (
                   <span className="absolute top-0 right-0 w-5 h-5 bg-rose-500 text-white text-[10px] font-bold rounded-full border-2 border-white dark:border-slate-800 flex items-center justify-center animate-bounce-slow">
                     {unreadCount}
                   </span>
                 )}
               </button>

               {/* Notification Dropdown Container */}
               {showNotifications && (
                 <div className="absolute right-0 mt-4 w-80 sm:w-96 bg-white/90 dark:bg-slate-800/95 backdrop-blur-xl rounded-[2rem] shadow-[0_20px_40px_-10px_rgba(0,0,0,0.2)] border border-white dark:border-slate-700 overflow-hidden animate-in fade-in zoom-in duration-200 z-50">

                    {/* Header */}
                    <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800 relative z-20">
                       <h3 className="font-bold text-base text-slate-800 dark:text-white">Thông báo</h3>
                       <div className="flex gap-2">
                           {unreadCount > 0 && (
                             <button 
                               onClick={handleMarkAllRead}
                               className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/30 text-indigo-500 hover:bg-indigo-100 dark:hover:bg-indigo-900 flex items-center justify-center transition-colors"
                               title="Đánh dấu tất cả là đã đọc"
                             >
                                <i className="fa-solid fa-check-double text-xs"></i>
                             </button>
                           )}
                           {unreadCount > 0 && <span className="text-[10px] bg-pink-100 dark:bg-pink-900 text-pink-600 dark:text-pink-300 px-3 py-1 rounded-full font-bold flex items-center">{unreadCount} mới</span>}
                       </div>
                    </div>

                    {/* Content Area */}
                    <div className="relative h-80">
                        {/* List View */}
                        <div className={`absolute inset-0 overflow-y-auto p-2 transition-transform duration-300 ${selectedNotification ? '-translate-x-full opacity-0 pointer-events-none' : 'translate-x-0 opacity-100'}`}>
                           {notifications.length > 0 ? notifications.slice(0, 10).map(notif => (
                             <div 
                               key={notif.id} 
                               onClick={() => handleNotificationClick(notif)}
                               className={`p-3 mb-1 rounded-2xl transition-colors cursor-pointer group flex gap-4 ${!notif.isRead ? 'bg-white dark:bg-slate-700 shadow-sm border border-pink-100 dark:border-pink-900/30' : 'hover:bg-slate-50 dark:hover:bg-slate-700/50 opacity-80'}`}
                             >
                                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${notif.bg} ${notif.color} shadow-sm relative`}>
                                   <i className={`fa-solid ${notif.icon} text-lg`}></i>
                                   {!notif.isRead && <span className="absolute -top-1 -right-1 w-3 h-3 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>}
                                </div>
                                <div className="min-w-0 flex-1">
                                   <h4 className={`text-sm ${!notif.isRead ? 'font-black text-slate-800 dark:text-white' : 'font-bold text-slate-600 dark:text-slate-300'} group-hover:text-pink-500 transition-colors truncate`}>{notif.title}</h4>
                                   <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed line-clamp-2">{notif.desc}</p>
                                   <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold mt-1.5">{new Date(notif.time).toLocaleString('vi-VN')}</p>
                                </div>
                             </div>
                           )) : (
                             <div className="flex flex-col items-center justify-center h-full text-slate-400">
                               <i className="fa-regular fa-bell-slash text-3xl mb-2"></i>
                               <p className="text-sm font-bold">Không có thông báo nào</p>
                             </div>
                           )}
                        </div>

                        {/* Detail View (Overlay) */}
                        <div className={`absolute inset-0 bg-white dark:bg-slate-800 z-10 p-5 flex flex-col transition-transform duration-300 ${selectedNotification ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'}`}>
                           {selectedNotification && (
                             <>
                                <button 
                                  onClick={() => setSelectedNotification(null)}
                                  className="self-start text-xs font-bold text-slate-500 hover:text-pink-500 mb-4 flex items-center bg-slate-100 dark:bg-slate-700 px-3 py-1.5 rounded-lg"
                                >
                                  <i className="fa-solid fa-arrow-left mr-2"></i> Quay lại
                                </button>

                                <div className="flex-1 overflow-y-auto pr-1">
                                  <div className="flex items-center gap-3 mb-4">
                                     <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${selectedNotification.bg} ${selectedNotification.color}`}>
                                        <i className={`fa-solid ${selectedNotification.icon} text-2xl`}></i>
                                     </div>
                                     <div>
                                        <h4 className="text-lg font-black text-slate-800 dark:text-white leading-tight">{selectedNotification.title}</h4>
                                        <p className="text-xs text-slate-400 font-bold mt-1">{new Date(selectedNotification.time).toLocaleString('vi-VN')}</p>
                                     </div>
                                  </div>
                                  <div className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-slate-700/50 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                                    {selectedNotification.desc}
                                  </div>
                                </div>
                             </>
                           )}
                        </div>
                    </div>

                    <div className="p-3 text-center border-t border-slate-50 dark:border-slate-700 relative z-20 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm">
                       <button 
                         onClick={() => { setShowNotifications(false); setShowAllNotifModal(true); }}
                         className="text-xs font-bold text-pink-500 hover:text-pink-700 dark:hover:text-pink-400 hover:underline"
                       >
                         Xem tất cả
                       </button>
                    </div>
                 </div>
               )}
             </div>

             {/* Profile Area */}
             <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="flex items-center gap-3 pl-2 pr-4 py-2 bg-white/60 dark:bg-slate-800/80 rounded-full border border-white dark:border-slate-700 shadow-sm hover:shadow-md transition-all active:scale-95 group backdrop-blur-sm"
                >
                   <div className={`w-9 h-9 rounded-full flex items-center justify-center text-white text-sm font-bold shadow-md border-2 border-white dark:border-slate-600 ${currentUser?.role === 'master' ? 'bg-gradient-to-tr from-slate-700 to-slate-900' : 'bg-gradient-to-tr from-pink-400 to-orange-400'}`}>
                      {currentUser?.email.substring(0, 1).toUpperCase()}
                   </div>
                   <div className="text-left hidden sm:block">
                      <p className="text-xs font-bold text-slate-700 dark:text-slate-200 group-hover:text-indigo-500 dark:group-hover:text-indigo-400 transition-colors">
                        {currentUser?.role === 'master' ? 'Admin' : 'Khách'}
                      </p>
                   </div>
                   <i className={`fa-solid fa-chevron-down text-[10px] text-slate-400 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`}></i>
                </button>

                {isProfileOpen && (
                  <div className="absolute top-full right-0 mt-3 w-64 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-700 overflow-hidden animate-in fade-in zoom-in duration-200 z-50">
                     <div className="p-5 bg-gradient-to-r from-pink-50 to-indigo-50 dark:from-slate-700/50 dark:to-slate-700 border-b border-slate-100 dark:border-slate-600 relative overflow-hidden">
                        <div className="absolute top-[-10px] right-[-10px] text-6xl text-white/40 dark:text-black/10 rotate-12">
                           <i className="fa-solid fa-user-circle"></i>
