];

const colors = [
  { text: 'text-pink-500', bg: 'bg-pink-100 dark:bg-pink-900/30' },
  { text: 'text-blue-500', bg: 'bg-blue-100 dark:bg-blue-900/30' },
  { text: 'text-emerald-500', bg: 'bg-emerald-100 dark:bg-emerald-900/30' },
