                      </div>

                      <div className="flex flex-col gap-3">
                         {/* Toggle Send Immediately */}
                         <div 
                           onClick={() => setSendImmediately(!sendImmediately)}
                           className={`cursor-pointer flex items-center gap-3 p-3 rounded-2xl border-2 transition-all ${sendImmediately ? 'bg-emerald-50 border-emerald-200 dark:bg-emerald-900/20 dark:border-emerald-800' : 'bg-slate-50 border-slate-200 dark:bg-slate-900 dark:border-slate-700 hover:border-emerald-200'}`}
                         >
                            <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors ${sendImmediately ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-300 dark:border-slate-500'}`}>
                               {sendImmediately && <i className="fa-solid fa-check text-[10px]"></i>}
                            </div>
                            <span className={`text-xs font-bold ${sendImmediately ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-500 dark:text-slate-400'}`}>Gửi ngay lập tức</span>
                         </div>

                         {/* Date Input - Shows only if not immediate */}
                         <div className={`transition-all duration-300 overflow-hidden ${sendImmediately ? 'max-h-0 opacity-0' : 'max-h-20 opacity-100'}`}>
                            <div className="relative">
                               <input 
                                 type="datetime-local" 
                                 value={scheduleTime}
                                 onChange={(e) => setScheduleTime(e.target.value)}
                                 className="w-full px-4 py-3 bg-white dark:bg-slate-900 border-2 border-indigo-100 dark:border-slate-600 rounded-2xl font-bold text-xs text-indigo-600 dark:text-indigo-300 outline-none focus:border-indigo-400 transition-all"
                               />
                               <span className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-400 bg-white dark:bg-slate-900 pl-2">
                                  <i className="fa-regular fa-calendar-days"></i>
                               </span>
                            </div>
                         </div>
                      </div>
                   </div>

                   {/* Custom Styled Dropdown for Target Audience */}
                   <div className="relative" ref={dropdownRef}>
                      <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-2 ml-2">Gửi tới ai?</label>
                      <button 
                        type="button"
                        onClick={() => setIsTargetDropdownOpen(!isTargetDropdownOpen)}
                        className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 rounded-2xl font-bold text-xs text-slate-700 dark:text-slate-200 outline-none flex items-center justify-between hover:border-indigo-400 transition-all h-[52px]"
                      >
                         <span className="flex items-center gap-2">
                            <i className={`fa-solid ${selectedTargetLabel?.icon} text-indigo-500`}></i>
                            {selectedTargetLabel?.label}
                         </span>
                         <i className={`fa-solid fa-chevron-down text-[10px] transition-transform ${isTargetDropdownOpen ? 'rotate-180' : ''}`}></i>
                      </button>

                      {isTargetDropdownOpen && (
                        <div className="absolute top-full left-0 w-full mt-2 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-600 rounded-2xl shadow-xl overflow-hidden z-20 animate-in fade-in zoom-in duration-200">
                           {targetOptions.map(opt => (
                             <div 
                               key={opt.value}
                               onClick={() => { setTargetUser(opt.value); setIsTargetDropdownOpen(false); }}
                               className={`px-4 py-3 text-xs font-bold cursor-pointer flex items-center gap-3 transition-colors ${targetUser === opt.value ? 'bg-indigo-50 dark:bg-slate-700 text-indigo-600 dark:text-white' : 'hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300'}`}
                             >
                                <div className={`w-6 h-6 rounded-full flex items-center justify-center ${targetUser === opt.value ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                                   <i className={`fa-solid ${opt.icon}`}></i>
                                </div>
                                {opt.label}
                             </div>
                           ))}
                        </div>
                      )}
                   </div>
                </div>

                {/* Icon Selector */}
                <div>
                   <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-3 ml-2">Chọn biểu tượng</label>
                   <div className="flex flex-wrap gap-3">
                      {icons.map((ic) => (
                         <button 
                           key={ic.class}
                           type="button"
                           onClick={() => setSelectedIcon(ic.class)}
                           className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${selectedIcon === ic.class ? 'bg-indigo-600 text-white shadow-lg scale-110' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-600'}`}
                         >
                            <i className={`fa-solid ${ic.class}`}></i>
                         </button>
                      ))}
                   </div>
                </div>

                 {/* Color Selector */}
                <div>
                   <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-3 ml-2">Chọn màu sắc</label>
                   <div className="flex flex-wrap gap-3">
                      {colors.map((c, i) => (
                         <button 
                           key={i}
                           type="button"
                           onClick={() => setSelectedColor(c)}
                           className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${selectedColor.text === c.text ? 'ring-2 ring-offset-2 ring-indigo-400 scale-110' : ''} ${c.bg} ${c.text}`}
                         >
                            <i className="fa-solid fa-circle text-xs"></i>
                         </button>
                      ))}
                   </div>
                </div>

                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="w-full py-4 bg-gradient-to-r from-indigo-500 to-violet-600 hover:from-indigo-600 hover:to-violet-700 text-white rounded-2xl font-bold shadow-xl shadow-indigo-200 dark:shadow-none active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                >
                   {isSubmitting ? (
                     <>
                        <i className="fa-solid fa-circle-notch animate-spin"></i>
                        Đang gửi...
                     </>
                   ) : (
                     <>
                        <i className="fa-solid fa-paper-plane"></i> 
                        {(!sendImmediately && scheduleTime) ? 'Lên lịch gửi' : 'Gửi thông báo ngay'}
                     </>
                   )}
                </button>
             </form>
          </div>

          {/* Right Column: Creative Center (Replaced History) */}
          <div className="space-y-8">
             {/* Phone Mockup Preview - Sticky */}
             <div className="sticky top-6">
                <div className="bg-slate-900 rounded-[3rem] p-4 shadow-2xl border-4 border-slate-800 relative max-w-[320px] mx-auto overflow-hidden">
                   {/* Notch & Top Bar */}
                   <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-xl z-20"></div>
                   <div className="absolute top-2 right-6 w-12 h-3 flex gap-1 justify-end z-20">
                      <div className="w-4 h-full bg-slate-700 rounded-sm"></div>
                      <div className="w-3 h-full bg-slate-700 rounded-sm"></div>
                   </div>

                   {/* Screen Content */}
                   <div className="bg-gradient-to-br from-indigo-500 to-purple-600 h-[500px] rounded-[2.2rem] overflow-hidden relative">
                      {/* Wallpaper Decor */}
                      <div className="absolute inset-0 opacity-30">
                         <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-pink-400 rounded-full blur-2xl"></div>
                         <div className="absolute bottom-[-20px] left-[-20px] w-60 h-60 bg-blue-400 rounded-full blur-3xl"></div>
                      </div>

                      {/* Time & Date */}
                      <div className="text-center pt-12 text-white/90">
                         <div className="text-5xl font-thin tracking-tight">{new Date().toLocaleTimeString('vi-VN', {hour: '2-digit', minute: '2-digit'})}</div>
                         <div className="text-xs font-bold mt-1 opacity-70">{new Date().toLocaleDateString('vi-VN', {weekday: 'long', day: 'numeric', month: 'long'})}</div>
                      </div>

                      {/* Notification Card */}
                      <div className="mt-8 px-4 animate-in slide-in-from-bottom-4 duration-700">
                         <div className="bg-white/90 backdrop-blur-md rounded-2xl p-4 shadow-lg">
                            <div className="flex items-center gap-2 mb-2">
                               <div className="w-5 h-5 bg-gradient-to-tr from-pink-500 to-violet-500 rounded-md flex items-center justify-center text-white text-[10px]">
                                  <i className="fa-solid fa-robot"></i>
                               </div>
                               <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">BibiChat • Vừa xong</span>
                            </div>
                            <div className="flex gap-3">
                               <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${selectedColor.bg} ${selectedColor.text}`}>
                                  <i className={`fa-solid ${selectedIcon} text-lg`}></i>
                               </div>
                               <div className="flex-1 min-w-0">
                                  <h4 className="text-xs font-black text-slate-800 truncate">{title || 'Tiêu đề ở đây...'}</h4>
                                  <p className="text-xs text-slate-600 mt-1 leading-snug line-clamp-2">{desc || 'Nội dung thông báo sẽ hiển thị như thế này trên điện thoại của khách hàng nha!'}</p>
                               </div>
                            </div>
                         </div>
                      </div>

                      {/* Swipe Indicator */}
                      <div className="absolute bottom-2 left-1/2 -translate-x-1/2 w-32 h-1 bg-white/50 rounded-full"></div>
                   </div>
                </div>

                {/* Tips Card */}
                <div className="mt-8 bg-gradient-to-br from-amber-50 to-orange-50 dark:from-slate-700 dark:to-slate-700 p-6 rounded-[2.5rem] border border-amber-100 dark:border-slate-600 relative overflow-hidden group">
                   <div className="absolute -right-6 -bottom-6 w-24 h-24 bg-amber-200/50 dark:bg-slate-600 rounded-full blur-xl group-hover:scale-150 transition-transform duration-700"></div>
                   <h4 className="font-bold text-amber-800 dark:text-amber-400 mb-3 flex items-center gap-2 relative z-10">
                      <i className="fa-solid fa-lightbulb text-xl animate-pulse"></i> Bí kíp của Bibi
                   </h4>
                   <ul className="space-y-3 text-xs font-bold text-slate-600 dark:text-slate-300 relative z-10">
                      <li className="flex items-start gap-2">
                         <span className="w-1.5 h-1.5 bg-amber-400 rounded-full mt-1.5"></span>
                         Thêm Emoji <span className="inline-block animate-bounce">✨</span> giúp tăng 20% tỷ lệ click đó nha!
                      </li>
                      <li className="flex items-start gap-2">
                         <span className="w-1.5 h-1.5 bg-amber-400 rounded-full mt-1.5"></span>
                         Thông báo ngắn gọn (dưới 50 từ) sẽ dễ đọc hơn trên điện thoại.
                      </li>
                      <li className="flex items-start gap-2">
                         <span className="w-1.5 h-1.5 bg-amber-400 rounded-full mt-1.5"></span>
                         Gửi vào khung giờ vàng (9h sáng hoặc 8h tối) để tiếp cận nhiều người nhất.
                      </li>
                   </ul>
                </div>
             </div>
          </div>
       </div>
    </div>
  );
};

export default NotificationManager;

import React, { useState, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import CustomerManagement from './components/CustomerManagement';
import ChatHistory from './components/ChatHistory';
import NotificationManager from './components/NotificationManager'; 
import Login from './components/Login';
import LandingPage from './components/LandingPage';
import { TermsPage, PrivacyPage, ContactPage, DemoPage } from './components/LegalPages'; 
import { View, Document, WidgetSettings, User, Notification } from './types';
import { apiService } from './services/apiService';

// Định nghĩa kiểu cho trang Public
type PublicViewType = 'landing' | 'login' | 'terms' | 'privacy' | 'contact' | 'demo';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [publicView, setPublicView] = useState<PublicViewType>('landing'); 
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedCustomerIdForStats, setSelectedCustomerIdForStats] = useState<string>('all');

  // Dark Mode State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('omnichat_theme') === 'dark';
    }
    return false;
  });

  // Notification State
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [selectedNotification, setSelectedNotification] = useState<Notification | null>(null);
  const [showAllNotifModal, setShowAllNotifModal] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  // Infinite Scroll State for Notifications
  const [visibleNotifCount, setVisibleNotifCount] = useState(20);
  const notifModalScrollRef = useRef<HTMLDivElement>(null);

  // Profile & Password Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#8b5cf6', 
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  const viewNames: Record<View, string> = {
    [View.DASHBOARD]: 'Tổng quan',
    [View.KNOWLEDGE_BASE]: 'Kho tri thức',
    [View.WIDGET_CONFIG]: 'Làm đẹp Widget',
    [View.ANALYTICS]: 'Phân tích',
    [View.INTEGRATION]: 'Mã nhúng',
    [View.DEPLOYMENT_GUIDE]: 'Hướng dẫn',
    [View.CUSTOMER_MANAGEMENT]: 'Khách hàng',
    [View.CHAT_HISTORY]: 'Lịch sử chat',
    [View.NOTIFICATION_MANAGER]: 'Quản lý thông báo'
  };

  useEffect(() => {
    // Apply Dark Mode Class
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('omnichat_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('omnichat_theme', 'light');
    }
  }, [darkMode]);

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    const savedUserRole = localStorage.getItem('omnichat_user_role');

    if (savedUserId) {
      setCurrentUser({
         id: savedUserId,
         email: 'Loading...', 
         role: savedUserRole as any || 'user',
         botSettings: settings,
         createdAt: Date.now()
      });
      setIsLoggedIn(true);

      apiService.getAllUsers().then(users => {
         const me = users.find(u => u.id === savedUserId);
         if(me) handleLoginSuccess(me);
         else if(savedUserId === 'admin') {
             handleLoginSuccess({ 
                 id: 'admin', 
                 email: 'admin@bibichat.io', 
                 role: 'master', 
                 botSettings: settings, 
                 createdAt: Date.now() 
             });
         }
      });
    }

    const handleClickOutside = (event: MouseEvent) => {
      // Close Notif Dropdown
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
        setSelectedNotification(null);
      }
      // Close Profile Dropdown
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);

  }, []);

  // --- Logic Notification Polling ---
  useEffect(() => {
    if (isLoggedIn && currentUser) {
      loadNotifications();
      const interval = setInterval(loadNotifications, 5000);
      return () => {
        clearInterval(interval);
      };
    }
  }, [isLoggedIn, currentUser?.id]);

  const handleNotifModalScroll = () => {
    if (notifModalScrollRef.current) {
        const { scrollTop, scrollHeight, clientHeight } = notifModalScrollRef.current;
        if (scrollTop + clientHeight >= scrollHeight - 50) {
            if (visibleNotifCount < notifications.length) {
                setVisibleNotifCount(prev => prev + 20);
            }
        }
    }
  };

  useEffect(() => {
      if (showAllNotifModal) {
          setVisibleNotifCount(20);
      }
  }, [showAllNotifModal]);

  const loadNotifications = async () => {
    if (currentUser) {
      const data = await apiService.getNotifications(currentUser.id);
      setNotifications(data);
    }
  };

  const handleNotificationClick = async (notif: Notification) => {
    setSelectedNotification(notif);
    if (!notif.isRead) {
      await apiService.markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
    }
  };

  const handleMarkAllRead = async () => {
    if (!currentUser) return;
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
    await apiService.markAllNotificationsRead(currentUser.id);
  };

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setPublicView('landing'); 
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    localStorage.setItem('omnichat_user_role', user.role);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
    localStorage.removeItem('omnichat_user_role');
    setPublicView('landing'); 
    setNotifications([]); 
  };

  // Logic Change Password
  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu quá ngắn (>= 6 ký tự)' });
      return;
    }

    try {
      const result = await apiService.changePassword(currentUser.id, currentUser.password || '', passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) {
    if (publicView === 'terms') return <TermsPage onNavigate={setPublicView} />;
    if (publicView === 'privacy') return <PrivacyPage onNavigate={setPublicView} />;
    if (publicView === 'contact') return <ContactPage onNavigate={setPublicView} />;
    if (publicView === 'demo') return <DemoPage onNavigate={setPublicView} />;

    if (publicView === 'landing') {
        return <LandingPage onNavigate={setPublicView} />;
    }

    return (
      <>
        <div className="absolute top-4 left-4 z-50">
           <button 
             onClick={() => setPublicView('landing')}
             className="px-4 py-2 bg-white/50 hover:bg-white rounded-xl text-sm font-bold text-slate-600 transition-all backdrop-blur-sm shadow-sm"
           >
             <i className="fa-solid fa-arrow-left mr-2"></i>Trang chủ
           </button>
        </div>
        <Login onLogin={handleLoginSuccess} />
      </>
    );
  }

  return (
    <div className={`flex h-screen w-full overflow-hidden relative font-sans antialiased transition-colors duration-500
      ${darkMode ? 'bg-slate-900 text-slate-100 selection:bg-purple-500 selection:text-white' : 'bg-[#f0f2f5] text-slate-700 selection:bg-pink-100 selection:text-pink-900'}
    `}>
      {/* Dynamic Background Mesh Gradient */}
      {!darkMode && (
        <div className="absolute inset-0 z-0 pointer-events-none opacity-60">
           <div className="absolute top-[-10%] left-[-10%] w-[40rem] h-[40rem] bg-pink-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
           <div className="absolute top-[-10%] right-[-10%] w-[40rem] h-[40rem] bg-purple-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>
           <div className="absolute bottom-[-10%] left-[20%] w-[40rem] h-[40rem] bg-yellow-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-4000"></div>
        </div>
      )}

      {/* Dark Mode Background Decor */}
      {darkMode && (
         <div className="absolute inset-0 z-0 pointer-events-none">
            <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-purple-900/20 rounded-full blur-[120px]"></div>
            <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-blue-900/20 rounded-full blur-[120px]"></div>
         </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <Sidebar 
        currentView={currentView} 
        onViewChange={handleViewChange} 
        onLogout={handleLogout}
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        user={currentUser!}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative z-10">
        <header className="h-24 flex items-center justify-between px-8 z-30 shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden w-12 h-12 bg-white/50 dark:bg-slate-800 rounded-2xl shadow-sm flex items-center justify-center text-pink-500 hover:text-pink-600 transition-colors backdrop-blur-sm">
              <i className="fas fa-bars text-xl"></i>
            </button>
            <div className="flex flex-col">
              <h1 className="text-3xl font-black text-slate-800 dark:text-white tracking-tight drop-shadow-sm">
                {viewNames[currentView]}
              </h1>
              <p className="text-sm font-bold text-slate-500 dark:text-slate-400 hidden sm:block">
                {currentUser?.role === 'master' ? '🚀 Control Center' : '✨ Dashboard Doanh Nghiệp'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             {/* Dark Mode Toggle */}
             <button 
               onClick={() => setDarkMode(!darkMode)}
               className="w-12 h-12 rounded-full bg-white/60 dark:bg-slate-800 border border-white dark:border-slate-700 shadow-sm flex items-center justify-center text-slate-600 dark:text-yellow-400 hover:scale-110 transition-transform backdrop-blur-sm"
               title={darkMode ? "Chuyển sang sáng" : "Chuyển sang tối"}
             >
                <i className={`fa-solid ${darkMode ? 'fa-sun' : 'fa-moon'} text-xl`}></i>
             </button>

             {/* Notification Bell */}
             <div className="relative" ref={notifRef}>
               <button 
                onClick={() => { setShowNotifications(!showNotifications); setSelectedNotification(null); }}
                className="w-12 h-12 bg-white/60 dark:bg-slate-800 rounded-full shadow-sm flex items-center justify-center text-slate-500 dark:text-slate-300 hover:text-pink-500 dark:hover:text-pink-400 hover:scale-110 transition-all relative active:scale-95 group border border-white dark:border-slate-700 backdrop-blur-sm"
               >
                 <i className={`fa-regular fa-bell text-xl ${unreadCount > 0 ? 'group-hover:animate-swing' : ''}`}></i>
                 {unreadCount > 0 && (
                   <span className="absolute top-0 right-0 w-5 h-5 bg-rose-500 text-white text-[10px] font-bold rounded-full border-2 border-white dark:border-slate-800 flex items-center justify-center animate-bounce-slow">
                     {unreadCount}
                   </span>
                 )}
               </button>

               {/* Notification Dropdown Container */}
               {showNotifications && (
                 <div className="absolute right-0 mt-4 w-80 sm:w-96 bg-white/90 dark:bg-slate-800/95 backdrop-blur-xl rounded-[2rem] shadow-[0_20px_40px_-10px_rgba(0,0,0,0.2)] border border-white dark:border-slate-700 overflow-hidden animate-in fade-in zoom-in duration-200 z-50">

                    {/* Header */}
