                       <h3 className="font-bold text-base text-slate-800 dark:text-white">Thông báo</h3>
                       <div className="flex gap-2">
                           {unreadCount > 0 && (
                             <button 
                               onClick={handleMarkAllRead}
                               className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/30 text-indigo-500 hover:bg-indigo-100 dark:hover:bg-indigo-900 flex items-center justify-center transition-colors"
                               title="Đánh dấu tất cả là đã đọc"
                             >
                                <i className="fa-solid fa-check-double text-xs"></i>
                             </button>
                           )}
                           {unreadCount > 0 && <span className="text-[10px] bg-pink-100 dark:bg-pink-900 text-pink-600 dark:text-pink-300 px-3 py-1 rounded-full font-bold flex items-center">{unreadCount} mới</span>}
                       </div>
                    </div>

                    {/* Content Area */}
                    <div className="relative h-80">
                        {/* List View */}
                        <div className={`absolute inset-0 overflow-y-auto p-2 transition-transform duration-300 ${selectedNotification ? '-translate-x-full opacity-0 pointer-events-none' : 'translate-x-0 opacity-100'}`}>
