import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole, Notification } from "../types";

const API_URL = 'http://localhost:3001/api';
const DB_KEY = 'omnichat_db_v1';

// Cấu hình tài khoản Master mặc định
const MASTER_USER: User = {
  id: 'admin',
  email: 'admin@bibichat.io',
  password: '123456',
  role: 'master',
  createdAt: Date.now(),
  botSettings: { 
    botName: 'BibiBot', 
    primaryColor: '#ec4899', 
    welcomeMessage: 'Xin chào! Hệ thống quản trị Master (Offline Mode).', 
    position: 'right', 
    avatarUrl: '' 
  }
};

// --- HELPER: LOCAL STORAGE FALLBACK ---
const getLocalDB = () => {
  const data = localStorage.getItem(DB_KEY);
  let db;

  if (!data) {
    db = { 
      users: [MASTER_USER], 
      documents: [],
      chatLogs: [],
      notifications: []
    };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  } else {
    db = JSON.parse(data);
    if (!db.users.find((u: any) => u.id === 'admin')) {
      db.users.unshift(MASTER_USER);
      localStorage.setItem(DB_KEY, JSON.stringify(db));
    }
    // Ensure notifications array exists
    if (!db.notifications) db.notifications = [];
  }
  return db;
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    // 0. Kiểm tra trùng lặp Local trước
    const db = getLocalDB();
    if (db.users.find((u: any) => u.email === email)) {
       return { success: false, message: 'Email này đã được đăng ký rồi nè!' };
    }

    // 1. Tạo user object
    const newUser: User = {
      id: Math.random().toString(36).substring(2, 11),
      email,
      password,
      role: 'user',
      createdAt: Date.now(),
      botSettings: {
        botName: 'Trợ lý AI',
        primaryColor: '#8b5cf6',
        welcomeMessage: 'Xin chào!',
        position: 'right',
        avatarUrl: ''
      }
    };

    // 2. Luôn lưu vào LocalStorage (Shadow Save) để đảm bảo Admin nhìn thấy ngay
    db.users.push(newUser);
    saveLocalDB(db);

    // 3. Gọi Server (nếu online)
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (res.ok) {
         const serverRes = await res.json();
         // Ưu tiên dùng ID từ server nếu có
         return serverRes;
      }
    } catch (e) {
      console.warn("Server Offline: Registration saved locally.");
    }

    // Trả về kết quả thành công dựa trên LocalStorage
    return { success: true, message: 'Đăng ký thành công (Offline/Hybrid)', user: newUser };
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (!res.ok) throw new Error("Server response not ok");
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();

      let user = db.users.find((u: any) => u.email === email && u.password === password);

      if (!user && email === MASTER_USER.email && password === MASTER_USER.password) {
        user = MASTER_USER;
        if (!db.users.find((u: any) => u.id === 'admin')) {
           db.users.unshift(MASTER_USER);
           saveLocalDB(db);
        }
      }

      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Email hoặc mật khẩu không chính xác.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx === -1) return { success: false, message: "User không tồn tại" };
      if (db.users[idx].password !== oldPassword) return { success: false, message: "Mật khẩu cũ sai" };
      db.users[idx].password = newPassword;
      saveLocalDB(db);
      return { success: true, message: "Đổi mật khẩu thành công (Offline)" };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    const localDB = getLocalDB();
    const localUsers: User[] = localDB.users;

    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) throw new Error("Server error");
      const serverUsers: User[] = await res.json();

      // Merge: Lấy tất cả user từ Local + Server, loại bỏ trùng lặp email
      const map = new Map();

      // Ưu tiên local users trước để đảm bảo những user vừa tạo (chưa sync server) được hiện
      [...localUsers, ...serverUsers].forEach(u => {
        if (!map.has(u.email)) {
          map.set(u.email, u);
        }
      });

      const combinedUsers = Array.from(map.values());
      return combinedUsers.filter((u: any) => u.id !== 'admin'); 
    } catch (e) {
      return localUsers.filter(u => u.id !== 'admin');
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === targetUserId);
      if (idx !== -1) {
        db.users[idx].password = newPassword;
        saveLocalDB(db);
        return { success: true, message: "Reset thành công (Offline)" };
      }
      return { success: false, message: "Lỗi Offline" };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      db.documents = db.documents.filter((d: any) => d.userId !== targetUserId);
      db.chatLogs = db.chatLogs.filter((l: any) => l.userId !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Offline)" };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    try {
      await fetch(`${API_URL}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx !== -1) {
        db.users[idx].botSettings = settings;
        saveLocalDB(db);
      }
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      if (!res.ok) throw new Error("Server error");
      const doc = await res.json();
      if (type === 'file') doc.type = 'file'; 
      return doc;
    } catch (e) {
      const db = getLocalDB();
      const newDoc: Document = {
        id: Math.random().toString(36).substring(2, 11),
        userId,
        name,
        content,
        type,
        status: 'indexed',
        createdAt: Date.now()
      };
      db.documents.push(newDoc);
      saveLocalDB(db);
      return newDoc;
    }
  },

  deleteDocument: async (id: string) => {
    try {
      await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];

    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }

    const statsMap: Record<string, { queries: number, solved: number }> = {};

    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);

      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;

      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });

    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    const db = getLocalDB();
    let logs = db.chatLogs as ChatLog[];
    if (userId !== 'all') {
      logs = logs.filter(l => l.userId === userId);
    }
    return logs.sort((a, b) => b.timestamp - a.timestamp);
  },

  // --- NOTIFICATIONS ---
  getNotifications: async (userId: string): Promise<Notification[]> => {
    try {
      const res = await fetch(`${API_URL}/notifications/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      // Filter offline & schedule check
      const now = Date.now();
      return (db.notifications || [])
        .filter((n: any) => {
          const isTargetUser = (n.userId === 'all' || n.userId === userId);
          if (!isTargetUser) return false;
          // Nếu admin, xem hết. Nếu không, chỉ xem quá khứ.
          if (userId === 'admin') return true;
          return n.scheduledAt ? n.scheduledAt <= now : n.time <= now;
        })
        .sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    }
  },

  getAdminNotifications: async (): Promise<Notification[]> => {
    try {
      const res = await fetch(`${API_URL}/admin/notifications`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return (db.notifications || []).sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    }
  },

  markNotificationRead: async (id: string): Promise<void> => {
    try {
      await fetch(`${API_URL}/notifications/${id}/read`, { method: 'POST' });
    } catch (e) {
      const db = getLocalDB();
      const n = db.notifications?.find((x: any) => x.id === id);
      if (n) {
        n.isRead = true;
        saveLocalDB(db);
      }
    }
  },

  markAllNotificationsRead: async (userId: string): Promise<void> => {
    try {
        await fetch(`${API_URL}/notifications/read-all`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ userId })
        });
    } catch (e) {
        const db = getLocalDB();
        const now = Date.now();
        db.notifications?.forEach((n: any) => {
            const isTargetUser = (n.userId === 'all' || n.userId === userId);
            const isVisible = userId === 'admin' ? true : (n.scheduledAt ? n.scheduledAt <= now : n.time <= now);

            if (isTargetUser && isVisible) {
                n.isRead = true;
            }
        });
        saveLocalDB(db);
    }
  },

  // Tạo thông báo (Admin)
  createSystemNotification: async (data: Partial<Notification>) => {
    try {
      await fetch(`${API_URL}/notifications/create`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(data)
      });
    } catch (e) {
      // Offline fallback
      const db = getLocalDB();
      if (!db.notifications) db.notifications = [];
      const now = Date.now();
      db.notifications.push({
        id: Math.random().toString(36).substr(2, 9),
        userId: data.userId || 'all',
        title: data.title || '',
        desc: data.desc || '',
        time: data.scheduledAt || now, 
        scheduledAt: data.scheduledAt || now,
        isRead: false,
        icon: data.icon || 'fa-bell',
        color: data.color || 'text-blue-500',
        bg: data.bg || 'bg-blue-100'
      });
      saveLocalDB(db);
    }
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    let context = "";
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if(res.ok) {
        const docs: Document[] = await res.json();
        context = docs.map(d => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      } else { throw new Error("API Docs Error"); }
    } catch (e) {
       const db = getLocalDB();
       context = db.documents.filter((d: any) => d.userId === userId)
         .map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
    }

    if (!process.env.API_KEY) return "Vui lòng cấu hình API_KEY.";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `Bạn là trợ lý AI tên "${botName}". Hãy sử dụng kho kiến thức sau: \n${context}`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: message,
        config: { systemInstruction }
      });

      const reply = response.text || "Tôi không thể trả lời.";

      const db = getLocalDB();
      const newLog: ChatLog = {
        id: Math.random().toString(36).substring(2, 9),
        userId,
        customerSessionId: 'anon-session',
        query: message,
        answer: reply,
        timestamp: Date.now(),
        tokens: message.length + (reply?.length || 0),
        isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi")
      };
      db.chatLogs.push(newLog);
      saveLocalDB(db);

      return reply;
    } catch (e) {
      console.error(e);
      return "Lỗi AI hoặc mất kết nối mạng.";
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import KnowledgeBase from './components/KnowledgeBase';
import WidgetPreview from './components/WidgetPreview';
import ChatWidget from './components/ChatWidget';
import Integration from './components/Integration';
import DeploymentGuide from './components/DeploymentGuide';
import CustomerManagement from './components/CustomerManagement';
import ChatHistory from './components/ChatHistory';
import NotificationManager from './components/NotificationManager'; 
import Login from './components/Login';
import LandingPage from './components/LandingPage';
import { TermsPage, PrivacyPage, ContactPage, DemoPage } from './components/LegalPages'; 
import { View, Document, WidgetSettings, User, Notification } from './types';
import { apiService } from './services/apiService';

// Định nghĩa kiểu cho trang Public
type PublicViewType = 'landing' | 'login' | 'terms' | 'privacy' | 'contact' | 'demo';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [publicView, setPublicView] = useState<PublicViewType>('landing'); 
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedCustomerIdForStats, setSelectedCustomerIdForStats] = useState<string>('all');

  // Dark Mode State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('omnichat_theme') === 'dark';
    }
    return false;
  });

  // Notification State
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [selectedNotification, setSelectedNotification] = useState<Notification | null>(null);
  const [showAllNotifModal, setShowAllNotifModal] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  // Infinite Scroll State for Notifications
  const [visibleNotifCount, setVisibleNotifCount] = useState(20);
  const notifModalScrollRef = useRef<HTMLDivElement>(null);

  // Profile & Password Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordForm, setPasswordForm] = useState({ old: '', new: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });

  const [settings, setSettings] = useState<WidgetSettings>({
    primaryColor: '#8b5cf6', 
    botName: 'Trợ lý AI',
    welcomeMessage: 'Xin chào! Tôi có thể giúp gì cho bạn?',
    position: 'right',
    avatarUrl: 'https://picsum.photos/100/100'
  });

  const viewNames: Record<View, string> = {
    [View.DASHBOARD]: 'Tổng quan',
    [View.KNOWLEDGE_BASE]: 'Kho tri thức',
    [View.WIDGET_CONFIG]: 'Làm đẹp Widget',
    [View.ANALYTICS]: 'Phân tích',
    [View.INTEGRATION]: 'Mã nhúng',
    [View.DEPLOYMENT_GUIDE]: 'Hướng dẫn',
    [View.CUSTOMER_MANAGEMENT]: 'Khách hàng',
    [View.CHAT_HISTORY]: 'Lịch sử chat',
    [View.NOTIFICATION_MANAGER]: 'Quản lý thông báo'
  };

  useEffect(() => {
    // Apply Dark Mode Class
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('omnichat_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('omnichat_theme', 'light');
    }
  }, [darkMode]);

  useEffect(() => {
    const savedUserId = localStorage.getItem('omnichat_user_id');
    const savedUserRole = localStorage.getItem('omnichat_user_role');

    if (savedUserId) {
      setCurrentUser({
         id: savedUserId,
         email: 'Loading...', 
         role: savedUserRole as any || 'user',
         botSettings: settings,
         createdAt: Date.now()
      });
      setIsLoggedIn(true);

      apiService.getAllUsers().then(users => {
         const me = users.find(u => u.id === savedUserId);
         if(me) handleLoginSuccess(me);
         else if(savedUserId === 'admin') {
             handleLoginSuccess({ 
                 id: 'admin', 
                 email: 'admin@bibichat.io', 
                 role: 'master', 
                 botSettings: settings, 
                 createdAt: Date.now() 
             });
         }
      });
    }

    const handleClickOutside = (event: MouseEvent) => {
      // Close Notif Dropdown
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
        setSelectedNotification(null);
      }
      // Close Profile Dropdown
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);

  }, []);

  // --- Logic Notification Polling ---
  useEffect(() => {
    if (isLoggedIn && currentUser) {
      loadNotifications();
      const interval = setInterval(loadNotifications, 5000);
      return () => {
        clearInterval(interval);
      };
    }
  }, [isLoggedIn, currentUser?.id]);

  const handleNotifModalScroll = () => {
    if (notifModalScrollRef.current) {
        const { scrollTop, scrollHeight, clientHeight } = notifModalScrollRef.current;
        if (scrollTop + clientHeight >= scrollHeight - 50) {
            if (visibleNotifCount < notifications.length) {
                setVisibleNotifCount(prev => prev + 20);
            }
        }
    }
  };

  useEffect(() => {
      if (showAllNotifModal) {
          setVisibleNotifCount(20);
      }
  }, [showAllNotifModal]);

  const loadNotifications = async () => {
    if (currentUser) {
      const data = await apiService.getNotifications(currentUser.id);
      setNotifications(data);
    }
  };

  const handleNotificationClick = async (notif: Notification) => {
    setSelectedNotification(notif);
    if (!notif.isRead) {
      await apiService.markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
    }
  };

  const handleMarkAllRead = async () => {
    if (!currentUser) return;
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
    await apiService.markAllNotificationsRead(currentUser.id);
  };

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const handleLoginSuccess = async (user: User) => {
    setIsLoggedIn(true);
    setPublicView('landing'); 
    setCurrentUser(user);
    setSettings(user.botSettings);
    localStorage.setItem('omnichat_user_id', user.id);
    localStorage.setItem('omnichat_user_role', user.role);
    const docs = await apiService.getDocuments(user.id);
    setDocuments(docs);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem('omnichat_user_id');
    localStorage.removeItem('omnichat_user_role');
    setPublicView('landing'); 
    setNotifications([]); 
  };

  // Logic Change Password
  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    if (passwordForm.new !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu không khớp' });
      return;
    }
    if (passwordForm.new.length < 6) {
      setPasswordMsg({ type: 'error', text: 'Mật khẩu quá ngắn (>= 6 ký tự)' });
      return;
    }

    try {
      const result = await apiService.changePassword(currentUser.id, currentUser.password || '', passwordForm.new);
      if (result.success) {
        setPasswordMsg({ type: 'success', text: result.message });
        setTimeout(() => {
          setShowPasswordModal(false);
          setPasswordForm({ old: '', new: '', confirm: '' });
          setPasswordMsg({ type: '', text: '' });
        }, 1500);
      } else {
        setPasswordMsg({ type: 'error', text: result.message });
      }
    } catch (err) {
      setPasswordMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
  };

  const updateSettings = async (newSettings: WidgetSettings) => {
    setSettings(newSettings);
    if (currentUser) await apiService.updateSettings(currentUser.id, newSettings);
  };

  const addDocument = async (name: string, content: string, type: 'text' | 'file') => {
    if (currentUser) {
      const newDoc = await apiService.addDocument(currentUser.id, name, content, type);
      setDocuments([...documents, newDoc]);
    }
  };

  const deleteDocument = async (id: string) => {
    await apiService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const handleViewChange = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    if (view !== View.DASHBOARD) setSelectedCustomerIdForStats('all');
  };

  const handleViewCustomerStats = (userId: string) => {
    setSelectedCustomerIdForStats(userId);
    setCurrentView(View.DASHBOARD);
  };

  if (!isLoggedIn) {
    if (publicView === 'terms') return <TermsPage onNavigate={setPublicView} />;
    if (publicView === 'privacy') return <PrivacyPage onNavigate={setPublicView} />;
    if (publicView === 'contact') return <ContactPage onNavigate={setPublicView} />;
    if (publicView === 'demo') return <DemoPage onNavigate={setPublicView} />;

    if (publicView === 'landing') {
        return <LandingPage onNavigate={setPublicView} />;
    }

    return (
      <>
        <div className="absolute top-4 left-4 z-50">
           <button 
             onClick={() => setPublicView('landing')}
             className="px-4 py-2 bg-white/50 hover:bg-white rounded-xl text-sm font-bold text-slate-600 transition-all backdrop-blur-sm shadow-sm"
           >
             <i className="fa-solid fa-arrow-left mr-2"></i>Trang chủ
           </button>
        </div>
        <Login onLogin={handleLoginSuccess} />
      </>
    );
  }

  return (
    <div className={`flex h-screen w-full overflow-hidden relative font-sans antialiased transition-colors duration-500
      ${darkMode ? 'bg-slate-900 text-slate-100 selection:bg-purple-500 selection:text-white' : 'bg-[#f0f2f5] text-slate-700 selection:bg-pink-100 selection:text-pink-900'}
    `}>
      {/* Dynamic Background Mesh Gradient */}
      {!darkMode && (
        <div className="absolute inset-0 z-0 pointer-events-none opacity-60">
           <div className="absolute top-[-10%] left-[-10%] w-[40rem] h-[40rem] bg-pink-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
           <div className="absolute top-[-10%] right-[-10%] w-[40rem] h-[40rem] bg-purple-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>
           <div className="absolute bottom-[-10%] left-[20%] w-[40rem] h-[40rem] bg-yellow-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-4000"></div>
        </div>
      )}

      {/* Dark Mode Background Decor */}
      {darkMode && (
         <div className="absolute inset-0 z-0 pointer-events-none">
            <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-purple-900/20 rounded-full blur-[120px]"></div>
            <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-blue-900/20 rounded-full blur-[120px]"></div>
         </div>
