                 </div>
               </div>

               <button type="submit" className="w-full py-4 bg-gradient-to-r from-pink-500 to-rose-600 hover:from-pink-600 hover:to-rose-700 text-white rounded-2xl font-black shadow-xl shadow-pink-200 dark:shadow-none transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-2 text-base group">
                 <span>Cập nhật ngay</span>
                 <i className="fa-solid fa-arrow-right group-hover:translate-x-1 transition-transform"></i>
               </button>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

export enum View {
  DASHBOARD = 'dashboard',
  KNOWLEDGE_BASE = 'knowledge_base',
  WIDGET_CONFIG = 'widget_config',
  ANALYTICS = 'analytics',
  INTEGRATION = 'integration',
  DEPLOYMENT_GUIDE = 'deployment_guide',
  CUSTOMER_MANAGEMENT = 'customer_management',
  CHAT_HISTORY = 'chat_history',
  NOTIFICATION_MANAGER = 'notification_manager'
}

export type UserRole = 'master' | 'user';

export interface Document {
  id: string;
  userId: string;
  name: string;
  content: string;
  type: 'file' | 'url' | 'text';
  status: 'indexed' | 'processing';
  createdAt: number;
}

export interface ChatLog {
  id: string;
  userId: string; // ID của chủ sở hữu bot
  customerSessionId: string;
  query: string;  // Nội dung người dùng hỏi
  answer: string; // Nội dung AI trả lời
  timestamp: number;
  tokens: number;
  isSolved: boolean;
}

export interface User {
  id: string;
  email: string;
  password?: string;
  role: UserRole;
  botSettings: WidgetSettings;
  createdAt: number;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface WidgetSettings {
  primaryColor: string;
  botName: string;
  welcomeMessage: string;
  position: 'right' | 'left';
  avatarUrl: string;
}

export interface AnalyticsData {
  label: string;
  queries: number;
  solved: number;
}

export interface Notification {
  id: string;
  userId: string; // 'all' hoặc userId cụ thể
  title: string;
  desc: string;
  time: number; // Thời gian tạo/hiển thị thực tế
  scheduledAt: number; // Thời gian hẹn giờ
  readBy: string[]; // Danh sách ID người dùng đã đọc
  isRead?: boolean; // Computed field cho frontend (không lưu trong DB nếu dùng readBy)
  icon: string;
  color: string;
  bg: string;
}

import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

const app = express();
const PORT = 3001;

// Cấu hình CORS để cho phép các website khác gọi API của bạn
app.use(cors({
  origin: '*', // Trong môi trường Production, hãy thay '*' bằng danh sách domain cụ thể của khách hàng
  methods: ['GET', 'POST', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}) as any);

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const dir = './uploads';
    if (!fs.existsSync(dir)) fs.mkdirSync(dir);
    cb(null, dir);
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});
