                         <div className="bg-white/90 backdrop-blur-md rounded-[1.5rem] p-4 shadow-xl border border-white/40 flex gap-4">
                            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${selectedColor.bg} ${selectedColor.text} shadow-sm text-xl border-2 border-white/50`}>
                               <i className={`fa-solid ${selectedIcon}`}></i>
                            </div>
                            <div className="flex-1 min-w-0">
                               <div className="flex justify-between items-start mb-1">
                                  <h4 className="text-sm font-black text-slate-800 truncate">{title || 'Tiêu đề ở đây...'}</h4>
