import express from 'express';
import cors from 'cors';
import mongoose from 'mongoose';
import { GoogleGenAI } from "@google/genai";
import multer from 'multer';

// --- CONFIGURATION ---
const app = express();
const PORT = process.env.PORT || 3001;
// Lấy connection string từ biến môi trường (sẽ cài đặt trên Vercel)
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb+srv://demo:demo@cluster0.demo.mongodb.net/bibichat?retryWrites=true&w=majority'; 

app.use(cors({
  origin: '*', 
  methods: ['GET', 'POST', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}) as any);

app.use(express.json() as any);

// --- MONGODB CONNECTION ---
mongoose.connect(MONGODB_URI)
  .then(() => console.log('✅ Connected to MongoDB Atlas'))
  .catch(err => console.error('❌ MongoDB connection error:', err));

// --- SCHEMAS & MODELS ---
const UserSchema = new mongoose.Schema({
  id: { type: String, required: true, unique: true },
  email: { type: String, required: true },
  password: { type: String, required: true },
  role: { type: String, default: 'user' },
  createdAt: { type: Number, default: Date.now },
  botSettings: {
    botName: { type: String, default: 'Trợ lý AI' },
    primaryColor: { type: String, default: '#8b5cf6' },
    welcomeMessage: { type: String, default: 'Xin chào!' },
    position: { type: String, default: 'right' },
    avatarUrl: String
  }
});
const UserModel = mongoose.model('User', UserSchema);

const DocumentSchema = new mongoose.Schema({
  id: { type: String, required: true, unique: true },
  userId: { type: String, required: true },
  name: String,
  content: String,
  type: String,
  status: String,
  createdAt: { type: Number, default: Date.now }
});
const DocumentModel = mongoose.model('Document', DocumentSchema);

const ChatLogSchema = new mongoose.Schema({
  id: { type: String, required: true },
  userId: { type: String, required: true },
  customerSessionId: String,
  query: String,
  answer: String,
  timestamp: { type: Number, default: Date.now },
  tokens: Number,
  isSolved: Boolean
});
const ChatLogModel = mongoose.model('ChatLog', ChatLogSchema);

const NotificationSchema = new mongoose.Schema({
  id: { type: String, required: true },
  userId: String,
  title: String,
  desc: String,
  time: Number,
  scheduledAt: Number,
  readBy: [String],
  icon: String,
  color: String,
  bg: String
});
const NotificationModel = mongoose.model('Notification', NotificationSchema);

// --- MULTER CONFIG (MEMORY STORAGE FOR VERCEL) ---
// Trên Vercel không lưu file ra disk được, nên ta dùng memory storage
// để đọc nội dung file text ngay lập tức rồi lưu vào DB
const upload = multer({ storage: multer.memoryStorage() });

// --- API ROUTES ---

// 1. Notifications
app.get('/api/notifications/:userId', async (req, res) => {
  const { userId } = req.params;
  const now = Date.now();

  try {
    const allNotifs = await NotificationModel.find({});

    let notifs = allNotifs.filter((n: any) => {
        const nUserId = String(n.userId || '').trim();
        const reqUserId = String(userId || '').trim();
        const isTargetUser = (nUserId === 'all' || nUserId === reqUserId);

        if (!isTargetUser) return false;
        if (reqUserId === 'admin') return true;

        const scheduleTime = Number(n.scheduledAt || n.time || 0);
        return scheduleTime <= (now + 60000); 
    });

    const result = notifs.map((n: any) => ({
        ...n.toObject(),
        isRead: Array.isArray(n.readBy) ? n.readBy.includes(userId) : false
    }));

    result.sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    res.json(result);
  } catch (e) { res.status(500).json({error: e}); }
});

