    }
  },

  // Tính năng AI: Gợi ý icon
  suggestIcon: async (text: string): Promise<string> => {
    if (!process.env.API_KEY) return 'fa-bullhorn';

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Based on the following notification text, suggest the single most appropriate FontAwesome 6 icon class name. ONLY return the class name string.
    Text: "${text}"`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      const iconClass = response.text?.trim() || 'fa-bullhorn';
      return iconClass.replace(/['".]/g, '');
    } catch (error) {
      return 'fa-bullhorn';
    }
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    // Chat luôn cần gọi server để AI xử lý và lưu log vào server
    try {
      const res = await fetch(`${API_URL}/chat`, {
         method: 'POST',
