        body: JSON.stringify({ email, password })
      });

      const serverRes = await res.json();
      if (res.ok && serverRes.success) {
         return serverRes;
      } else {
         return { success: false, message: serverRes.message || 'Lỗi đăng ký từ server' };
      }
    } catch (e) {
      console.warn("Server Offline: Registration saved locally.");

      // Fallback Offline
      const db = getLocalDB();
      if (db.users.find((u: any) => u.email === email)) {
         return { success: false, message: 'Email này đã được đăng ký (Offline)' };
