                        {/* LIST VIEW with Infinite Scroll */}
                        <div 
                            className={`absolute inset-0 px-4 py-2 transition-transform duration-300 ${selectedNotification ? '-translate-x-full opacity-0 pointer-events-none' : 'translate-x-0 opacity-100'} ${notifications.length > 0 ? 'overflow-y-auto no-scrollbar scroll-smooth' : 'flex items-center justify-center'}`}
                            onScroll={handleDropdownScroll}
                        >
                           {notifications.length > 0 ? (
                             <div className="space-y-3 pt-3 pb-6">
                               {notifications.slice(0, visibleNotifCount).map(notif => {
                                 const isScheduled = notif.scheduledAt > Date.now();
                                 const isRead = notif.isRead;

                                 // Cute Card Styling
                                 let cardStyle = "relative p-4 rounded-[1.5rem] transition-all duration-300 cursor-pointer group flex items-start gap-4 border-2 ";

                                 if (isScheduled) {
                                   // Scheduled Style
                                   cardStyle += "bg-amber-50/80 dark:bg-amber-900/10 border-dashed border-amber-300/60 dark:border-amber-700 hover:bg-amber-100 dark:hover:bg-amber-900/30";
                                 } else if (!isRead) {
                                   // Unread Style - Popping out
                                   cardStyle += "bg-white dark:bg-slate-800 border-white dark:border-slate-700 shadow-[0_8px_20px_-6px_rgba(236,72,153,0.15)] dark:shadow-none hover:border-pink-200 dark:hover:border-pink-800 hover:shadow-lg hover:shadow-pink-100/50 transform hover:-translate-y-1 z-10";
                                 } else {
                                   // Read Style - Subtle
                                   cardStyle += "bg-white/40 dark:bg-slate-800/40 border-transparent hover:bg-white dark:hover:bg-slate-700 hover:border-slate-100 dark:hover:border-slate-600";
                                 }

                                 return (
                                   <div key={notif.id} onClick={() => handleNotificationClick(notif)} className={cardStyle}>
                                      {/* Icon Box */}
                                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${notif.bg} ${notif.color} shadow-sm border-[3px] border-white dark:border-slate-700 relative group-hover:rotate-6 transition-transform duration-300`}>
                                         <i className={`fa-solid ${notif.icon} text-lg`}></i>

                                         {/* Unread/Status Badge */}
                                         {isScheduled ? (
                                             <span className="absolute -top-1 -right-1 w-4 h-4 bg-amber-400 rounded-full border-2 border-white dark:border-slate-800 flex items-center justify-center shadow-sm" title="Chờ gửi">
                                                <i className="fa-solid fa-clock text-[8px] text-white"></i>
                                             </span>
                                         ) : !isRead && (
                                            <span className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800 animate-pulse"></span>
                                         )}
                                      </div>

                                      {/* Text Content */}
                                      <div className="flex-1 min-w-0 pt-0.5">
                                         <div className="flex justify-between items-start gap-2 mb-1">
                                            <h4 className={`text-sm leading-snug truncate ${!isRead && !isScheduled ? 'font-black text-slate-800 dark:text-white' : 'font-bold text-slate-600 dark:text-slate-300'}`}>
                                                {notif.title}
                                            </h4>
                                            <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 whitespace-nowrap bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded-md">
                                                {new Date(notif.time).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                                            </span>
                                         </div>
                                         <p className={`text-xs leading-relaxed line-clamp-2 ${!isRead ? 'text-slate-600 dark:text-slate-400 font-medium' : 'text-slate-500 dark:text-slate-500'}`}>
                                            {notif.desc}
                                         </p>
                                      </div>
                                   </div>
                                 );
                               })}

                               {/* Loading / End Indicators */}
                               {notifications.length > visibleNotifCount && (
                                  <div className="py-4 text-center">
                                      <div className="w-8 h-8 mx-auto rounded-full border-2 border-pink-200 border-t-pink-500 animate-spin bg-white dark:bg-slate-800"></div>
                                      <p className="text-[10px] font-bold text-slate-400 mt-2">Đang tải thêm...</p>
                                  </div>
                               )}

                               {notifications.length > 0 && notifications.length <= visibleNotifCount && (
                                  <div className="text-center py-8 opacity-50">
                                      <i className="fa-solid fa-check-circle text-2xl text-slate-300 mb-2"></i>
                                      <p className="text-xs font-bold text-slate-400">Đã hết thông báo rồi nè</p>
                                  </div>
                               )}
                             </div>
                           ) : (
                             // Cute Empty State
                             <div className="flex flex-col items-center justify-center h-full text-center px-8 pb-10">
                               <div className="relative mb-6">
                                  <div className="w-24 h-24 bg-gradient-to-tr from-indigo-50 to-pink-50 dark:from-slate-800 dark:to-slate-700 rounded-full flex items-center justify-center shadow-inner border-[6px] border-white dark:border-slate-800">
                                     <i className="fa-solid fa-box-open text-4xl text-slate-300 dark:text-slate-500"></i>
                                  </div>
                                  <div className="absolute -bottom-2 -right-2 text-2xl animate-bounce delay-700">🍃</div>
                               </div>
                               <h4 className="text-lg font-black text-slate-700 dark:text-slate-300 mb-2">Hộp thư trống trơn!</h4>
                               <p className="text-sm font-medium text-slate-400 dark:text-slate-500 max-w-[200px] leading-relaxed">
                                  Hiện tại chưa có tin tức nào mới. Bạn hãy quay lại sau nhé!
                               </p>
                             </div>
                           )}
                        </div>

                        {/* Detail View - Slide In Effect */}
                        <div className={`absolute inset-0 bg-white/60 dark:bg-slate-900/60 backdrop-blur-xl z-20 flex flex-col transition-all duration-300 ${selectedNotification ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'}`}>
                           {selectedNotification && (
                             <div className="flex flex-col h-full bg-white dark:bg-slate-900 shadow-2xl m-3 rounded-[2rem] overflow-hidden border border-white/50 dark:border-slate-700 ring-1 ring-black/5">
                                {/* Detail Header */}
                                <div className="p-4 flex items-center gap-3 border-b border-slate-100 dark:border-slate-800">
                                   <button 
                                     onClick={() => setSelectedNotification(null)} 
                                     className="w-10 h-10 rounded-full bg-slate-50 dark:bg-slate-800 text-slate-500 hover:bg-white hover:shadow-md transition-all flex items-center justify-center"
                                   >
                                     <i className="fa-solid fa-arrow-left"></i>
                                   </button>
                                   <span className="text-sm font-bold text-slate-500">Chi tiết thông báo</span>
                                </div>

                                <div className="flex-1 overflow-y-auto p-6 text-center">
                                   <div className={`w-24 h-24 mx-auto rounded-[2rem] flex items-center justify-center ${selectedNotification.bg} ${selectedNotification.color} shadow-lg shadow-pink-100/50 dark:shadow-none mb-6 transform -rotate-6 border-[6px] border-white dark:border-slate-800`}>
                                      <i className={`fa-solid ${selectedNotification.icon} text-4xl`}></i>
                                   </div>

                                   <h4 className="text-xl font-black text-slate-800 dark:text-white leading-tight mb-3">
                                      {selectedNotification.title}
                                   </h4>

                                   <div className="inline-flex items-center gap-2 bg-slate-100 dark:bg-slate-800 px-4 py-1.5 rounded-full text-xs font-bold text-slate-500 dark:text-slate-400 mb-6">
                                      <i className="fa-regular fa-clock"></i>
                                      {new Date(selectedNotification.time).toLocaleString('vi-VN', { dateStyle: 'full', timeStyle: 'short' })}
                                   </div>

                                   <div className="text-left bg-slate-50 dark:bg-slate-800/50 p-6 rounded-3xl border border-slate-100 dark:border-slate-700 relative">
                                     <i className="fa-solid fa-quote-left absolute -top-3 -left-2 text-4xl text-slate-200 dark:text-slate-700"></i>
                                     <p className="text-sm font-medium text-slate-600 dark:text-slate-300 leading-relaxed relative z-10">
