                                   cardStyle += "bg-white dark:bg-slate-800 border-white dark:border-slate-700 shadow-[0_4px_15px_-4px_rgba(236,72,153,0.15)] dark:shadow-none hover:border-pink-200 dark:hover:border-pink-800 hover:shadow-lg hover:shadow-pink-100/50 transform hover:-translate-y-0.5 z-10";
                                 } else {
                                   cardStyle += "bg-white/40 dark:bg-slate-800/40 border-transparent hover:bg-white dark:hover:bg-slate-700 hover:border-slate-100 dark:hover:border-slate-600";
                                 }

                                 return (
                                   <div key={notif.id} onClick={() => handleNotificationClick(notif)} className={cardStyle}>
                                      {/* Icon Box - Smaller */}
                                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${notif.bg} ${notif.color} shadow-sm border-2 border-white dark:border-slate-700 relative group-hover:rotate-6 transition-transform duration-300`}>
                                         <i className={`fa-solid ${notif.icon} text-base`}></i>

                                         {/* Unread/Status Badge */}
                                         {isScheduled ? (
                                             <span className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-amber-400 rounded-full border-2 border-white dark:border-slate-800 flex items-center justify-center shadow-sm" title="Chờ gửi">
                                                <i className="fa-solid fa-clock text-[7px] text-white"></i>
                                             </span>
                                         ) : !isRead && (
                                            <span className="absolute -top-1 -right-1 w-3 h-3 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800 animate-pulse"></span>
                                         )}
                                      </div>

                                      {/* Text Content */}
                                      <div className="flex-1 min-w-0 pt-0.5">
                                         <div className="flex justify-between items-start gap-1 mb-0.5">
                                            <h4 className={`text-xs leading-snug truncate ${!isRead && !isScheduled ? 'font-black text-slate-800 dark:text-white' : 'font-bold text-slate-600 dark:text-slate-300'}`}>
                                                {notif.title}
                                            </h4>
                                            <span className="text-[9px] font-bold text-slate-400 dark:text-slate-500 whitespace-nowrap bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded-md">
                                                {new Date(notif.time).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                                            </span>
                                         </div>
                                         <p className={`text-[11px] leading-relaxed line-clamp-2 ${!isRead ? 'text-slate-600 dark:text-slate-400 font-medium' : 'text-slate-500 dark:text-slate-500'}`}>
                                            {notif.desc}
                                         </p>
                                      </div>
                                   </div>
                                 );
                               })}

                               {/* Loading / End Indicators */}
                               {notifications.length > visibleNotifCount && (
                                  <div className="py-2 text-center">
                                      <div className="w-5 h-5 mx-auto rounded-full border-2 border-pink-200 border-t-pink-500 animate-spin bg-white dark:bg-slate-800"></div>
                                      <p className="text-[9px] font-bold text-slate-400 mt-1">Đang tải thêm...</p>
                                  </div>
                               )}

                               {notifications.length > 0 && notifications.length <= visibleNotifCount && (
                                  <div className="text-center py-4 opacity-50">
                                      <i className="fa-solid fa-check-circle text-lg text-slate-300 mb-1"></i>
                                      <p className="text-[10px] font-bold text-slate-400">Đã hết rồi nha</p>
                                  </div>
                               )}
                             </div>
                           ) : (
                             // Cute Empty State - Smaller
                             <div className="flex flex-col items-center justify-center h-full text-center px-6 pb-6">
                               <div className="relative mb-4">
                                  <div className="w-16 h-16 bg-gradient-to-tr from-indigo-50 to-pink-50 dark:from-slate-800 dark:to-slate-700 rounded-full flex items-center justify-center shadow-inner border-[4px] border-white dark:border-slate-800">
                                     <i className="fa-solid fa-box-open text-2xl text-slate-300 dark:text-slate-500"></i>
                                  </div>
                                  <div className="absolute -bottom-1 -right-1 text-lg animate-bounce delay-700">🍃</div>
                               </div>
                               <h4 className="text-sm font-black text-slate-700 dark:text-slate-300 mb-1">Hộp thư trống!</h4>
                               <p className="text-xs font-medium text-slate-400 dark:text-slate-500 max-w-[180px] leading-relaxed">
                                  Chưa có tin tức nào mới. Bạn quay lại sau nhé!
                               </p>
                             </div>
                           )}
