                             <div className="flex flex-col h-full">
                                {/* Detail Header */}
                                <div className="px-5 py-3 flex items-center gap-3 border-b border-slate-100/50 dark:border-slate-700/50 bg-slate-50/50 dark:bg-slate-800/30">
                                   <button 
                                     onClick={() => setSelectedNotification(null)} 
                                     className="w-8 h-8 rounded-full bg-white dark:bg-slate-700 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-600 hover:text-pink-500 transition-all flex items-center justify-center shadow-sm border border-slate-100 dark:border-slate-600"
                                   >
                                     <i className="fa-solid fa-arrow-left text-xs"></i>
                                   </button>
                                   <span className="text-xs font-bold text-slate-500">Chi tiết thông báo</span>
                                </div>

                                {/* Scrollable Content with Hover-Only Scrollbar */}
                                <div className={`flex-1 overflow-y-auto p-5 text-center
                                    [&::-webkit-scrollbar]:w-1.5 
                                    [&::-webkit-scrollbar-track]:bg-transparent 
                                    [&::-webkit-scrollbar-thumb]:bg-transparent 
                                    hover:[&::-webkit-scrollbar-thumb]:bg-slate-300 
                                    dark:hover:[&::-webkit-scrollbar-thumb]:bg-slate-600 
                                    [&::-webkit-scrollbar-thumb]:rounded-full
                                    transition-colors`}>

                                   <div className={`w-16 h-16 mx-auto rounded-[1.5rem] flex items-center justify-center ${selectedNotification.bg} ${selectedNotification.color} shadow-lg shadow-pink-100/50 dark:shadow-none mb-4 transform -rotate-6 border-[4px] border-white dark:border-slate-800`}>
                                      <i className={`fa-solid ${selectedNotification.icon} text-2xl`}></i>
