                                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${notif.bg} ${notif.color} shadow-sm border-2 border-white dark:border-slate-700 relative group-hover:rotate-6 transition-transform duration-300`}>
                                         <i className={`fa-solid ${notif.icon} text-base`}></i>

                                         {/* Unread/Status Badge */}
                                         {isScheduled ? (
                                             <span className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-amber-400 rounded-full border-2 border-white dark:border-slate-800 flex items-center justify-center shadow-sm" title="Chờ gửi">
                                                <i className="fa-solid fa-clock text-[7px] text-white"></i>
                                             </span>
                                         ) : !isRead && (
                                            <span className="absolute -top-1 -right-1 w-3 h-3 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800 animate-pulse"></span>
                                         )}
                                      </div>

                                      {/* Text Content */}
                                      <div className="flex-1 min-w-0 pt-0.5">
                                         <div className="flex justify-between items-start gap-1 mb-0.5">
                                            <h4 className={`text-xs leading-snug truncate ${!isRead && !isScheduled ? 'font-black text-slate-800 dark:text-white' : 'font-bold text-slate-600 dark:text-slate-300'}`}>
                                                {notif.title}
                                            </h4>
                                            <span className="text-[9px] font-bold text-slate-400 dark:text-slate-500 whitespace-nowrap bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded-md">
