                                            </span>
                                         </div>
                                         <p className={`text-[11px] leading-relaxed line-clamp-2 ${!isRead ? 'text-slate-600 dark:text-slate-400 font-medium' : 'text-slate-500 dark:text-slate-500'}`}>
                                            {notif.desc}
                                         </p>
                                      </div>
                                   </div>
                                 );
                               })}

                               {/* Loading / End Indicators */}
                               {notifications.length > visibleNotifCount && (
                                  <div className="py-2 text-center">
                                      <div className="w-5 h-5 mx-auto rounded-full border-2 border-pink-200 border-t-pink-500 animate-spin bg-white dark:bg-slate-800"></div>
                                      <p className="text-[9px] font-bold text-slate-400 mt-1">Đang tải thêm...</p>
                                  </div>
                               )}

