                                      <i className="fa-solid fa-check-circle text-lg text-slate-300 mb-1"></i>
                                      <p className="text-[10px] font-bold text-slate-400">Đã hết rồi nha</p>
                                  </div>
                               )}
                             </div>
                           ) : (
                             // Cute Empty State - Smaller
                             <div className="flex flex-col items-center justify-center h-full text-center px-6 pb-6">
                               <div className="relative mb-4">
                                  <div className="w-16 h-16 bg-gradient-to-tr from-indigo-50 to-pink-50 dark:from-slate-800 dark:to-slate-700 rounded-full flex items-center justify-center shadow-inner border-[4px] border-white dark:border-slate-800">
