  const content = fs.readFileSync(file.path, 'utf-8');
  const db = getDB();
  const newDoc = { id: Math.random().toString(36).substr(2, 9), userId, name: file.originalname, content: content, path: file.path, type: 'file', status: 'indexed', createdAt: Date.now() };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) fs.unlinkSync(doc.path);
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});
app.post('/api/chat', async (req, res) => {
  const { message, userId, botName } = req.body;
  const db = getDB();
  if (!process.env.API_KEY) return res.status(500).json({ error: "Missing API KEY" });
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const context = db.documents.filter((d: any) => d.userId === userId).map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
  const systemInstruction = `Bạn là trợ lý AI tên "${botName || 'BibiBot'}". Hãy sử dụng kiến thức sau để hỗ trợ khách hàng: ${context}`;
  try {
    const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: message, config: { systemInstruction } });
    const reply = response.text || "Tôi không thể trả lời.";
    if (!db.chatLogs) db.chatLogs = [];
    const newLog = { id: Math.random().toString(36).substr(2, 9), userId, customerSessionId: 'anon-session', query: message, answer: reply, timestamp: Date.now(), tokens: message.length + reply.length, isSolved: !reply.includes("không có thông tin") && !reply.includes("Xin lỗi") };
    db.chatLogs.push(newLog);
    saveDB(db);
    res.json({ text: reply });
  } catch (error) { res.status(500).json({ error: "AI Error" }); }
});

app.listen(PORT, () => {
  console.log(`SaaS Backend running at http://localhost:${PORT}`);
});

import { GoogleGenAI } from "@google/genai";
