  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    let logs: ChatLog[] = [];
    try {
        logs = await apiService.getChatLogs('all');
    } catch (e) {
        const db = getLocalDB();
        logs = db.chatLogs;
    }
    if (userId !== 'all') logs = logs.filter(l => l.userId === userId);

    const statsMap: Record<string, { queries: number, solved: number }> = {};
    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);
      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;
      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });
    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    try {
        const res = await fetch(`${API_URL}/chat-logs/${userId}`);
        if(!res.ok) throw new Error("Fetch logs failed");
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        let logs = db.chatLogs as ChatLog[];
        if (userId !== 'all') logs = logs.filter(l => l.userId === userId);
        return logs.sort((a, b) => b.timestamp - a.timestamp);
    }
  },

  // --- NOTIFICATIONS ---
  getNotifications: async (userId: string): Promise<Notification[]> => {
    try {
      const res = await fetch(`${API_URL}/notifications/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const now = Date.now();
      return (db.notifications || [])
        .filter((n: any) => {
          const isTargetUser = (n.userId === 'all' || n.userId === userId);
          if (!isTargetUser) return false;
          if (userId === 'admin') return true;
          return n.scheduledAt ? n.scheduledAt <= now : n.time <= now;
        })
        .map((n: any) => ({
            ...n,
            isRead: Array.isArray(n.readBy) ? n.readBy.includes(userId) : (n.isRead || false)
        }))
        .sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    }
  },

  markNotificationRead: async (id: string, userId: string): Promise<void> => {
    try {
      await fetch(`${API_URL}/notifications/${id}/read`, { 
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId })
      });
    } catch (e) {
      const db = getLocalDB();
      const n = db.notifications?.find((x: any) => x.id === id);
      if (n) {
        if (!n.readBy) n.readBy = [];
        if (!n.readBy.includes(userId)) n.readBy.push(userId);
        saveLocalDB(db);
      }
    }
  },

  markAllNotificationsRead: async (userId: string): Promise<void> => {
    try {
        await fetch(`${API_URL}/notifications/read-all`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ userId })
        });
    } catch (e) {
        const db = getLocalDB();
        const now = Date.now();
        db.notifications?.forEach((n: any) => {
            const isTargetUser = (n.userId === 'all' || n.userId === userId);
            const isVisible = userId === 'admin' ? true : (n.scheduledAt ? n.scheduledAt <= now : n.time <= now);
            if (isTargetUser && isVisible) {
                if (!n.readBy) n.readBy = [];
                if (!n.readBy.includes(userId)) n.readBy.push(userId);
            }
        });
        saveLocalDB(db);
    }
  },

  createSystemNotification: async (data: Partial<Notification>) => {
    try {
      await fetch(`${API_URL}/notifications/create`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(data)
      });
    } catch (e) {
      const db = getLocalDB();
      if (!db.notifications) db.notifications = [];
      const now = Date.now();
      db.notifications.push({
        id: Math.random().toString(36).substr(2, 9),
        userId: data.userId || 'all',
        title: data.title || '',
        desc: data.desc || '',
        time: data.scheduledAt || now, 
        scheduledAt: data.scheduledAt || now,
        readBy: [],
        icon: data.icon || 'fa-bell',
        color: data.color || 'text-blue-500',
        bg: data.bg || 'bg-blue-100'
      });
      saveLocalDB(db);
    }
  },

  suggestIcon: async (text: string): Promise<string> => {
    if (!process.env.API_KEY) return 'fa-bullhorn';
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Based on the following notification text, suggest the single most appropriate FontAwesome 6 icon class name. ONLY return the class name string. Text: "${text}"`;
    try {
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      const iconClass = response.text?.trim() || 'fa-bullhorn';
      return iconClass.replace(/['".]/g, '');
    } catch (error) { return 'fa-bullhorn'; }
  },

  chat: async (userId: string, message: string, botName: string): Promise<string> => {
    try {
      const res = await fetch(`${API_URL}/chat`, {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ userId, message, botName })
      });
      if(res.ok) {
         const data = await res.json();
         return data.text;
      }
    } catch (e) {}

    try {
      if (!process.env.API_KEY) return "Lỗi cấu hình: Thiếu API Key.";
      const db = getLocalDB();
      const docs = db.documents.filter((d: any) => d.userId === userId);
      const context = docs.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      const systemInstruction = `Bạn là trợ lý AI tên "${botName || 'BibiBot'}". Hãy sử dụng kiến thức sau để hỗ trợ khách hàng: ${context}`;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: message, config: { systemInstruction } });
      if (!db.chatLogs) db.chatLogs = [];
      db.chatLogs.push({ id: Math.random().toString(36).substr(2, 9), userId, customerSessionId: 'client-fallback', query: message, answer: response.text || '', timestamp: Date.now(), isSolved: true });
      saveLocalDB(db);
      return response.text || "Tôi không thể trả lời lúc này.";
    } catch (clientError) { return "Lỗi kết nối. Vui lòng thử lại sau."; }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { WidgetSettings, PluginConfig, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  setSettings: (s: WidgetSettings) => void;
  user: User;
}

const WidgetConfig: React.FC<Props> = ({ settings, setSettings, user }) => {
  const [activeTab, setActiveTab] = useState<'appearance' | 'plugins'>('appearance');

  // Plugin State Management (Internal here as it's part of config)
  const [plugins, setPlugins] = useState<PluginConfig>({
      autoOpen: { enabled: false, delay: 5 },
      social: { enabled: false, zalo: '', phone: '' },
      leadForm: { enabled: false, title: 'Để lại thông tin để được tư vấn nhé!', trigger: 'manual' }
  });
  const [isPluginsLoading, setIsPluginsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  // Preview Interactive States
  const [isPreviewOpen, setIsPreviewOpen] = useState(true);
  const [showPreviewForm, setShowPreviewForm] = useState(false);
  const [previewForm, setPreviewForm] = useState({ name: '', phone: '', email: '' });
  const [mockLeads, setMockLeads] = useState<any[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load Plugins on Mount
  useEffect(() => {
    const loadPlugins = async () => {
        const data = await apiService.getPlugins(user.id);
        setPlugins(data);
        setIsPluginsLoading(false);
        if(data.leadForm.trigger === 'on_open') setShowPreviewForm(true);
    };
    loadPlugins();
  }, [user.id]);

  const handleSave = async () => {
      setIsSaving(true);
      await new Promise(r => setTimeout(r, 800)); // Delay effect
      await apiService.updatePlugins(user.id, plugins);
      // Settings are usually saved instantly via props, but we can do a "Global Save" effect here
      setIsSaving(false);
  };

  const handleMockSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!previewForm.name || !previewForm.phone) return;

      // Save as TEST lead to DB
      await apiService.submitLead(user.id, previewForm.name, previewForm.phone, previewForm.email, true);

      const newMock = {
          id: Date.now().toString(),
          name: previewForm.name,
          phone: previewForm.phone,
          time: new Date().toLocaleTimeString('vi-VN')
      };

      setMockLeads(prev => [newMock, ...prev]);
      setPreviewForm({ name: '', phone: '', email: '' });
      setShowPreviewForm(false);
  };

  const resetPreview = () => {
      setIsPreviewOpen(false);
      setTimeout(() => setIsPreviewOpen(true), 100);
      setMockLeads([]);
      setShowPreviewForm(plugins.leadForm.trigger === 'on_open');
  };

  return (
    <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 pb-12 items-start">
      {/* Left Column: Configuration Panels */}
      <div className="space-y-6">
        <div className="flex justify-between items-end">
            <div>
                <h2 className="text-3xl font-black text-slate-800 dark:text-white mb-2 flex items-center gap-3">
                    <span className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-500 dark:text-indigo-300 rounded-2xl flex items-center justify-center text-xl shadow-sm -rotate-6 border-2 border-indigo-200 dark:border-indigo-800">
                    <i className="fa-solid fa-sliders"></i>
                    </span>
                    Cấu hình Widget
                </h2>
                <p className="text-slate-600 dark:text-slate-400 font-bold ml-1 text-base">Tùy chỉnh toàn diện mọi thứ tại đây.</p>
            </div>
            <button 
                onClick={handleSave} 
                disabled={isSaving}
                className="px-6 py-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-sm shadow-xl hover:-translate-y-1 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {isSaving ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <i className="fa-solid fa-floppy-disk"></i>}
