import React, { useState, useEffect } from 'react';
import { apiService } from '../services/apiService';
import { User, Lead } from '../types';

interface Props {
  user: User;
}

const Leads: React.FC<Props> = ({ user }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  useEffect(() => {
    loadLeads();
  }, [user.id]);

  const loadLeads = async () => {
    setIsLoading(true);
    await new Promise(r => setTimeout(r, 800)); // Cute delay
    const data = await apiService.getLeads(user.id);
    setLeads(data);
    setIsLoading(false);
  };

  const updateStatus = async (id: string, newStatus: string) => {
      // Optimistic update
      setLeads(prev => prev.map(l => l.id === id ? { ...l, status: newStatus as any } : l));
      await apiService.updateLeadStatus(id, newStatus);
  };

  const handleDelete = async (id: string) => {
      if(!window.confirm("Bạn có chắc chắn muốn xóa khách hàng này không?")) return;
      setDeletingId(id);
      await apiService.deleteLead(id);
      setLeads(prev => prev.filter(l => l.id !== id));
      setDeletingId(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex justify-between items-center bg-white dark:bg-slate-800 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-xl shadow-slate-200/50 dark:shadow-none">
        <div>
           <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3">
              <span className="w-12 h-12 bg-pink-100 dark:bg-pink-900/50 text-pink-500 dark:text-pink-300 rounded-2xl flex items-center justify-center text-xl shadow-sm rotate-3 border-2 border-pink-200">
                 <i className="fa-solid fa-address-book"></i>
              </span>
              Danh sách Khách hàng
           </h2>
           <p className="text-slate-500 dark:text-slate-400 font-bold ml-1 mt-1">
              Những người quan tâm đã để lại thông tin ({leads.length})
           </p>
        </div>
        <button onClick={loadLeads} className="w-10 h-10 rounded-full bg-slate-50 dark:bg-slate-700 flex items-center justify-center text-slate-400 hover:text-pink-500 transition-colors">
            <i className={`fa-solid fa-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-700 overflow-hidden p-2">
         <div className="overflow-x-auto">
            <table className="w-full text-left border-separate border-spacing-y-2 min-w-[800px]">
               <thead>
                  <tr className="bg-slate-50/50 dark:bg-slate-700/50">
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300 rounded-l-2xl pl-8">Họ tên</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300">Liên hệ</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300">Nguồn</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300">Thời gian</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300 text-right">Trạng thái</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300 rounded-r-2xl pr-8 text-right">Thao tác</th>
                  </tr>
               </thead>
               <tbody className="space-y-2">
                  {leads.map(lead => (
                     <tr key={lead.id} className="bg-slate-50 dark:bg-slate-700/30 hover:bg-pink-50 dark:hover:bg-slate-700 transition-colors group">
                        <td className="px-6 py-5 rounded-l-2xl pl-8 font-bold text-slate-800 dark:text-white border-b border-transparent">
                           <div className="flex items-center gap-3">
                              <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-pink-400 to-rose-400 text-white flex items-center justify-center font-bold text-sm shadow-md">
                                 {lead.name.charAt(0).toUpperCase()}
                              </div>
                              <div className="flex flex-col">
                                  <span>{lead.name}</span>
                                  {lead.isTest && <span className="text-[9px] font-bold bg-amber-100 text-amber-600 px-1.5 py-0.5 rounded w-fit mt-0.5">TEST DATA</span>}
                              </div>
                           </div>
                        </td>
                        <td className="px-6 py-5 border-b border-transparent">
                           <div className="flex flex-col gap-1">
                              <span className="text-sm font-bold text-slate-700 dark:text-slate-200"><i className="fa-solid fa-phone text-xs text-slate-400 mr-1.5"></i>{lead.phone}</span>
                              {lead.email && <span className="text-xs font-bold text-slate-500"><i className="fa-solid fa-envelope text-xs text-slate-400 mr-1.5"></i>{lead.email}</span>}
                           </div>
                        </td>
                        <td className="px-6 py-5 border-b border-transparent">
                           <span className="text-xs font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 px-2 py-1 rounded-lg text-slate-500 uppercase tracking-wider">
                              {lead.source}
                           </span>
                        </td>
                        <td className="px-6 py-5 border-b border-transparent text-sm font-bold text-slate-500">
                           {new Date(lead.createdAt).toLocaleString('vi-VN')}
                        </td>
                        <td className="px-6 py-5 text-right border-b border-transparent">
                           <select 
                              value={lead.status}
                              onChange={(e) => updateStatus(lead.id, e.target.value)}
                              className={`text-xs font-bold px-3 py-1.5 rounded-full border-2 outline-none cursor-pointer ${
                                 lead.status === 'new' ? 'bg-blue-50 border-blue-200 text-blue-600' :
                                 lead.status === 'contacted' ? 'bg-amber-50 border-amber-200 text-amber-600' :
                                 'bg-emerald-50 border-emerald-200 text-emerald-600'
                              }`}
                           >
                              <option value="new">Mới tinh</option>
                              <option value="contacted">Đang chat</option>
                              <option value="converted">Chốt đơn</option>
                           </select>
                        </td>
                        <td className="px-6 py-5 rounded-r-2xl pr-8 text-right border-b border-transparent">
                            <button 
                                onClick={() => handleDelete(lead.id)}
                                disabled={deletingId === lead.id}
                                className="w-8 h-8 rounded-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 flex items-center justify-center text-slate-400 hover:text-rose-500 hover:border-rose-200 transition-all shadow-sm"
                                title="Xóa khách hàng"
                            >
                                {deletingId === lead.id ? <i className="fa-solid fa-circle-notch animate-spin text-xs"></i> : <i className="fa-solid fa-trash-can text-xs"></i>}
                            </button>
                        </td>
                     </tr>
                  ))}
                  {leads.length === 0 && !isLoading && (
                     <tr>
                        <td colSpan={6} className="px-8 py-24 text-center">
                           <div className="flex flex-col items-center">
                              <div className="w-20 h-20 bg-slate-100 dark:bg-slate-700/50 rounded-full flex items-center justify-center text-slate-300 dark:text-slate-600 mb-4">
                                 <i className="fa-solid fa-folder-open text-3xl"></i>
                              </div>
                              <p className="font-bold text-slate-500">Chưa có khách hàng nào để lại thông tin.</p>
                           </div>
                        </td>
                     </tr>
                  )}
               </tbody>
            </table>
         </div>
      </div>
    </div>
  );
};

