import React, { useState, useEffect, useRef } from 'react';
import { apiService } from '../services/apiService';
import { User, Lead } from '../types';

interface Props {
  user: User;
}

const Leads: React.FC<Props> = ({ user }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Custom Dropdown State
  const [openDropdownId, setOpenDropdownId] = useState<string | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadLeads();

    // Click outside to close dropdown
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setOpenDropdownId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [user.id]);

  const loadLeads = async () => {
    setIsLoading(true);
    await new Promise(r => setTimeout(r, 1000)); // Cute delay for skeleton effect
    const data = await apiService.getLeads(user.id);
    setLeads(data);
    setIsLoading(false);
  };

  const updateStatus = async (id: string, newStatus: string) => {
      // Optimistic update
      setLeads(prev => prev.map(l => l.id === id ? { ...l, status: newStatus as any } : l));
      setOpenDropdownId(null);
      await apiService.updateLeadStatus(id, newStatus);
  };

  const handleDelete = async (id: string) => {
      if(!window.confirm("Bạn có chắc chắn muốn xóa khách hàng này không?")) return;
      setDeletingId(id);
      await apiService.deleteLead(id);
      setLeads(prev => prev.filter(l => l.id !== id));
      setDeletingId(null);
  };

  const getStatusBadge = (status: string) => {
      switch(status) {
          case 'new': return { label: 'Mới tinh', color: 'bg-blue-50 text-blue-600 border-blue-200', icon: 'fa-star' };
          case 'contacted': return { label: 'Đang chat', color: 'bg-amber-50 text-amber-600 border-amber-200', icon: 'fa-comments' };
          case 'converted': return { label: 'Chốt đơn', color: 'bg-emerald-50 text-emerald-600 border-emerald-200', icon: 'fa-check-circle' };
          default: return { label: 'Khác', color: 'bg-slate-50 text-slate-600 border-slate-200', icon: 'fa-circle' };
      }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12" ref={dropdownRef}>
      <div className="flex justify-between items-center bg-white dark:bg-slate-800 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-xl shadow-slate-200/50 dark:shadow-none">
        <div>
           <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3">
              <span className="w-12 h-12 bg-pink-100 dark:bg-pink-900/50 text-pink-500 dark:text-pink-300 rounded-2xl flex items-center justify-center text-xl shadow-sm rotate-3 border-2 border-pink-200">
                 <i className="fa-solid fa-address-book"></i>
              </span>
              Danh sách Khách hàng
           </h2>
           <p className="text-slate-500 dark:text-slate-400 font-bold ml-1 mt-1">
              Những người quan tâm đã để lại thông tin ({leads.length})
           </p>
        </div>
        <button onClick={loadLeads} className="w-10 h-10 rounded-full bg-slate-50 dark:bg-slate-700 flex items-center justify-center text-slate-400 hover:text-pink-500 transition-colors">
            <i className={`fa-solid fa-rotate ${isLoading ? 'animate-spin' : ''}`}></i>
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-700 overflow-hidden p-2">
         <div className="overflow-x-auto min-h-[300px]">
            <table className="w-full text-left border-separate border-spacing-y-2 min-w-[800px]">
               <thead>
                  <tr className="bg-slate-50/50 dark:bg-slate-700/50">
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300 rounded-l-2xl pl-8">Họ tên</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300">Liên hệ</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300">Nguồn</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300">Thời gian</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300 text-left">Trạng thái</th>
                     <th className="px-6 py-5 text-sm font-black text-slate-600 dark:text-slate-300 rounded-r-2xl pr-8 text-left">Thao tác</th>
                  </tr>
               </thead>
