                                    <span className="text-sm font-bold text-slate-700 dark:text-slate-200"><i className="fa-solid fa-phone text-xs text-slate-400 mr-1.5"></i>{lead.phone}</span>
                                    {lead.email && <span className="text-xs font-bold text-slate-500"><i className="fa-solid fa-envelope text-xs text-slate-400 mr-1.5"></i>{lead.email}</span>}
                                </div>
                                </td>
                                <td className="px-6 py-5 border-b border-transparent">
                                <span className="text-xs font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 px-2 py-1 rounded-lg text-slate-500 uppercase tracking-wider">
                                    {lead.source}
                                </span>
                                </td>
                                <td className="px-6 py-5 border-b border-transparent text-sm font-bold text-slate-500">
                                {new Date(lead.createdAt).toLocaleString('vi-VN')}
                                </td>
                                <td className="px-6 py-5 text-left border-b border-transparent relative">
                                    {/* Cute Custom Dropdown */}
                                    <div className="relative">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setOpenDropdownId(openDropdownId === lead.id ? null : lead.id); }}
                                            className={`flex items-center gap-2 px-3 py-1.5 rounded-full border-2 text-xs font-bold transition-all active:scale-95 ${statusStyle.color}`}
                                        >
                                            <i className={`fa-solid ${statusStyle.icon}`}></i>
                                            {statusStyle.label}
                                            <i className="fa-solid fa-chevron-down text-[10px] ml-1 opacity-60"></i>
                                        </button>

                                        {openDropdownId === lead.id && (
                                            <div className="absolute top-full left-0 mt-2 w-40 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border-2 border-slate-100 dark:border-slate-600 z-50 overflow-hidden animate-in fade-in zoom-in duration-200">
                                                <button onClick={() => updateStatus(lead.id, 'new')} className="w-full text-left px-4 py-3 text-xs font-bold text-blue-600 hover:bg-blue-50 dark:hover:bg-slate-700 flex items-center gap-2">
                                                    <i className="fa-solid fa-star w-4"></i> Mới tinh
                                                </button>
                                                <button onClick={() => updateStatus(lead.id, 'contacted')} className="w-full text-left px-4 py-3 text-xs font-bold text-amber-600 hover:bg-amber-50 dark:hover:bg-slate-700 flex items-center gap-2 border-t border-slate-50 dark:border-slate-700">
                                                    <i className="fa-solid fa-comments w-4"></i> Đang chat
                                                </button>
                                                <button onClick={() => updateStatus(lead.id, 'converted')} className="w-full text-left px-4 py-3 text-xs font-bold text-emerald-600 hover:bg-emerald-50 dark:hover:bg-slate-700 flex items-center gap-2 border-t border-slate-50 dark:border-slate-700">
                                                    <i className="fa-solid fa-check-circle w-4"></i> Chốt đơn
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-5 rounded-r-2xl pr-8 text-left border-b border-transparent">
                                    <button 
                                        onClick={() => handleDelete(lead.id)}
                                        disabled={deletingId === lead.id}
                                        className="w-9 h-9 rounded-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 flex items-center justify-center text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 hover:border-rose-200 transition-all shadow-sm active:scale-90"
                                        title="Xóa khách hàng"
                                    >
                                        {deletingId === lead.id ? <i className="fa-solid fa-circle-notch animate-spin text-xs"></i> : <i className="fa-solid fa-trash-can text-sm"></i>}
                                    </button>
                                </td>
                            </tr>
                         );
                      })
                  )}
               </tbody>
            </table>
         </div>
      </div>
    </div>
  );
};

