                         {/* Lead Form Preview */}
                         {plugins.leadForm.enabled && showPreviewForm && (
                             <div className="bg-white p-3 rounded-2xl border border-slate-100 shadow-md animate-in zoom-in duration-300 relative z-10">
                                 <div className="flex justify-between items-start mb-2">
                                     <div className="flex items-center gap-2">
                                         <div className="w-6 h-6 bg-pink-100 text-pink-500 rounded-full flex items-center justify-center text-xs"><i className="fa-solid fa-address-card"></i></div>
