                                 <form onSubmit={handleMockSubmit} className="space-y-2">
                                     <input required type="text" placeholder="Tên..." value={previewForm.name} onChange={e => setPreviewForm({...previewForm, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-medium focus:border-pink-400 outline-none" />
                                     <input required type="tel" placeholder="SĐT..." value={previewForm.phone} onChange={e => setPreviewForm({...previewForm, phone: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-medium focus:border-pink-400 outline-none" />
                                     <input type="email" placeholder="Email..." value={previewForm.email} onChange={e => setPreviewForm({...previewForm, email: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-medium focus:border-pink-400 outline-none" />
                                     <button type="submit" className="w-full py-2 bg-pink-500 hover:bg-pink-600 text-white rounded-lg text-xs font-bold transition-colors">Gửi thông tin</button>
                                 </form>
                             </div>
                         )}

                         {/* Success Message Mock */}
                         {mockLeads.map((lead, idx) => (
                             <div key={idx} className="space-y-2 animate-in slide-in-from-bottom-2 fade-in">
                                 <div className="flex justify-end">
                                     <div className="bg-indigo-600 text-white p-3 rounded-2xl rounded-tr-none text-xs font-medium shadow-sm max-w-[85%]" style={{backgroundColor: settings.primaryColor}}>
                                         Đã gửi thông tin: {lead.name} - {lead.phone}
                                     </div>
                                 </div>
                                 <div className="flex justify-start">
                                     <div className="bg-white text-slate-700 border border-slate-100 p-3 rounded-2xl rounded-tl-none text-xs font-medium shadow-sm max-w-[85%]">
                                         Cảm ơn bạn! Chúng mình sẽ liên hệ sớm nha.
                                     </div>
                                 </div>
                             </div>
                         ))}
                         <div ref={messagesEndRef} />
                     </div>

                     {/* Footer */}
                     <div className="p-3 bg-white border-t border-slate-100 relative">
                         {plugins.leadForm.enabled && plugins.leadForm.trigger === 'manual' && !showPreviewForm && (
                             <button onClick={() => setShowPreviewForm(true)} className="absolute -top-8 left-1/2 -translate-x-1/2 bg-white border border-pink-200 text-pink-500 px-3 py-1 rounded-full text-[10px] font-bold shadow-sm whitespace-nowrap hover:bg-pink-50 transition-colors">
                                 <i className="fa-regular fa-hand-point-up mr-1"></i> Để lại SĐT
                             </button>
                         )}
                         <div className="flex gap-2">
                             <input className="flex-1 bg-slate-100 rounded-full px-3 py-2 text-xs" disabled placeholder="Nhập tin nhắn..." />
                             <div className="w-8 h-8 rounded-full flex items-center justify-center text-white shadow-sm" style={{ backgroundColor: settings.primaryColor }}><i className="fa-solid fa-paper-plane text-xs"></i></div>
                         </div>
                     </div>
                 </div>
             )}
         </div>
      </div>
    </div>
  );
};

