import React, { useState, useEffect, useRef } from 'react';
import { WidgetSettings, PluginConfig, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  setSettings: (s: WidgetSettings) => void;
  user: User;
  onConfigSave?: () => void; // New prop for triggering parent refresh
}

const WidgetConfig: React.FC<Props> = ({ settings, setSettings, user, onConfigSave }) => {
  const [activeTab, setActiveTab] = useState<'appearance' | 'plugins'>('appearance');

  // Plugin State Management (Internal here as it's part of config)
  const [plugins, setPlugins] = useState<PluginConfig>({
      autoOpen: { enabled: false, delay: 5 },
      social: { enabled: false, zalo: '', phone: '' },
      leadForm: { enabled: false, title: 'Để lại thông tin để được tư vấn nhé!', trigger: 'manual' }
  });
  const [isPluginsLoading, setIsPluginsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  // Preview Interactive States
  const [isPreviewOpen, setIsPreviewOpen] = useState(true);
  const [showPreviewForm, setShowPreviewForm] = useState(false);
  const [previewForm, setPreviewForm] = useState({ name: '', phone: '', email: '' });
  const [mockLeads, setMockLeads] = useState<any[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load Plugins on Mount
  useEffect(() => {
    const loadPlugins = async () => {
        const data = await apiService.getPlugins(user.id);
        setPlugins(data);
        setIsPluginsLoading(false);
        if(data.leadForm.trigger === 'on_open') setShowPreviewForm(true);
    };
    loadPlugins();
  }, [user.id]);

  const handleSave = async () => {
      setIsSaving(true);
      await new Promise(r => setTimeout(r, 800)); // Delay effect
      await apiService.updatePlugins(user.id, plugins);
      // Settings are usually saved instantly via props, but we can do a "Global Save" effect here
      setIsSaving(false);

      // Trigger parent to refresh the actual ChatWidget
      if (onConfigSave) onConfigSave();
  };

  const handleMockSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!previewForm.name || !previewForm.phone) return;

      // Save as TEST lead to DB
      await apiService.submitLead(user.id, previewForm.name, previewForm.phone, previewForm.email, true);

      const newMock = {
          id: Date.now().toString(),
          name: previewForm.name,
          phone: previewForm.phone,
          time: new Date().toLocaleTimeString('vi-VN')
      };

      setMockLeads(prev => [newMock, ...prev]);
      setPreviewForm({ name: '', phone: '', email: '' });
      setShowPreviewForm(false);
  };

  const resetPreview = () => {
      setIsPreviewOpen(false);
      setTimeout(() => setIsPreviewOpen(true), 100);
      setMockLeads([]);
      setShowPreviewForm(plugins.leadForm.trigger === 'on_open');
  };

  return (
    <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 pb-12 items-start">
      {/* Left Column: Configuration Panels */}
      <div className="space-y-6">
        <div className="flex justify-between items-end">
            <div>
                <h2 className="text-3xl font-black text-slate-800 dark:text-white mb-2 flex items-center gap-3">
                    <span className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-500 dark:text-indigo-300 rounded-2xl flex items-center justify-center text-xl shadow-sm -rotate-6 border-2 border-indigo-200 dark:border-indigo-800">
                    <i className="fa-solid fa-sliders"></i>
                    </span>
                    Cấu hình Widget
                </h2>
                <p className="text-slate-600 dark:text-slate-400 font-bold ml-1 text-base">Tùy chỉnh toàn diện mọi thứ tại đây.</p>
            </div>
            <button 
                onClick={handleSave} 
                disabled={isSaving}
                className="px-6 py-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-sm shadow-xl hover:-translate-y-1 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {isSaving ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <i className="fa-solid fa-floppy-disk"></i>}
                Lưu cài đặt
            </button>
        </div>

        {/* Tabs */}
        <div className="bg-slate-100 dark:bg-slate-700/50 p-1.5 rounded-2xl flex font-bold text-sm">
            <button 
                onClick={() => setActiveTab('appearance')}
                className={`flex-1 py-3 rounded-xl transition-all flex items-center justify-center gap-2 ${activeTab === 'appearance' ? 'bg-white dark:bg-slate-600 shadow-sm text-indigo-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
            >
                <i className="fa-solid fa-paint-roller"></i> Giao diện
            </button>
            <button 
                onClick={() => setActiveTab('plugins')}
                className={`flex-1 py-3 rounded-xl transition-all flex items-center justify-center gap-2 ${activeTab === 'plugins' ? 'bg-white dark:bg-slate-600 shadow-sm text-pink-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
            >
                <i className="fa-solid fa-puzzle-piece"></i> Tiện ích
            </button>
        </div>

        {/* Tab Content: Appearance */}
        {activeTab === 'appearance' && (
            <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border-2 border-slate-100 dark:border-slate-700 space-y-8 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="space-y-4">
                    <label className="block text-xs font-extrabold text-slate-500 dark:text-slate-400 uppercase ml-1">Màu sắc chủ đạo</label>
                    <div className="flex flex-wrap gap-4">
                    {['#6366f1', '#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#1e293b'].map(color => (
                        <button 
                        key={color}
                        onClick={() => setSettings({ ...settings, primaryColor: color })}
                        className={`w-14 h-14 rounded-full border-4 transition-all shadow-sm flex items-center justify-center ${settings.primaryColor === color ? 'border-slate-200 dark:border-slate-600 scale-110 shadow-lg ring-4 ring-offset-2 ring-indigo-200 dark:ring-indigo-900' : 'border-white dark:border-slate-700 hover:scale-105'}`}
                        style={{ backgroundColor: color }}
                        >
                        {settings.primaryColor === color && <i className="fa-solid fa-check text-white text-xl"></i>}
                        </button>
                    ))}
                    </div>
                </div>

                <div className="space-y-4">
                    <label className="block text-xs font-extrabold text-slate-500 dark:text-slate-400 uppercase ml-1">Thông tin Bot</label>
                    <div className="grid grid-cols-1 gap-4">
                        <div className="relative">
                            <i className="fa-solid fa-tag absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500"></i>
                            <input 
                                type="text"
                                placeholder="Tên Bot (VD: Trợ lý ảo)"
                                value={settings.botName}
                                onChange={(e) => setSettings({ ...settings, botName: e.target.value })}
                                className="w-full pl-12 pr-5 py-4 bg-slate-50 dark:bg-slate-900/50 border-2 border-slate-200 dark:border-slate-600 rounded-2xl focus:outline-none focus:border-indigo-500 font-bold text-slate-800 dark:text-white transition-all"
                            />
                        </div>
                        <textarea 
                            value={settings.welcomeMessage}
