import React, { useState, useEffect, useRef } from 'react';
import { apiService } from '../services/apiService';
import { ChatLog, User } from '../types';

interface Props {
  user: User;
}

const ChatHistory: React.FC<Props> = ({ user }) => {
  const isMaster = user.role === 'master';
  const [logs, setLogs] = useState<ChatLog[]>([]);
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUserFilter, setSelectedUserFilter] = useState<string>('all');
  const [selectedLog, setSelectedLog] = useState<ChatLog | null>(null);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    loadData();
  }, [user.id]);

  const loadData = async () => {
    setIsLoading(true);
    try {
      await new Promise(r => setTimeout(r, 800)); // Cute delay
      if (isMaster) {
        const allUsers = await apiService.getAllUsers();
        // Lọc bỏ tài khoản admin/master khỏi danh sách
        setCustomers(allUsers.filter(u => u.role !== 'master'));
        const allLogs = await apiService.getChatLogs('all');
        setLogs(allLogs);
      } else {
        const myLogs = await apiService.getChatLogs(user.id);
        setLogs(myLogs);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredLogs = logs.filter(log => {
    if (selectedUserFilter === 'all') return true;
    return log.userId === selectedUserFilter;
  });

  const getCustomerEmail = (userId: string) => {
    return customers.find(c => c.id === userId)?.email || 'Khách ẩn danh';
  };

  const getFilterLabel = () => {
     if (selectedUserFilter === 'all') return 'Tất cả khách hàng';
     const found = customers.find(c => c.id === selectedUserFilter);
     return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-700 shadow-lg shadow-slate-200/50 dark:shadow-none">
        <div>
          <h2 className="text-xl font-black text-slate-800 dark:text-white flex items-center">
            <span className="w-10 h-10 rounded-2xl bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 flex items-center justify-center mr-3 text-lg shadow-sm border-2 border-indigo-200 dark:border-indigo-800 rotate-3">
               <i className="fa-solid fa-clock-rotate-left"></i>
            </span>
            Lịch sử Trò chuyện
          </h2>
        </div>

        {isMaster && (
          <div className="w-full sm:w-auto relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full sm:w-64 flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-700 border-2 border-slate-200 dark:border-slate-600 rounded-2xl text-sm font-bold hover:border-indigo-400 transition-all text-slate-600 dark:text-slate-200 shadow-sm"
              >
                <span className="truncate">{getFilterLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-slate-400 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
            </button>

            {isDropdownOpen && (
                <div className="absolute top-full right-0 w-full sm:w-64 mt-2 bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 rounded-2xl shadow-2xl z-50 max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200">
                  <div 
                    onClick={() => { setSelectedUserFilter('all'); setIsDropdownOpen(false); }}
                    className={`px-4 py-3 text-sm font-bold cursor-pointer hover:bg-indigo-50 dark:hover:bg-slate-600 hover:text-indigo-600 dark:hover:text-indigo-300 ${selectedUserFilter === 'all' ? 'bg-indigo-50 dark:bg-slate-600 text-indigo-600 dark:text-indigo-300' : 'text-slate-600 dark:text-slate-300'}`}
                  >
                    Tất cả khách hàng
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUserFilter(c.id); setIsDropdownOpen(false); }}
                      className={`px-4 py-3 text-sm font-bold cursor-pointer hover:bg-indigo-50 dark:hover:bg-slate-600 hover:text-indigo-600 dark:hover:text-indigo-300 border-t border-slate-50 dark:border-slate-600 ${selectedUserFilter === c.id ? 'bg-indigo-50 dark:bg-slate-600 text-indigo-600 dark:text-indigo-300' : 'text-slate-600 dark:text-slate-300'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* List Column - Cute Style */}
        <div className={`lg:col-span-1 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/40 dark:shadow-none border-2 border-slate-100 dark:border-slate-700 overflow-hidden flex flex-col h-[650px] ${selectedLog ? 'hidden lg:flex' : 'flex'}`}>
          <div className="p-5 border-b-2 border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-700/30 backdrop-blur-sm">
             <h3 className="font-black text-slate-700 dark:text-slate-300 text-sm uppercase tracking-wide flex items-center gap-2">
                <i className="fa-solid fa-list-ul text-indigo-400"></i>
                Danh sách hội thoại ({filteredLogs.length})
             </h3>
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-3 scroll-smooth">
            {isLoading ? (
               <div className="flex flex-col items-center justify-center h-full p-4">
                  <div className="w-16 h-16 bg-indigo-50 dark:bg-indigo-900/30 rounded-full flex items-center justify-center animate-bounce mb-3 border-4 border-white dark:border-slate-800 shadow-sm">
                     <i className="fa-regular fa-comment-dots text-indigo-500 text-2xl"></i>
                  </div>
                  <p className="text-xs font-bold text-slate-400 animate-pulse">Đang tải tin nhắn...</p>
               </div>
            ) : filteredLogs.length > 0 ? (
              filteredLogs.map(log => {
                const isSelected = selectedLog?.id === log.id;
                return (
                  <div 
                    key={log.id}
                    onClick={() => setSelectedLog(log)}
                    className={`relative p-4 rounded-[1.5rem] cursor-pointer transition-all duration-300 group border-2 ${
                      isSelected
                      ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-200 dark:border-indigo-800 shadow-inner scale-[0.98]' 
                      : 'bg-white dark:bg-slate-800 border-transparent hover:border-slate-200 dark:hover:border-slate-600 hover:shadow-lg hover:-translate-y-1'
                    }`}
                  >
