                                            <span className="text-[10px] font-black bg-amber-100 text-amber-600 border border-amber-200 px-3 py-1.5 rounded-full whitespace-nowrap shadow-sm">
                                                <i className="fa-solid fa-flask mr-1.5"></i> Dữ liệu Test
                                            </span>
                                        ) : (
                                            <span className="text-[10px] font-black bg-emerald-100 text-emerald-600 border border-emerald-200 px-3 py-1.5 rounded-full whitespace-nowrap shadow-sm">
                                                <i className="fa-solid fa-globe mr-1.5"></i> Dữ liệu Thật
                                            </span>
                                        )}
                                        <button 
                                            type="button"
                                            onClick={(e) => handleDeleteClick(e, lead.id)}
                                            className={`h-9 shrink-0 rounded-full flex items-center justify-center transition-all shadow-sm active:scale-90 font-bold text-xs border ${
                                                isConfirming 
                                                ? 'w-auto px-3 bg-red-500 text-white border-red-600 hover:bg-red-600 animate-pulse' 
                                                : 'w-9 bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 hover:border-rose-200'
