export default ChatHistory;

import React, { useState, useRef, useEffect } from 'react';
import { WidgetSettings, Message, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  userId: string;
}

const ChatWidget: React.FC<Props> = ({ settings, userId }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: settings.welcomeMessage, timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [sessionId, setSessionId] = useState('');

  // Plugin States
  const [plugins, setPlugins] = useState<any>(null);
  const [showLeadForm, setShowLeadForm] = useState(false);
  const [leadForm, setLeadForm] = useState({ name: '', phone: '', email: '' });
  const [leadSubmitted, setLeadSubmitted] = useState(false);

  // Initialize Session ID & Fetch Plugins
  useEffect(() => {
    // 1. Session Logic
    let storedSessionId = localStorage.getItem('bibichat_session_id');
    if (!storedSessionId) {
        storedSessionId = Math.random().toString(36).substring(2) + Date.now().toString(36);
        localStorage.setItem('bibichat_session_id', storedSessionId);
    }
    setSessionId(storedSessionId);

    // 2. Plugins Logic
    const fetchPlugins = async () => {
        const p = await apiService.getPlugins(userId);
        setPlugins(p);

        // Auto Open Logic
        if (p.autoOpen?.enabled) {
            setTimeout(() => setIsOpen(true), p.autoOpen.delay * 1000);
        }
    };
    fetchPlugins();
  }, [userId]);

  // Effect to scroll bottom
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading, showLeadForm]);

  useEffect(() => {
    if (messages.length === 1 && messages[0].id === '1') {
      setMessages([{ ...messages[0], text: settings.welcomeMessage }]);
    }
  }, [settings.welcomeMessage]);

  // Handle Auto-show Lead Form when opened
  useEffect(() => {
      if (isOpen && plugins?.leadForm?.enabled && plugins?.leadForm?.trigger === 'on_open' && !leadSubmitted && !showLeadForm) {
          setShowLeadForm(true);
      }
  }, [isOpen, plugins]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      // Pass sessionId to the API
      const responseText = await apiService.chat(userId, input, settings.botName, sessionId);
      const botMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: responseText, timestamp: Date.now() };
      setMessages(prev => [...prev, botMsg]);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Hệ thống đang bận. Vui lòng thử lại sau.", timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  const submitLead = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!leadForm.name || !leadForm.phone) return;
      await apiService.submitLead(userId, leadForm.name, leadForm.phone, leadForm.email);
      setLeadSubmitted(true);
      setShowLeadForm(false);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: "Cảm ơn bạn! Chúng mình sẽ liên hệ sớm nha.", timestamp: Date.now() }]);
  };

  return (
    <div className={`fixed bottom-6 ${settings.position === 'right' ? 'right-6' : 'left-6'} z-[9999] font-sans`}>
      <button 
        onClick={() => setIsOpen(!isOpen)} 
        className="w-16 h-16 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl transition-all hover:scale-110 active:scale-95 duration-300 relative group" 
        style={{ backgroundColor: settings.primaryColor }}
      >
        <span className="absolute inset-0 rounded-full bg-white opacity-20 group-hover:animate-ping"></span>
        {isOpen ? <i className="fa-solid fa-xmark"></i> : <i className="fa-solid fa-comment-dots"></i>}
      </button>

      {isOpen && (
        <div className={`absolute bottom-24 ${settings.position === 'right' ? 'right-0' : 'left-0'} w-[calc(100vw-3rem)] sm:w-[380px] h-[550px] bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in slide-in-from-bottom-10 duration-300 border border-slate-100/50`}>
          {/* Header */}
          <div className="p-4 text-white relative overflow-hidden shrink-0" style={{ backgroundColor: settings.primaryColor }}>
            <div className="absolute top-0 right-0 p-4 opacity-10">
               <i className="fa-solid fa-robot text-6xl"></i>
            </div>

            <div className="flex justify-between items-center relative z-10">
                <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center border-2 border-white/30 backdrop-blur-sm">
                        <i className="fa-solid fa-robot text-lg"></i>
                    </div>
                    <div>
                        <h3 className="font-bold text-base">{settings.botName}</h3>
                        <div className="flex items-center text-[10px] opacity-90 font-medium bg-white/20 px-2 py-0.5 rounded-full w-fit mt-0.5">
                        <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full mr-1.5 animate-pulse"></span>
                        Trực tuyến
                        </div>
                    </div>
                </div>

                {/* Social Plugin Icons */}
                {plugins?.social?.enabled && (
                    <div className="flex gap-2">
                         {plugins.social.phone && (
                             <a href={`tel:${plugins.social.phone}`} className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/40 flex items-center justify-center transition-colors border border-white/20" title="Gọi Hotline">
                                 <i className="fa-solid fa-phone text-xs"></i>
                             </a>
                         )}
                         {plugins.social.zalo && (
                             <a href={`https://zalo.me/${plugins.social.zalo}`} target="_blank" rel="noreferrer" className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/40 flex items-center justify-center transition-colors border border-white/20" title="Chat Zalo">
                                 <div className="font-bold text-[8px]">Zalo</div>
                             </a>
                         )}
                    </div>
                )}
            </div>
          </div>

          {/* Messages Area */}
          <div ref={scrollRef} className="flex-1 p-5 bg-slate-50 space-y-4 overflow-y-auto relative">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-3 text-sm font-medium shadow-sm leading-relaxed ${
                  msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-2xl rounded-tr-none' 
                  : 'bg-white text-slate-800 border border-slate-100 rounded-2xl rounded-tl-none'
                }`} style={msg.role === 'user' ? { backgroundColor: settings.primaryColor } : {}}>
                  <p className="whitespace-pre-wrap">{msg.text}</p>
                </div>
              </div>
            ))}

            {/* Lead Form Plugin (Inline) */}
            {showLeadForm && (
                <div className="mx-4 my-4 bg-white p-5 rounded-2xl shadow-lg border-2 border-slate-100 animate-in zoom-in duration-300 relative z-10">
                     <button onClick={() => setShowLeadForm(false)} className="absolute top-2 right-2 text-slate-400 hover:text-rose-500 p-1"><i className="fa-solid fa-xmark"></i></button>
                     <div className="text-center mb-4">
                        <div className="w-12 h-12 bg-pink-100 text-pink-500 rounded-full flex items-center justify-center mx-auto mb-2 text-xl">
                            <i className="fa-solid fa-address-card"></i>
                        </div>
                        <h4 className="font-bold text-slate-800 text-sm">{plugins.leadForm.title || "Vui lòng để lại thông tin"}</h4>
                     </div>
                     <form onSubmit={submitLead} className="space-y-3">
                         <input 
                            required 
                            type="text" 
                            placeholder="Tên của bạn *" 
                            className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:border-pink-400 font-bold"
                            value={leadForm.name}
                            onChange={e => setLeadForm({...leadForm, name: e.target.value})}
                         />
                         <input 
                            required 
                            type="tel" 
                            placeholder="Số điện thoại *" 
                            className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:border-pink-400 font-bold"
                            value={leadForm.phone}
                            onChange={e => setLeadForm({...leadForm, phone: e.target.value})}
                         />
                         <input 
                            type="email" 
                            placeholder="Email (không bắt buộc)" 
                            className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:border-pink-400 font-bold"
                            value={leadForm.email}
                            onChange={e => setLeadForm({...leadForm, email: e.target.value})}
                         />
                         <button type="submit" className="w-full py-2.5 bg-pink-500 hover:bg-pink-600 text-white rounded-xl font-bold text-sm shadow-md transition-colors">
                             Gửi thông tin
                         </button>
                     </form>
                </div>
            )}

            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white px-4 py-3 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm flex space-x-1.5 items-center">
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 bg-white border-t border-slate-100 relative z-20">
            {/* Quick Actions if Plugin Lead Form Manual Trigger is enabled */}
            {plugins?.leadForm?.enabled && plugins?.leadForm?.trigger === 'manual' && !leadSubmitted && !showLeadForm && (
                <button 
                    onClick={() => setShowLeadForm(true)}
                    className="absolute -top-10 left-1/2 -translate-x-1/2 bg-white border border-pink-200 text-pink-500 px-4 py-1.5 rounded-full text-xs font-bold shadow-md hover:bg-pink-50 transition-colors flex items-center gap-1 whitespace-nowrap"
                >
                    <i className="fa-regular fa-hand-point-up"></i> Để lại SĐT tư vấn
                </button>
            )}

            <div className="flex items-center space-x-2 bg-slate-50 p-1.5 rounded-full border border-slate-200 focus-within:ring-2 focus-within:ring-blue-100 focus-within:border-blue-400 transition-all">
              <input 
                type="text" 
                value={input} 
                onChange={(e) => setInput(e.target.value)} 
                onKeyPress={(e) => e.key === 'Enter' && handleSend()} 
                placeholder="Nhập tin nhắn..." 
                className="flex-1 text-sm bg-transparent outline-none px-4 py-2 text-slate-700 placeholder:text-slate-400 font-medium" 
                disabled={isLoading} 
              />
              <button 
                onClick={handleSend} 
                className="w-10 h-10 rounded-full text-white flex items-center justify-center transition-transform active:scale-90 shadow-md"
                style={{ backgroundColor: settings.primaryColor }}
              >
                <i className="fa-solid fa-paper-plane text-sm"></i>
              </button>
            </div>
            <div className="text-[10px] text-center text-slate-400 mt-2 font-bold flex items-center justify-center gap-1">
              <i className="fa-solid fa-bolt text-amber-400"></i> by BibiChat AI
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatWidget;

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole, Notification, Lead, PluginConfig } from "../types";

const API_URL = 'http://localhost:3001/api';
const DB_KEY = 'omnichat_db_v1';

const MASTER_USER: User = {
  id: 'admin',
  email: 'admin@bibichat.io',
  password: '123456',
  role: 'master',
  createdAt: Date.now(),
  botSettings: { 
    botName: 'BibiBot', 
    primaryColor: '#ec4899', 
    welcomeMessage: 'Xin chào! Hệ thống quản trị Master (Offline Mode).', 
    position: 'right', 
    avatarUrl: '' 
  }
};

const getLocalDB = () => {
  const data = localStorage.getItem(DB_KEY);
  let db;
  if (!data) {
    db = { users: [MASTER_USER], documents: [], chatLogs: [], notifications: [], leads: [] };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  } else {
    db = JSON.parse(data);
    if (!db.notifications) db.notifications = [];
    if (!db.leads) db.leads = [];
  }
  return db;
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      const serverRes = await res.json();
      if (res.ok && serverRes.success) return serverRes;
      else return { success: false, message: serverRes.message || 'Lỗi đăng ký từ server' };
    } catch (e) {
      console.warn("Server Offline: Registration saved locally.");
      const db = getLocalDB();
      if (db.users.find((u: any) => u.email === email)) return { success: false, message: 'Email này đã được đăng ký (Offline)' };
      const newUser: User = {
        id: Math.random().toString(36).substring(2, 11),
        email,
        password,
        role: 'user',
        createdAt: Date.now(),
        botSettings: { botName: 'Trợ lý AI', primaryColor: '#8b5cf6', welcomeMessage: 'Xin chào!', position: 'right', avatarUrl: '' }
      };
      db.users.push(newUser);
      saveLocalDB(db);
      return { success: true, message: 'Đăng ký thành công (Chế độ Offline)', user: newUser };
    }
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (!res.ok) {
         const errData = await res.json();
         return { success: false, message: errData.message || 'Lỗi đăng nhập' };
      }
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();
      let user = db.users.find((u: any) => u.email === email && u.password === password);
      if (!user && email === MASTER_USER.email && password === MASTER_USER.password) user = MASTER_USER;
      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Không thể kết nối Server & Sai thông tin Offline.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, oldPassword, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx === -1) return { success: false, message: "User không tồn tại" };
      if (db.users[idx].password !== oldPassword) return { success: false, message: "Mật khẩu cũ sai" };
      db.users[idx].password = newPassword;
      saveLocalDB(db);
      return { success: true, message: "Đổi mật khẩu thành công (Offline)" };
    }
  },

  // --- ADMIN TOOLS ---
  getAllUsers: async (): Promise<User[]> => {
    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const localDB = getLocalDB();
      return localDB.users;
    }
  },

  resetUserPassword: async (targetUserId: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetUserId, newPassword })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === targetUserId);
      if (idx !== -1) {
        db.users[idx].password = newPassword;
        saveLocalDB(db);
        return { success: true, message: "Reset thành công (Offline)" };
      }
      return { success: false, message: "Lỗi Offline" };
    }
  },

  deleteUser: async (targetUserId: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/admin/users/${targetUserId}`, { method: 'DELETE' });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      db.users = db.users.filter((u: any) => u.id !== targetUserId);
      saveLocalDB(db);
      return { success: true, message: "Xóa thành công (Offline)" };
    }
  },

  // --- SETTINGS ---
  updateSettings: async (userId: string, settings: WidgetSettings) => {
    try {
      await fetch(`${API_URL}/settings/${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      });
    } catch (e) {
      const db = getLocalDB();
      const idx = db.users.findIndex((u: any) => u.id === userId);
      if (idx !== -1) {
        db.users[idx].botSettings = settings;
        saveLocalDB(db);
      }
    }
  },

  // --- PLUGINS (NEW) ---
  getPlugins: async (userId: string): Promise<PluginConfig> => {
    try {
        const res = await fetch(`${API_URL}/plugins/${userId}`);
        if (!res.ok) throw new Error("Fetch plugins failed");
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        const user = db.users.find((u: any) => u.id === userId);
        return user?.plugins || { autoOpen: { enabled: false, delay: 5 }, social: { enabled: false, zalo: '', phone: '' }, leadForm: { enabled: false, title: '', trigger: 'manual' } };
    }
  },

  updatePlugins: async (userId: string, plugins: PluginConfig) => {
    try {
        await fetch(`${API_URL}/plugins/${userId}`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(plugins)
        });
    } catch (e) {
        const db = getLocalDB();
        const idx = db.users.findIndex((u: any) => u.id === userId);
        if (idx !== -1) {
            db.users[idx].plugins = plugins;
            saveLocalDB(db);
        }
    }
  },

  // --- LEADS (NEW) ---
  getLeads: async (userId: string): Promise<Lead[]> => {
    try {
        const res = await fetch(`${API_URL}/leads/${userId}`);
        if (!res.ok) throw new Error("Fetch leads failed");
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        return (db.leads || []).filter((l: any) => l.userId === userId).sort((a: any, b: any) => b.createdAt - a.createdAt);
    }
  },

  submitLead: async (userId: string, name: string, phone: string, email: string, isTest: boolean = false): Promise<Lead> => {
    try {
        const res = await fetch(`${API_URL}/leads`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ userId, name, phone, email, isTest })
        });
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        if (!db.leads) db.leads = [];
        const newLead: Lead = { 
            id: Math.random().toString(36).substr(2, 9), 
            userId, 
            name, 
            phone, 
            email, 
            source: 'chat_form', 
            status: 'new', 
            createdAt: Date.now(),
            isTest: isTest
        };
        db.leads.push(newLead);
        saveLocalDB(db);
        return newLead;
    }
  },

  updateLeadStatus: async (leadId: string, status: string) => {
    try {
        await fetch(`${API_URL}/leads/${leadId}/status`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ status })
        });
    } catch (e) {
        const db = getLocalDB();
        const idx = db.leads.findIndex((l: any) => l.id === leadId);
        if (idx !== -1) {
            db.leads[idx].status = status;
            saveLocalDB(db);
        }
    }
  },

  deleteLead: async (leadId: string) => {
    try {
      await fetch(`${API_URL}/leads/${leadId}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.leads = (db.leads || []).filter((l: any) => l.id !== leadId);
      saveLocalDB(db);
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const newDoc: Document = {
        id: Math.random().toString(36).substring(2, 11),
        userId,
        name,
        content,
        type,
        status: 'indexed',
        createdAt: Date.now()
      };
      db.documents.push(newDoc);
      saveLocalDB(db);
      return newDoc;
    }
  },

  deleteDocument: async (id: string) => {
    try {
      await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    let logs: ChatLog[] = [];
    try {
        logs = await apiService.getChatLogs('all');
    } catch (e) {
        const db = getLocalDB();
        logs = db.chatLogs;
    }
    if (userId !== 'all') logs = logs.filter(l => l.userId === userId);

    const statsMap: Record<string, { queries: number, solved: number }> = {};
    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);
      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;
      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });
    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    try {
        const res = await fetch(`${API_URL}/chat-logs/${userId}`);
        if(!res.ok) throw new Error("Fetch logs failed");
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        let logs = db.chatLogs as ChatLog[];
        if (userId !== 'all') logs = logs.filter(l => l.userId === userId);
        return logs.sort((a, b) => b.timestamp - a.timestamp);
    }
  },

  // --- NOTIFICATIONS ---
  getNotifications: async (userId: string): Promise<Notification[]> => {
    try {
      const res = await fetch(`${API_URL}/notifications/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const now = Date.now();
      return (db.notifications || [])
        .filter((n: any) => {
          const isTargetUser = (n.userId === 'all' || n.userId === userId);
          if (!isTargetUser) return false;
          if (userId === 'admin') return true;
          return n.scheduledAt ? n.scheduledAt <= now : n.time <= now;
        })
        .map((n: any) => ({
            ...n,
            isRead: Array.isArray(n.readBy) ? n.readBy.includes(userId) : (n.isRead || false)
        }))
        .sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    }
  },

  markNotificationRead: async (id: string, userId: string): Promise<void> => {
    try {
      await fetch(`${API_URL}/notifications/${id}/read`, { 
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId })
      });
    } catch (e) {
      const db = getLocalDB();
      const n = db.notifications?.find((x: any) => x.id === id);
      if (n) {
        if (!n.readBy) n.readBy = [];
        if (!n.readBy.includes(userId)) n.readBy.push(userId);
        saveLocalDB(db);
      }
    }
  },

  markAllNotificationsRead: async (userId: string): Promise<void> => {
    try {
        await fetch(`${API_URL}/notifications/read-all`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ userId })
        });
    } catch (e) {
        const db = getLocalDB();
        const now = Date.now();
        db.notifications?.forEach((n: any) => {
            const isTargetUser = (n.userId === 'all' || n.userId === userId);
            const isVisible = userId === 'admin' ? true : (n.scheduledAt ? n.scheduledAt <= now : n.time <= now);
            if (isTargetUser && isVisible) {
                if (!n.readBy) n.readBy = [];
                if (!n.readBy.includes(userId)) n.readBy.push(userId);
            }
        });
        saveLocalDB(db);
    }
  },

  createSystemNotification: async (data: Partial<Notification>) => {
    try {
      await fetch(`${API_URL}/notifications/create`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(data)
      });
    } catch (e) {
      const db = getLocalDB();
      if (!db.notifications) db.notifications = [];
      const now = Date.now();
      db.notifications.push({
        id: Math.random().toString(36).substr(2, 9),
        userId: data.userId || 'all',
        title: data.title || '',
        desc: data.desc || '',
        time: data.scheduledAt || now, 
        scheduledAt: data.scheduledAt || now,
        readBy: [],
        icon: data.icon || 'fa-bell',
        color: data.color || 'text-blue-500',
        bg: data.bg || 'bg-blue-100'
      });
      saveLocalDB(db);
    }
  },

  suggestIcon: async (text: string): Promise<string> => {
    if (!process.env.API_KEY) return 'fa-bullhorn';
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Based on the following notification text, suggest the single most appropriate FontAwesome 6 icon class name. ONLY return the class name string. Text: "${text}"`;
    try {
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      const iconClass = response.text?.trim() || 'fa-bullhorn';
      return iconClass.replace(/['".]/g, '');
    } catch (error) { return 'fa-bullhorn'; }
  },

  chat: async (userId: string, message: string, botName: string, sessionId: string): Promise<string> => {
    try {
      const res = await fetch(`${API_URL}/chat`, {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ userId, message, botName, sessionId })
      });
      if(res.ok) {
         const data = await res.json();
         return data.text;
      }
    } catch (e) {}

    try {
      if (!process.env.API_KEY) return "Lỗi cấu hình: Thiếu API Key.";
      const db = getLocalDB();
      const docs = db.documents.filter((d: any) => d.userId === userId);
      const context = docs.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      const systemInstruction = `Bạn là trợ lý AI tên "${botName || 'BibiBot'}". Hãy sử dụng kiến thức sau để hỗ trợ khách hàng: ${context}`;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: message, config: { systemInstruction } });
      if (!db.chatLogs) db.chatLogs = [];
      // Use the provided sessionId for grouping offline/fallback logs too
      db.chatLogs.push({ id: Math.random().toString(36).substr(2, 9), userId, customerSessionId: sessionId || 'client-fallback', query: message, answer: response.text || '', timestamp: Date.now(), isSolved: true });
      saveLocalDB(db);
      return response.text || "Tôi không thể trả lời lúc này.";
    } catch (clientError) { return "Lỗi kết nối. Vui lòng thử lại sau."; }
  }
};

