  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    loadData();
  }, [user.id]);

  const loadData = async () => {
    setIsLoading(true);
    try {
      await new Promise(r => setTimeout(r, 800)); // Cute delay
      if (isMaster) {
        const allUsers = await apiService.getAllUsers();
        // Lọc bỏ tài khoản admin/master khỏi danh sách
        setCustomers(allUsers.filter(u => u.role !== 'master'));
        const allLogs = await apiService.getChatLogs('all');
        processLogsToSessions(allLogs);
