  const processLogsToSessions = (logs: ChatLog[]) => {
      const grouped: Record<string, ChatSession> = {};

      logs.forEach(log => {
          const sid = log.customerSessionId || 'unknown';
          if (!grouped[sid]) {
              grouped[sid] = {
                  sessionId: sid,
                  userId: log.userId,
                  messages: [],
                  lastActive: 0,
                  preview: ''
              };
          }
          grouped[sid].messages.push(log);
          if (log.timestamp > grouped[sid].lastActive) {
              grouped[sid].lastActive = log.timestamp;
              grouped[sid].preview = log.query;
          }
      });

      // Sort messages within sessions and convert to array sorted by lastActive
      const sessionList = Object.values(grouped).map(s => {
          s.messages.sort((a, b) => a.timestamp - b.timestamp);
          return s;
      }).sort((a, b) => b.lastActive - a.lastActive);

      setSessions(sessionList);
