  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    // Use mousedown to detect outside clicks earlier
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    loadData();
  }, [user.id]);

  const loadData = async () => {
    setIsLoading(true);
    try {
      await new Promise(r => setTimeout(r, 800)); // Cute delay
      if (isMaster) {
        const allUsers = await apiService.getAllUsers();
        // Lọc bỏ tài khoản admin/master khỏi danh sách
        setCustomers(allUsers.filter(u => u.role !== 'master'));
        const allLogs = await apiService.getChatLogs('all');
        processLogsToSessions(allLogs);
      } else {
        const myLogs = await apiService.getChatLogs(user.id);
        processLogsToSessions(myLogs);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const processLogsToSessions = (logs: ChatLog[]) => {
      const grouped: Record<string, ChatSession> = {};

      logs.forEach(log => {
          const sid = log.customerSessionId || 'unknown';
          // FIX: Create a unique key combining UserId and SessionId to prevent merging different users
          const uniqueKey = `${log.userId}_${sid}`; 

          if (!grouped[uniqueKey]) {
              grouped[uniqueKey] = {
                  uniqueKey: uniqueKey,
                  sessionId: sid,
                  userId: log.userId,
                  messages: [],
                  lastActive: 0,
                  preview: ''
              };
          }
          grouped[uniqueKey].messages.push(log);
          if (log.timestamp > grouped[uniqueKey].lastActive) {
              grouped[uniqueKey].lastActive = log.timestamp;
              grouped[uniqueKey].preview = log.query;
          }
      });

      // Sort messages within sessions and convert to array sorted by lastActive
      const sessionList = Object.values(grouped).map(s => {
          s.messages.sort((a, b) => a.timestamp - b.timestamp);
          return s;
      }).sort((a, b) => b.lastActive - a.lastActive);

      setSessions(sessionList);
  };

  const filteredSessions = sessions.filter(session => {
    if (selectedUserFilter === 'all') return true;
    return session.userId === selectedUserFilter;
  });

  const getCustomerEmail = (userId: string) => {
    return customers.find(c => c.id === userId)?.email || 'Khách ẩn danh';
  };

  const getFilterLabel = () => {
     if (selectedUserFilter === 'all') return 'Tất cả khách hàng';
     const found = customers.find(c => c.id === selectedUserFilter);
     return found ? found.email : 'Unknown';
  };

  const handleSelectFilter = (id: string) => {
      setSelectedUserFilter(id);
      setIsDropdownOpen(false);
      // Optional: Clear selected session if it doesn't belong to the new filter
      if (id !== 'all' && selectedSession?.userId !== id) {
          setSelectedSession(null);
      }
  };

