// Updated GET /api/users to support pagination and search
app.get('/api/users', (req, res) => {
  const db = getDB();
  const page = parseInt(req.query.page as string) || 1;
  const limit = parseInt(req.query.limit as string) || 10000; // Default to all if not paginated (backward compatibility)
  const search = (req.query.search as string || '').toLowerCase();

  let filteredUsers = db.users;

  // 1. Search Filter
  if (search) {
    filteredUsers = filteredUsers.filter((u: any) => 
      u.email.toLowerCase().includes(search) || 
      (u.botSettings?.botName || '').toLowerCase().includes(search)
    );
  }

  // 2. Pagination
  const total = filteredUsers.length;
  // If no pagination params provided, return pure array (legacy support for simple dropdowns)
  if (!req.query.page && !req.query.limit) {
      return res.json(filteredUsers);
  }

  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit)
    }
  });
});

