    }
  },

  submitLead: async (userId: string, name: string, phone: string, email: string, isTest: boolean = false): Promise<Lead> => {
    try {
        const res = await fetch(`${API_URL}/leads`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ userId, name, phone, email, isTest })
        });
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        if (!db.leads) db.leads = [];
        const newLead: Lead = { 
            id: Math.random().toString(36).substr(2, 9), 
            userId, 
            name, 
            phone, 
            email, 
            source: 'chat_form', 
            status: 'new', 
            createdAt: Date.now(),
            isTest: isTest
        };
        db.leads.push(newLead);
        saveLocalDB(db);
        return newLead;
    }
  },

  updateLeadStatus: async (leadId: string, status: string) => {
    try {
        await fetch(`${API_URL}/leads/${leadId}/status`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ status })
        });
    } catch (e) {
        const db = getLocalDB();
        const idx = db.leads.findIndex((l: any) => l.id === leadId);
        if (idx !== -1) {
            db.leads[idx].status = status;
            saveLocalDB(db);
        }
    }
  },

  deleteLead: async (leadId: string) => {
    try {
      await fetch(`${API_URL}/leads/${leadId}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.leads = (db.leads || []).filter((l: any) => l.id !== leadId);
      saveLocalDB(db);
    }
  },

  // --- DOCUMENTS ---
  getDocuments: async (userId: string): Promise<Document[]> => {
    try {
      const res = await fetch(`${API_URL}/documents/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      return db.documents.filter((d: any) => d.userId === userId);
    }
  },

  addDocument: async (userId: string, name: string, content: string, type: 'text' | 'file'): Promise<Document> => {
    try {
      const res = await fetch(`${API_URL}/documents/text`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, content, userId })
      });
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const newDoc: Document = {
        id: Math.random().toString(36).substring(2, 11),
        userId,
        name,
        content,
        type,
        status: 'indexed',
        createdAt: Date.now()
      };
      db.documents.push(newDoc);
      saveLocalDB(db);
      return newDoc;
    }
  },

  deleteDocument: async (id: string) => {
    try {
      await fetch(`${API_URL}/documents/${id}`, { method: 'DELETE' });
    } catch (e) {
      const db = getLocalDB();
      db.documents = db.documents.filter((d: any) => d.id !== id);
      saveLocalDB(db);
    }
  },

  // --- ANALYTICS & LOGS ---
  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    let logs: ChatLog[] = [];
    try {
        logs = await apiService.getChatLogs('all');
    } catch (e) {
        const db = getLocalDB();
        logs = db.chatLogs;
    }
    if (userId !== 'all') logs = logs.filter(l => l.userId === userId);

    const statsMap: Record<string, { queries: number, solved: number }> = {};
    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);
      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;
      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });
    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    try {
        const res = await fetch(`${API_URL}/chat-logs/${userId}`);
        if(!res.ok) throw new Error("Fetch logs failed");
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        let logs = db.chatLogs as ChatLog[];
        if (userId !== 'all') logs = logs.filter(l => l.userId === userId);
        return logs.sort((a, b) => b.timestamp - a.timestamp);
    }
  },

  // --- NOTIFICATIONS ---
  getNotifications: async (userId: string): Promise<Notification[]> => {
    try {
      const res = await fetch(`${API_URL}/notifications/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const now = Date.now();
      return (db.notifications || [])
        .filter((n: any) => {
          const isTargetUser = (n.userId === 'all' || n.userId === userId);
          if (!isTargetUser) return false;
          if (userId === 'admin') return true;
          return n.scheduledAt ? n.scheduledAt <= now : n.time <= now;
        })
        .map((n: any) => ({
            ...n,
            isRead: Array.isArray(n.readBy) ? n.readBy.includes(userId) : (n.isRead || false)
        }))
        .sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    }
  },

  markNotificationRead: async (id: string, userId: string): Promise<void> => {
    try {
      await fetch(`${API_URL}/notifications/${id}/read`, { 
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId })
      });
    } catch (e) {
      const db = getLocalDB();
      const n = db.notifications?.find((x: any) => x.id === id);
      if (n) {
        if (!n.readBy) n.readBy = [];
        if (!n.readBy.includes(userId)) n.readBy.push(userId);
        saveLocalDB(db);
      }
    }
  },

  markAllNotificationsRead: async (userId: string): Promise<void> => {
    try {
        await fetch(`${API_URL}/notifications/read-all`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ userId })
        });
    } catch (e) {
        const db = getLocalDB();
        const now = Date.now();
        db.notifications?.forEach((n: any) => {
            const isTargetUser = (n.userId === 'all' || n.userId === userId);
            const isVisible = userId === 'admin' ? true : (n.scheduledAt ? n.scheduledAt <= now : n.time <= now);
            if (isTargetUser && isVisible) {
                if (!n.readBy) n.readBy = [];
                if (!n.readBy.includes(userId)) n.readBy.push(userId);
            }
        });
        saveLocalDB(db);
    }
  },

  createSystemNotification: async (data: Partial<Notification>) => {
    try {
      await fetch(`${API_URL}/notifications/create`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(data)
      });
    } catch (e) {
      const db = getLocalDB();
      if (!db.notifications) db.notifications = [];
      const now = Date.now();
      db.notifications.push({
        id: Math.random().toString(36).substr(2, 9),
        userId: data.userId || 'all',
        title: data.title || '',
        desc: data.desc || '',
        time: data.scheduledAt || now, 
        scheduledAt: data.scheduledAt || now,
        readBy: [],
        icon: data.icon || 'fa-bell',
        color: data.color || 'text-blue-500',
        bg: data.bg || 'bg-blue-100'
      });
      saveLocalDB(db);
    }
  },

  suggestIcon: async (text: string): Promise<string> => {
    if (!process.env.API_KEY) return 'fa-bullhorn';
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Based on the following notification text, suggest the single most appropriate FontAwesome 6 icon class name. ONLY return the class name string. Text: "${text}"`;
    try {
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      const iconClass = response.text?.trim() || 'fa-bullhorn';
      return iconClass.replace(/['".]/g, '');
    } catch (error) { return 'fa-bullhorn'; }
  },

  chat: async (userId: string, message: string, botName: string, sessionId: string): Promise<string> => {
    try {
      const res = await fetch(`${API_URL}/chat`, {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ userId, message, botName, sessionId })
      });
      if(res.ok) {
         const data = await res.json();
         return data.text;
      }
    } catch (e) {}

    try {
      if (!process.env.API_KEY) return "Lỗi cấu hình: Thiếu API Key.";
      const db = getLocalDB();
      const docs = db.documents.filter((d: any) => d.userId === userId);
      const context = docs.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      const systemInstruction = `Bạn là trợ lý AI tên "${botName || 'BibiBot'}". Hãy sử dụng kiến thức sau để hỗ trợ khách hàng: ${context}`;
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: message, config: { systemInstruction } });
      if (!db.chatLogs) db.chatLogs = [];
      // Use the provided sessionId for grouping offline/fallback logs too
      db.chatLogs.push({ id: Math.random().toString(36).substr(2, 9), userId, customerSessionId: sessionId || 'client-fallback', query: message, answer: response.text || '', timestamp: Date.now(), isSolved: true });
      saveLocalDB(db);
      return response.text || "Tôi không thể trả lời lúc này.";
    } catch (clientError) { return "Lỗi kết nối. Vui lòng thử lại sau."; }
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  onViewStats: (userId: string) => void;
}

const CustomerManagement: React.FC<Props> = ({ onViewStats }) => {
  const [customers, setCustomers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // Pagination State
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalUsers, setTotalUsers] = useState(0);
  const LIMIT = 10; // Number of items per page

  // States for Modals
  const [resetModal, setResetModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [newResetPassword, setNewResetPassword] = useState('');
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, userId: string | null, email: string }>({ isOpen: false, userId: null, email: '' });
  const [actionMsg, setActionMsg] = useState<{ type: string, text: string }>({ type: '', text: '' });

  // Loading state for modal actions
  const [isProcessing, setIsProcessing] = useState(false);

  // Debounce search function
  useEffect(() => {
    const delayDebounceFn = setTimeout(() => {
      setPage(1); // Reset to page 1 on new search
      loadCustomers(1, searchTerm);
    }, 500);

    return () => clearTimeout(delayDebounceFn);
  }, [searchTerm]);

  // Handle page change
  const handlePageChange = (newPage: number) => {
      if (newPage >= 1 && newPage <= totalPages) {
          setPage(newPage);
          loadCustomers(newPage, searchTerm);
      }
  };

  const loadCustomers = async (currentPage: number, search: string) => {
    setIsLoading(true);
    try {
      // Fetch paginated data
      const result = await apiService.getUsersPaginated(currentPage, LIMIT, search);
      // Filter out 'master' role locally just in case, though server handles logic mostly
      const filtered = result.data.filter(u => u.role !== 'master');
      setCustomers(filtered);
      setTotalPages(result.totalPages);
      setTotalUsers(result.total);
    } catch (err) {
      console.error("Lỗi khi tải khách hàng:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!resetModal.userId || !newResetPassword) return;
    setIsProcessing(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      const result = await apiService.resetUserPassword(resetModal.userId, newResetPassword);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã đổi pass cho ${resetModal.email}` });
        setResetModal({ isOpen: false, userId: null, email: '' });
        setNewResetPassword('');
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setIsProcessing(false);
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  const handleDeleteUser = async () => {
    if (!deleteModal.userId) return;
    setIsProcessing(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      const result = await apiService.deleteUser(deleteModal.userId);
      if (result.success) {
        setActionMsg({ type: 'success', text: `Đã xóa bé ${deleteModal.email}` });
        setDeleteModal({ isOpen: false, userId: null, email: '' });
        loadCustomers(page, searchTerm); 
      } else {
        setActionMsg({ type: 'error', text: result.message });
      }
    } catch (e) {
      setActionMsg({ type: 'error', text: 'Lỗi hệ thống' });
    }
    setIsProcessing(false);
    setTimeout(() => setActionMsg({ type: '', text: '' }), 3000);
  };

  return (
    <>
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Header & Search */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-white dark:border-slate-700 shadow-lg shadow-indigo-50/50 dark:shadow-none">
        <div className="flex items-center gap-4">
            <div>
              <h2 className="text-xl font-bold text-slate-800 dark:text-white flex items-center">
                <span className="w-10 h-10 rounded-2xl bg-indigo-100 dark:bg-indigo-900/50 text-indigo-500 dark:text-indigo-300 flex items-center justify-center mr-3 text-lg">
                  <i className="fa-solid fa-users"></i>
                </span>
                Quản lý khách hàng
              </h2>
              <p className="text-xs font-bold text-slate-400 dark:text-slate-500 ml-1 mt-1">Tổng cộng: {totalUsers} user</p>
            </div>
            <button 
              onClick={() => loadCustomers(page, searchTerm)}
              disabled={isLoading}
              className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-50 dark:bg-slate-700 text-slate-400 dark:text-slate-300 hover:bg-indigo-100 dark:hover:bg-indigo-900 hover:text-indigo-500 transition-all active:scale-90 border border-slate-100 dark:border-slate-600 shadow-sm"
              title="Làm mới danh sách"
