                <th className="px-6 py-5 text-sm font-black text-indigo-900/70 dark:text-indigo-200 rounded-r-2xl text-right pr-8 whitespace-nowrap">
                  <i className="fa-solid fa-wand-magic-sparkles mr-2 text-amber-400"></i>
                  Hành động
