// 1. Get Paginated Sessions (Grouped logs)
app.get('/api/chat-sessions/:userId', (req, res) => {
    const { userId } = req.params;
    const db = getDB();
    const page = parseInt(req.query.page as string) || 1;
    const limit = parseInt(req.query.limit as string) || 10;
    const filterUserId = req.query.filterUserId as string || 'all'; // Filter by a specific customer ID

    let allLogs = db.chatLogs || [];

    // Filter by Owner
    if (userId !== 'all') {
        allLogs = allLogs.filter((l: any) => l.userId === userId);
    }

    // Filter by Specific Customer (if selected in dropdown)
    if (filterUserId !== 'all') {
        // In a real DB, `userId` in logs refers to the bot owner. 
        // We assume `customerSessionId` is unique per customer session.
        // If we want to filter by "Customer", we typically filter by user metadata or session ID.
        // For simplicity in this file-based DB, we might skip complex customer filtering 
        // or filter logs where `userId` matches if `filterUserId` implies a sub-user (not applicable here as userId is owner).
        // Let's assume filterUserId here allows Master Admin to filter by Bot Owner ID.
        if (userId === 'all') { // Master admin looking at specific owner
             allLogs = allLogs.filter((l: any) => l.userId === filterUserId);
        }
    }

    // Grouping Logic (Heavy operation - in real DB use aggregation)
    const sessionsMap: Record<string, any> = {};

    allLogs.forEach((log: any) => {
        const key = `${log.userId}_${log.customerSessionId}`;
        if (!sessionsMap[key]) {
            sessionsMap[key] = {
                uniqueKey: key,
                sessionId: log.customerSessionId,
                userId: log.userId,
                lastActive: log.timestamp,
                preview: log.query,
                messageCount: 0
            };
        }
        sessionsMap[key].messageCount++;
        // Update last active and preview to the latest message
        if (log.timestamp > sessionsMap[key].lastActive) {
            sessionsMap[key].lastActive = log.timestamp;
            sessionsMap[key].preview = log.query;
        }
    });

    const sessions = Object.values(sessionsMap).sort((a: any, b: any) => b.lastActive - a.lastActive);

    const total = sessions.length;
    const startIndex = (page - 1) * limit;
    const paginatedSessions = sessions.slice(startIndex, startIndex + limit);

    res.json({
        data: paginatedSessions,
        pagination: {
            total,
            page,
            limit,
            totalPages: Math.ceil(total / limit)
        }
    });
});

