  const db = getDB();
  const user = db.users.find((u: any) => u.id === req.params.userId);
  user ? res.json(user.botSettings) : res.status(404).json({ success: false });
});
app.post('/api/settings/:userId', (req, res) => {
  const db = getDB();
  const idx = db.users.findIndex((u: any) => u.id === req.params.userId);
  if (idx !== -1) { db.users[idx].botSettings = req.body; saveDB(db); res.json({ success: true }); } 
  else res.status(404).json({ success: false });
});
app.post('/api/documents/text', (req, res) => {
  const { name, content, userId } = req.body;
  const db = getDB();
  const newDoc = { id: Math.random().toString(36).substr(2, 9), userId, name, content, type: 'text', status: 'indexed', createdAt: Date.now() };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});
app.post('/api/documents/upload', upload.single('file') as any, (req: any, res: any) => {
  const file = (req as any).file;
  if (!file || !req.body.userId) return res.status(400).send('Missing file/userId');
  const db = getDB();
  const newDoc = { id: Math.random().toString(36).substr(2, 9), userId: req.body.userId, name: file.originalname, content: fs.readFileSync(file.path, 'utf-8'), path: file.path, type: 'file', status: 'indexed', createdAt: Date.now() };
  db.documents.push(newDoc);
  saveDB(db);
  res.json(newDoc);
});
app.delete('/api/documents/:id', (req, res) => {
  const db = getDB();
  const doc = db.documents.find((d: any) => d.id === req.params.id);
  if (doc && doc.path && fs.existsSync(doc.path)) fs.unlinkSync(doc.path);
  db.documents = db.documents.filter((d: any) => d.id !== req.params.id);
  saveDB(db);
  res.json({ success: true });
});
app.post('/api/chat', async (req, res) => {
  const { message, userId, botName, sessionId } = req.body;
  const db = getDB();
  if (!process.env.API_KEY) return res.status(500).json({ error: "Missing API KEY" });
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const context = db.documents.filter((d: any) => d.userId === userId).map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
  const systemInstruction = `Bạn là trợ lý AI tên "${botName || 'BibiBot'}". Dữ liệu: ${context}`;
  try {
    const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: message, config: { systemInstruction } });
    const reply = response.text || "Tôi không thể trả lời.";
    if (!db.chatLogs) db.chatLogs = [];
    db.chatLogs.push({ id: Math.random().toString(36).substr(2, 9), userId, customerSessionId: sessionId || 'anon', query: message, answer: reply, timestamp: Date.now(), tokens: message.length, isSolved: !reply.includes("không có thông tin") });
    saveDB(db);
    res.json({ text: reply });
  } catch (error) { res.status(500).json({ error: "AI Error" }); }
});

app.listen(PORT, () => {
  console.log(`SaaS Backend running at http://localhost:${PORT}`);
});

import { GoogleGenAI } from "@google/genai";
import { User, Document, WidgetSettings, ChatLog, UserRole, Notification, Lead, PluginConfig } from "../types";

const API_URL = 'http://localhost:3001/api';
const DB_KEY = 'omnichat_db_v1';

const MASTER_USER: User = {
  id: 'admin',
  email: 'admin@bibichat.io',
  password: '123456',
  role: 'master',
  createdAt: Date.now(),
  botSettings: { 
    botName: 'BibiBot', 
    primaryColor: '#ec4899', 
    welcomeMessage: 'Xin chào! Hệ thống quản trị Master (Offline Mode).', 
    position: 'right', 
    avatarUrl: '' 
  }
};

const getLocalDB = () => {
  const data = localStorage.getItem(DB_KEY);
  let db;
  if (!data) {
    db = { users: [MASTER_USER], documents: [], chatLogs: [], notifications: [], leads: [] };
    localStorage.setItem(DB_KEY, JSON.stringify(db));
  } else {
    db = JSON.parse(data);
    if (!db.notifications) db.notifications = [];
    if (!db.leads) db.leads = [];
  }
  return db;
};

const saveLocalDB = (db: any) => {
  localStorage.setItem(DB_KEY, JSON.stringify(db));
};

export const apiService = {
  // --- AUTH ---
  register: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      const serverRes = await res.json();
      if (res.ok && serverRes.success) return serverRes;
      else return { success: false, message: serverRes.message || 'Lỗi đăng ký từ server' };
    } catch (e) {
      console.warn("Server Offline: Registration saved locally.");
      const db = getLocalDB();
      if (db.users.find((u: any) => u.email === email)) return { success: false, message: 'Email này đã được đăng ký (Offline)' };
      const newUser: User = {
        id: Math.random().toString(36).substring(2, 11),
        email,
        password,
        role: 'user',
        createdAt: Date.now(),
        botSettings: { botName: 'Trợ lý AI', primaryColor: '#8b5cf6', welcomeMessage: 'Xin chào!', position: 'right', avatarUrl: '' }
      };
      db.users.push(newUser);
      saveLocalDB(db);
      return { success: true, message: 'Đăng ký thành công (Chế độ Offline)', user: newUser };
    }
  },

  login: async (email: string, password: string): Promise<{success: boolean, message: string, user?: User}> => {
    try {
      const res = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      if (!res.ok) {
         const errData = await res.json();
         return { success: false, message: errData.message || 'Lỗi đăng nhập' };
      }
      return await res.json();
    } catch (e) {
      console.warn("Server Offline: Fallback to LocalStorage login");
      const db = getLocalDB();
      let user = db.users.find((u: any) => u.email === email && u.password === password);
      if (!user && email === MASTER_USER.email && password === MASTER_USER.password) user = MASTER_USER;
      if (user) return { success: true, message: 'Đăng nhập thành công (Offline Mode)', user };
      return { success: false, message: 'Không thể kết nối Server & Sai thông tin Offline.' };
    }
  },

  changePassword: async (userId: string, oldPassword: string, newPassword: string): Promise<{success: boolean, message: string}> => {
    try {
      const res = await fetch(`${API_URL}/user/change-password`, {
        method: 'POST',
