                                <td className="px-6 py-5 border-b border-transparent text-sm font-bold text-slate-500">
                                {new Date(lead.createdAt).toLocaleString('vi-VN')}
                                </td>
                                <td className="px-6 py-5 text-left border-b border-transparent relative">
                                    {/* Cute Custom Dropdown */}
                                    <div className="relative">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setOpenDropdownId(openDropdownId === lead.id ? null : lead.id); }}
                                            className={`flex items-center gap-2 px-3 py-1.5 rounded-full border-2 text-xs font-bold transition-all active:scale-95 ${statusStyle.color}`}
                                        >
                                            <i className={`fa-solid ${statusStyle.icon}`}></i>
                                            {statusStyle.label}
                                            <i className="fa-solid fa-chevron-down text-[10px] ml-1 opacity-60"></i>
                                        </button>

                                        {openDropdownId === lead.id && (
                                            <div className="absolute top-full left-0 mt-2 w-40 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border-2 border-slate-100 dark:border-slate-600 z-50 overflow-hidden animate-in fade-in zoom-in duration-200">
                                                <button onClick={() => updateStatus(lead.id, 'new')} className="w-full text-left px-4 py-3 text-xs font-bold text-blue-600 hover:bg-blue-50 dark:hover:bg-slate-700 flex items-center gap-2">
                                                    <i className="fa-solid fa-star w-4"></i> Mới tinh
                                                </button>
                                                <button onClick={() => updateStatus(lead.id, 'contacted')} className="w-full text-left px-4 py-3 text-xs font-bold text-amber-600 hover:bg-amber-50 dark:hover:bg-slate-700 flex items-center gap-2 border-t border-slate-50 dark:border-slate-700">
                                                    <i className="fa-solid fa-comments w-4"></i> Đang chat
                                                </button>
                                                <button onClick={() => updateStatus(lead.id, 'converted')} className="w-full text-left px-4 py-3 text-xs font-bold text-emerald-600 hover:bg-emerald-50 dark:hover:bg-slate-700 flex items-center gap-2 border-t border-slate-50 dark:border-slate-700">
                                                    <i className="fa-solid fa-check-circle w-4"></i> Chốt đơn
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-5 rounded-r-2xl pr-8 text-left border-b border-transparent">
                                    <div className="flex items-center justify-between gap-4">
                                        {lead.isTest ? (
                                            <span className="text-[10px] font-black bg-amber-100 text-amber-600 border border-amber-200 px-3 py-1.5 rounded-full whitespace-nowrap shadow-sm">
                                                <i className="fa-solid fa-flask mr-1.5"></i> Dữ liệu Test
                                            </span>
                                        ) : (
                                            <span className="text-[10px] font-black bg-emerald-100 text-emerald-600 border border-emerald-200 px-3 py-1.5 rounded-full whitespace-nowrap shadow-sm">
                                                <i className="fa-solid fa-globe mr-1.5"></i> Dữ liệu Thật
                                            </span>
                                        )}
                                        <button 
                                            type="button"
                                            onClick={(e) => handleDeleteClick(e, lead.id)}
                                            className={`h-9 shrink-0 rounded-full flex items-center justify-center transition-all shadow-sm active:scale-90 font-bold text-xs border ${
                                                isConfirming 
                                                ? 'w-auto px-3 bg-red-500 text-white border-red-600 hover:bg-red-600 animate-pulse' 
                                                : 'w-9 bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 hover:border-rose-200'
                                            }`}
                                            title="Xóa khách hàng"
                                        >
                                            {isConfirming ? (
                                                <>
                                                    <i className="fa-solid fa-circle-question mr-1"></i> Xóa?
                                                </>
                                            ) : (
                                                <i className="fa-solid fa-trash-can text-sm"></i>
                                            )}
                                        </button>
                                    </div>
                                </td>
                            </tr>
                         );
                      })
                  )}
               </tbody>
            </table>
         </div>

         {/* Pagination Controls */}
         {totalLeads > 0 && (
            <div className="flex items-center justify-between p-6 border-t border-slate-50 dark:border-slate-700/50">
                <span className="text-xs font-bold text-slate-400 dark:text-slate-500">
                    Hiển thị {((page - 1) * LIMIT) + 1} - {Math.min(page * LIMIT, totalLeads)} trong số {totalLeads}
                </span>
                <div className="flex gap-2">
                    <button 
                        onClick={() => handlePageChange(page - 1)} 
                        disabled={page === 1}
                        className="px-4 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 font-bold text-xs disabled:opacity-50 hover:bg-pink-50 dark:hover:bg-slate-700 transition-colors"
                    >
                        Trước
                    </button>
                    <span className="px-4 py-2 text-xs font-bold text-slate-500 dark:text-slate-400 flex items-center">
                        Trang {page} / {totalPages}
                    </span>
                    <button 
                        onClick={() => handlePageChange(page + 1)} 
                        disabled={page === totalPages}
                        className="px-4 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 font-bold text-xs disabled:opacity-50 hover:bg-pink-50 dark:hover:bg-slate-700 transition-colors"
                    >
                        Sau
                    </button>
                </div>
            </div>
         )}
      </div>
    </div>
  );
};

