// --- PLUGINS API ---
app.get('/api/plugins/:userId', (req, res) => {
    const db = getDB();
    const user = db.users.find((u: any) => u.id === req.params.userId);
    if (user) {
        const plugins = user.plugins || {
            autoOpen: { enabled: false, delay: 5 },
