app.post('/api/plugins/:userId', (req, res) => {
    const db = getDB();
    const userIndex = db.users.findIndex((u: any) => u.id === req.params.userId);
    if (userIndex !== -1) {
        db.users[userIndex].plugins = req.body;
        saveDB(db);
        res.json({ success: true });
    } else {
        res.status(404).json({ success: false });
    }
});

// --- LEADS API (OPTIMIZED) ---
app.get('/api/leads/:userId', (req, res) => {
    const db = getDB();
    const { userId } = req.params;
    const page = parseInt(req.query.page as string) || 1;
    const limit = parseInt(req.query.limit as string) || 10;
    const search = (req.query.search as string || '').toLowerCase();

    // 1. Filter by User
    let leads = (db.leads || []).filter((l: any) => l.userId === userId);

    // 2. Filter by Search
    if (search) {
        leads = leads.filter((l: any) => 
            l.name.toLowerCase().includes(search) || 
            l.phone.includes(search) || 
            (l.email && l.email.toLowerCase().includes(search))
        );
    }

    // 3. Sort
    leads.sort((a: any, b: any) => b.createdAt - a.createdAt);

    // 4. Paginate
    const total = leads.length;
    const startIndex = (page - 1) * limit;
    const paginatedLeads = leads.slice(startIndex, startIndex + limit);

    res.json({
        data: paginatedLeads,
        pagination: {
            total,
            page,
            limit,
            totalPages: Math.ceil(total / limit)
        }
    });
});

app.post('/api/leads', (req, res) => {
    const db = getDB();
    const { userId, name, phone, email, isTest } = req.body;

    if (!db.leads) db.leads = [];

    const newLead = {
        id: Math.random().toString(36).substr(2, 9),
        userId,
        name,
        phone,
        email,
        source: 'chat_form',
        status: 'new',
        createdAt: Date.now(),
        isTest: !!isTest
    };

    db.leads.push(newLead);
    saveDB(db);
    res.json(newLead);
});

app.post('/api/leads/:id/status', (req, res) => {
    const db = getDB();
    const idx = (db.leads || []).findIndex((l: any) => l.id === req.params.id);
    if (idx !== -1) {
        db.leads[idx].status = req.body.status;
        saveDB(db);
        res.json({ success: true });
    } else {
        res.status(404).json({ success: false });
    }
});

app.delete('/api/leads/:id', (req, res) => {
    const db = getDB();
    const initialLength = (db.leads || []).length;
    db.leads = (db.leads || []).filter((l: any) => l.id !== req.params.id);

    if (db.leads.length < initialLength) {
        saveDB(db);
        res.json({ success: true });
    } else {
        res.status(404).json({ success: false, message: 'Lead not found' });
    }
});

