// --- CHAT LOGS OPTIMIZATION (SESSION BASED - FIXED) ---

// 1. Get Paginated Sessions (Grouped logs)
app.get('/api/chat-sessions/:userId', (req, res) => {
    const { userId } = req.params; // 'all' (Admin) or specific user ID
    const db = getDB();
    const page = parseInt(req.query.page as string) || 1;
    const limit = parseInt(req.query.limit as string) || 10;
    const filterUserId = req.query.filterUserId as string || 'all'; 

    let allLogs = db.chatLogs || [];

    // Filter Logic:
    // If Admin request (userId = 'all'):
    //    - If filterUserId is 'all': Show logs from ALL users.
    //    - If filterUserId is specific: Show logs only for that user.
    // If User request (userId = specific):
    //    - Show logs only for that user (ignore filterUserId).

    if (userId !== 'all') {
        // User view
        allLogs = allLogs.filter((l: any) => l.userId === userId);
    } else {
        // Admin view
        if (filterUserId !== 'all') {
            allLogs = allLogs.filter((l: any) => l.userId === filterUserId);
        }
    }

    // Grouping Logic
    const sessionsMap: Record<string, any> = {};

    allLogs.forEach((log: any) => {
        const sessId = log.customerSessionId || 'legacy_session';
        // Unique key must include owner (userId) to distinguish same session IDs across different owners (if collisions occur)
        const key = `${log.userId}_${sessId}`; 

        if (!sessionsMap[key]) {
            sessionsMap[key] = {
                uniqueKey: key,
                sessionId: sessId,
                userId: log.userId,
                lastActive: log.timestamp,
                preview: log.query,
                messageCount: 0
            };
        }
        sessionsMap[key].messageCount++;
        if (log.timestamp > sessionsMap[key].lastActive) {
            sessionsMap[key].lastActive = log.timestamp;
            sessionsMap[key].preview = log.query;
        }
    });

    const sessions = Object.values(sessionsMap).sort((a: any, b: any) => b.lastActive - a.lastActive);

    const total = sessions.length;
    const startIndex = (page - 1) * limit;
    const paginatedSessions = sessions.slice(startIndex, startIndex + limit);

    res.json({
        data: paginatedSessions,
        pagination: {
            total,
            page,
            limit,
            totalPages: Math.ceil(total / limit)
        }
    });
});

// 2. Get Messages for a specific Session
app.get('/api/chat-messages/:userId/:sessionId', (req, res) => {
    const { userId, sessionId } = req.params;
    const db = getDB();

    // Logic:
    // If userId is 'all' (Admin), we find messages with that sessionId across all users (or filter if needed, but sessionIds are usually unique enough or we rely on context).
    // Actually, safer to just filter by sessionId if userId is 'all', OR if strict, pass the owner ID.
    // The previous component code passes 'all' for Admin. 
    // Ideally, the session object should contain the owner ID, and the component should pass that specific ID even if Admin.
    // But for simplicity, we allow lenient filtering.

    const messages = (db.chatLogs || []).filter((l: any) => 
        (userId === 'all' || l.userId === userId) && 
        (l.customerSessionId === sessionId || (sessionId === 'legacy_session' && !l.customerSessionId))
    );

    messages.sort((a: any, b: any) => a.timestamp - b.timestamp);
    res.json(messages);
});

