                                Bắt đầu lúc {new Date(messages[0].timestamp).toLocaleString('vi-VN')}
                                </span>
                            </div>
                        )}

                        {messages.map((log) => (
                            <React.Fragment key={log.id}>
                                {/* User Message */}
                                <div className="flex justify-end">
                                    <div className="max-w-[85%] lg:max-w-[75%] space-y-2 group">
                                    <div className="flex justify-end items-end gap-2">
                                        <div className={`${theme.userBubble} text-white px-5 py-3 rounded-[1.5rem] rounded-tr-none shadow-lg dark:shadow-none text-sm font-medium leading-relaxed relative border-2 border-white dark:border-slate-700`}>
                                            {log.query}
                                        </div>
                                        <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center shrink-0 border-2 border-white shadow-sm">
                                            <i className="fa-solid fa-user text-xs text-slate-500"></i>
                                        </div>
                                    </div>
                                    </div>
                                </div>

                                {/* AI Response */}
                                <div className="flex justify-start">
                                    <div className="max-w-[90%] lg:max-w-[80%] space-y-2">
                                    <div className="flex items-end gap-3">
                                        <div className="w-10 h-10 rounded-2xl bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 flex items-center justify-center text-lg shadow-md shrink-0 mb-1 z-10">
                                        <i className={`fa-solid fa-robot animate-pulse ${theme.botAvatarText}`}></i>
                                        </div>
                                        <div>
                                            <div className="bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-100 dark:border-slate-700 px-5 py-4 rounded-[1.5rem] rounded-tl-none shadow-md text-sm font-medium leading-relaxed whitespace-pre-wrap relative">
                                            {log.answer}
                                            </div>
                                            <div className="flex items-center gap-2 mt-2 ml-2">
                                            {!log.isSolved && (
                                                <span className="text-[9px] text-rose-500 dark:text-rose-400 bg-rose-50 dark:bg-rose-900/20 px-2 py-0.5 rounded-full font-bold flex items-center border border-rose-100 dark:border-rose-900 animate-pulse">
                                                <i className="fa-solid fa-circle-exclamation mr-1"></i>
                                                Chưa tìm thấy thông tin
                                                </span>
                                            )}
                                            <span className="text-[9px] text-slate-300 font-bold ml-auto pr-2">
                                                {new Date(log.timestamp).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                                            </span>
                                            </div>
                                        </div>
                                    </div>
                                    </div>
                                </div>
                            </React.Fragment>
                        ))}
                      </>
                  )}
                </div>
             </>
           ) : (
             <div className="h-full flex flex-col items-center justify-center text-slate-300 dark:text-slate-600 p-8 text-center relative z-10">
               <div className="w-24 h-24 bg-white dark:bg-slate-800 rounded-full border-[6px] border-slate-100 dark:border-slate-700 shadow-sm flex items-center justify-center mb-6">
                 <i className={`fa-solid fa-comments text-4xl ${isMaster ? 'text-indigo-200 dark:text-slate-600' : 'text-pink-200 dark:text-slate-600'}`}></i>
               </div>
               <h3 className="text-xl font-bold text-slate-700 dark:text-slate-400 mb-2">Chọn phiên chat để xem</h3>
               <p className="text-sm text-slate-400">Danh sách phiên bên trái kìa bạn ơi 👇</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

export default ChatHistory;

import React, { useState, useEffect, useRef } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { apiService } from '../services/apiService';
import { User } from '../types';

interface Props {
  user: User;
  initialSelectedUser?: string;
}

const Dashboard: React.FC<Props> = ({ user, initialSelectedUser = 'all' }) => {
  const isMaster = user.role === 'master';
  const [period, setPeriod] = useState<'hour' | 'day' | 'week' | 'month'>('day');
  const [selectedUser, setSelectedUser] = useState<string>(initialSelectedUser);
  const [customers, setCustomers] = useState<User[]>([]);
  const [stats, setStats] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedUser(initialSelectedUser);
  }, [initialSelectedUser]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isMaster) {
      apiService.getAllUsers().then(users => {
        // Chỉ hiển thị tài khoản khách hàng (loại bỏ admin/master)
        setCustomers(users.filter(u => u.role !== 'master'));
      });
    }
    loadStats();
  }, [period, selectedUser, user.id]);

  const loadStats = async () => {
    setIsLoading(true);
    const targetId = isMaster ? selectedUser : user.id;
    // Removed artificial delay
    const data = await apiService.getStats(targetId as any, period);
    setStats(data);
    setIsLoading(false);
  };

  const totalQueries = stats.reduce((acc, curr) => acc + curr.queries, 0);
  const totalSolved = stats.reduce((acc, curr) => acc + curr.solved, 0);
  const successRate = totalQueries > 0 ? Math.round((totalSolved / totalQueries) * 100) : 0;

  const getSelectedUserLabel = () => {
    if (selectedUser === 'all') return 'Toàn bộ hệ thống';
    const found = customers.find(c => c.id === selectedUser);
    return found ? found.email : 'Unknown';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Header Card */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white dark:bg-slate-800 p-8 rounded-[2rem] border-2 border-slate-100 dark:border-slate-700 shadow-xl shadow-slate-200/50 dark:shadow-none">
        <div>
          <h2 className="text-3xl font-black text-slate-800 dark:text-white tracking-tight mb-2 flex items-center gap-3">
            <span className="text-3xl animate-bounce">📊</span> Hiệu suất AI
          </h2>
          <p className="text-base text-slate-600 dark:text-slate-400 font-bold">
            {isMaster && selectedUser !== 'all' 
              ? `Đang xem: ${customers.find(c => c.id === selectedUser)?.email}` 
              : 'Theo dõi sự chăm chỉ của AI theo thời gian thực.'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full lg:w-auto items-center">
          {isMaster && (
            <div className="relative flex-1 lg:flex-none w-full lg:w-72 z-20" ref={dropdownRef}>
              <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-6 py-4 bg-white dark:bg-slate-700 border-2 border-slate-200 dark:border-slate-600 rounded-2xl text-sm font-bold hover:border-indigo-400 transition-all text-slate-700 dark:text-slate-200 shadow-sm"
              >
                <span className="truncate">{getSelectedUserLabel()}</span>
                <i className={`fa-solid fa-chevron-down text-xs transition-transform text-slate-400 ${isDropdownOpen ? 'rotate-180' : ''}`}></i>
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 w-full mt-2 bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 rounded-2xl shadow-2xl overflow-hidden max-h-60 overflow-y-auto animate-in fade-in zoom-in duration-200 z-50">
                  <div 
                    onClick={() => { setSelectedUser('all'); setIsDropdownOpen(false); }}
                    className={`px-5 py-4 text-sm font-bold cursor-pointer hover:bg-indigo-50 dark:hover:bg-slate-600 hover:text-indigo-600 transition-colors ${selectedUser === 'all' ? 'bg-indigo-50 dark:bg-slate-600 text-indigo-600 dark:text-white' : 'text-slate-600 dark:text-slate-300'}`}
                  >
                    Toàn bộ hệ thống
                  </div>
                  {customers.map(c => (
                    <div 
                      key={c.id} 
                      onClick={() => { setSelectedUser(c.id); setIsDropdownOpen(false); }}
                      className={`px-5 py-4 text-sm font-bold cursor-pointer hover:bg-indigo-50 dark:hover:bg-slate-600 hover:text-indigo-600 border-t border-slate-100 dark:border-slate-600 transition-colors ${selectedUser === c.id ? 'bg-indigo-50 dark:bg-slate-600 text-indigo-600 dark:text-white' : 'text-slate-600 dark:text-slate-300'}`}
                    >
                      {c.email}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex bg-slate-100 dark:bg-slate-700/80 p-2 rounded-2xl border border-slate-200 dark:border-slate-600 shadow-inner">
            {(['hour', 'day', 'week', 'month'] as const).map(p => (
              <button
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-5 py-2.5 text-xs font-extrabold rounded-xl transition-all ${
                  period === p ? 'bg-white dark:bg-slate-600 text-indigo-600 dark:text-white shadow-md' : 'text-slate-500 dark:text-slate-400 hover:text-indigo-500 dark:hover:text-slate-200'
                }`}
              >
                {p === 'hour' ? 'Giờ' : p === 'day' ? 'Ngày' : p === 'week' ? 'Tuần' : 'Tháng'}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Stats Cards - Colorful Gradients */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { 
            label: 'Tổng lượt hỏi', 
            value: totalQueries, 
            icon: 'fa-solid fa-comments', 
            bg: 'bg-gradient-to-br from-blue-50 to-white dark:from-slate-800 dark:to-slate-800',
            iconBg: 'bg-blue-600 shadow-lg shadow-blue-500/40',
            text: 'text-blue-700 dark:text-blue-400',
            border: 'border-blue-200 dark:border-slate-700'
          },
          { 
            label: 'Đã giải quyết', 
            value: `${successRate}%`, 
            icon: 'fa-solid fa-wand-magic-sparkles', 
            bg: 'bg-gradient-to-br from-emerald-50 to-white dark:from-slate-800 dark:to-slate-800',
            iconBg: 'bg-emerald-600 shadow-lg shadow-emerald-500/40',
            text: 'text-emerald-700 dark:text-emerald-400',
            border: 'border-emerald-200 dark:border-slate-700'
          },
          { 
            label: 'Cần hỗ trợ', 
            value: totalQueries - totalSolved, 
            icon: 'fa-solid fa-headset', 
            bg: 'bg-gradient-to-br from-orange-50 to-white dark:from-slate-800 dark:to-slate-800',
            iconBg: 'bg-orange-500 shadow-lg shadow-orange-500/40',
            text: 'text-orange-600 dark:text-orange-400',
            border: 'border-orange-200 dark:border-slate-700'
          },
        ].map((stat, i) => (
          <div key={i} className={`${stat.bg} p-8 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border-2 ${stat.border} flex items-center space-x-6 hover:-translate-y-2 transition-all duration-300 group`}>
            <div className={`w-20 h-20 rounded-[1.5rem] ${stat.iconBg} flex items-center justify-center shrink-0 text-white text-3xl group-hover:scale-110 group-hover:rotate-6 transition-transform border-4 border-white dark:border-slate-700`}>
              <i className={`${stat.icon}`}></i>
            </div>
            <div>
              <p className="text-sm font-extrabold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-1">{stat.label}</p>
              <h3 className={`text-5xl font-black ${stat.text}`}>{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      {/* Chart Card */}
      <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-2xl shadow-slate-200/50 dark:shadow-none border-2 border-slate-100 dark:border-slate-700 relative overflow-hidden">
        {/* Background Decor */}
        <div className="absolute top-0 right-0 w-80 h-80 bg-indigo-50 dark:bg-indigo-900/20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 opacity-70 pointer-events-none"></div>

        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8 relative z-10">
          <div>
            <h3 className="text-xl font-bold text-slate-800 dark:text-white">Biểu đồ tăng trưởng</h3>
            <p className="text-sm text-slate-500 dark:text-slate-400 font-bold mt-1">Xu hướng câu hỏi theo thời gian</p>
          </div>
          <div className="flex items-center space-x-6 bg-slate-50 dark:bg-slate-700/50 px-6 py-4 rounded-2xl border border-slate-200 dark:border-slate-600">
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-indigo-500 rounded-full shadow-sm shadow-indigo-500/50"></span>
              <span className="text-xs font-bold text-slate-600 dark:text-slate-300">Tổng lượt hỏi</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="w-3 h-3 bg-teal-500 rounded-full shadow-sm shadow-teal-500/50"></span>
              <span className="text-xs font-bold text-slate-600 dark:text-slate-300">Đã giải quyết</span>
            </div>
          </div>
        </div>

        <div className="h-[450px] w-full relative z-10">
          {isLoading ? (
            <div className="h-full w-full flex flex-col items-center justify-center">
              <div className="w-20 h-20 bg-indigo-50 dark:bg-indigo-900/30 rounded-full flex items-center justify-center animate-bounce mb-4">
                 <i className="fa-solid fa-robot text-indigo-500 text-3xl"></i>
              </div>
              <p className="text-base font-bold text-slate-500 dark:text-slate-400 animate-pulse">Đang phân tích dữ liệu...</p>
            </div>
          ) : stats.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorQueries" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.4}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorSolved" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#14b8a6" stopOpacity={0.4}/>
                    <stop offset="95%" stopColor="#14b8a6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                {/* Dynamic grid color via CSS var or simple toggle, here using a darker stroke for dark mode context */}
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={document.documentElement.classList.contains('dark') ? '#334155' : '#e2e8f0'} />
                <XAxis 
                  dataKey="label" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} 
                  dy={15} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} 
                />
                <Tooltip 
                  cursor={{stroke: '#94a3b8', strokeWidth: 2, strokeDasharray: '4 4'}}
                  contentStyle={{ 
                    borderRadius: '16px', 
                    border: 'none', 
                    boxShadow: '0 10px 25px -5px rgba(0,0,0,0.2)', 
                    padding: '16px 20px',
                    fontWeight: 700,
                    fontSize: '14px',
                    backgroundColor: '#1e293b',
                    color: '#f8fafc'
                  }}
                  itemStyle={{ paddingBottom: '4px' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="queries" 
                  name="Tổng lượt hỏi"
                  stroke="#6366f1" 
                  fillOpacity={1} 
                  fill="url(#colorQueries)" 
                  strokeWidth={5} 
                  activeDot={{r: 8, strokeWidth: 4, stroke:'#fff', fill: '#4f46e5'}} 
                />
                <Area 
                  type="monotone" 
                  dataKey="solved" 
                  name="Đã giải quyết"
                  stroke="#14b8a6" 
                  fillOpacity={1} 
                  fill="url(#colorSolved)" 
                  strokeWidth={5} 
                  activeDot={{r: 8, strokeWidth: 4, stroke:'#fff', fill: '#0d9488'}}
                />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 dark:text-slate-600">
               <div className="w-24 h-24 bg-slate-100 dark:bg-slate-700 rounded-full flex items-center justify-center mb-6">
                 <i className="fa-solid fa-chart-line text-4xl text-slate-400 dark:text-slate-500"></i>
               </div>
               <p className="text-xl font-bold">Chưa có dữ liệu nào</p>
               <p className="text-base mt-2">Hệ thống sẽ hiển thị biểu đồ khi có tương tác.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { WidgetSettings, PluginConfig, User } from '../types';
import { apiService } from '../services/apiService';

interface Props {
  settings: WidgetSettings;
  setSettings: (s: WidgetSettings) => void;
  user: User;
  onConfigSave?: () => void;
}

const WidgetConfig: React.FC<Props> = ({ settings, setSettings, user, onConfigSave }) => {
  const [activeTab, setActiveTab] = useState<'appearance' | 'plugins'>('appearance');

  // Plugin State Management
  const [plugins, setPlugins] = useState<PluginConfig>({
      autoOpen: { enabled: false, delay: 5 },
      social: { enabled: false, zalo: '', phone: '' },
      leadForm: { enabled: false, title: 'Để lại thông tin để được tư vấn nhé!', trigger: 'manual' }
  });

  // Auto-save State
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<number | null>(null);
  const isFirstLoad = useRef(true);

  // Load Plugins on Mount
  useEffect(() => {
    const loadPlugins = async () => {
        const data = await apiService.getPlugins(user.id);
        setPlugins(data);
        isFirstLoad.current = false;
    };
    loadPlugins();
  }, [user.id]);

  // Auto-save logic for Plugins
  useEffect(() => {
      if (isFirstLoad.current) return;

      setIsSaving(true);
      const timer = setTimeout(async () => {
          await apiService.updatePlugins(user.id, plugins);
          setIsSaving(false);
          setLastSaved(Date.now());
          if (onConfigSave) onConfigSave();
      }, 500); // Reduced debounce to 500ms for snappier feel

      return () => clearTimeout(timer);
  }, [plugins, user.id]);

  return (
    <div className="max-w-4xl mx-auto pb-12">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-8">
          <div className="flex-1">
              <h2 className="text-3xl font-black text-slate-800 dark:text-white mb-2 flex items-center gap-3">
                  <span className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-500 dark:text-indigo-300 rounded-2xl flex items-center justify-center text-xl shadow-sm -rotate-6 border-2 border-indigo-200 dark:border-indigo-800 shrink-0">
                  <i className="fa-solid fa-sliders"></i>
                  </span>
                  Cấu hình Widget
              </h2>
              <div className="flex items-center gap-3">
                  <p className="text-slate-600 dark:text-slate-400 font-bold ml-1">Thay đổi sẽ được cập nhật trực tiếp.</p>
                  {isSaving ? (
                      <span className="text-xs font-bold text-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-full flex items-center gap-1">
                          <i className="fa-solid fa-circle-notch animate-spin"></i> Đang lưu...
                      </span>
                  ) : lastSaved ? (
                      <span className="text-xs font-bold text-emerald-500 bg-emerald-50 dark:bg-emerald-900/30 px-2 py-1 rounded-full flex items-center gap-1 animate-in fade-in">
                          <i className="fa-solid fa-check"></i> Đã lưu
                      </span>
                  ) : null}
              </div>
          </div>
      </div>

      {/* Tabs */}
      <div className="bg-white dark:bg-slate-800 p-2 rounded-2xl flex font-bold text-sm shadow-sm border border-slate-200 dark:border-slate-700 mb-8">
          <button 
              onClick={() => setActiveTab('appearance')}
              className={`flex-1 py-3 rounded-xl transition-all flex items-center justify-center gap-2 ${activeTab === 'appearance' ? 'bg-indigo-50 dark:bg-slate-700 text-indigo-600 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
          >
              <i className="fa-solid fa-paint-roller"></i> Giao diện
          </button>
          <button 
              onClick={() => setActiveTab('plugins')}
              className={`flex-1 py-3 rounded-xl transition-all flex items-center justify-center gap-2 ${activeTab === 'plugins' ? 'bg-pink-50 dark:bg-slate-700 text-pink-600 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
          >
              <i className="fa-solid fa-puzzle-piece"></i> Tiện ích
          </button>
      </div>

      {/* Content Area */}
      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-700 overflow-hidden relative">

          {/* Live Preview Hint */}
          <div className="absolute top-6 right-6 z-10 hidden lg:block animate-bounce-slow">
              <div className="bg-slate-800 text-white text-xs font-bold px-3 py-1.5 rounded-full shadow-lg flex items-center gap-2 opacity-80">
                  Nhìn xuống dưới kia kìa 
                  <i className={`fa-solid fa-arrow-right-long transform ${settings.position === 'right' ? 'rotate-45' : 'rotate-[135deg]'}`}></i>
              </div>
          </div>

          <div className="p-8">
            {/* Tab Content: Appearance */}
            {activeTab === 'appearance' && (
                <div className="space-y-10 animate-in fade-in slide-in-from-left-4 duration-300">

                    {/* Color Picker */}
                    <div className="space-y-4">
                        <label className="block text-sm font-extrabold text-slate-500 dark:text-slate-400 uppercase ml-1">Màu sắc chủ đạo</label>
                        <div className="flex flex-wrap gap-4">
                        {['#6366f1', '#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#1e293b'].map(color => (
                            <button 
                            key={color}
                            onClick={() => setSettings({ ...settings, primaryColor: color })}
                            className={`w-14 h-14 rounded-full border-4 transition-all shadow-sm flex items-center justify-center ${settings.primaryColor === color ? 'border-slate-200 dark:border-slate-600 scale-110 shadow-lg ring-4 ring-offset-2 ring-indigo-200 dark:ring-indigo-900' : 'border-white dark:border-slate-700 hover:scale-105'}`}
                            style={{ backgroundColor: color }}
                            >
                            {settings.primaryColor === color && <i className="fa-solid fa-check text-white text-xl"></i>}
                            </button>
                        ))}
                        </div>
                    </div>

